	DECLARE v_eot DATE = EXT.LIB_CONSTANTES:v_eot; 
	DECLARE v_PeriodSeq BIGINT;
	DECLARE v_PeriodName VARCHAR(255);
	DECLARE v_PeriodStartDate TIMESTAMP;
    DECLARE v_PeriodEndDate TIMESTAMP;
	DECLARE v_fechaliquidacion VARCHAR(6);
	DECLARE v_const_out_batch_control_load INTEGER := EXT.LIB_CONSTANTES:CONST_OUT_BATCH_CONTROL_LOAD;
	DECLARE v_const_out_batch_control_ok INTEGER := EXT.LIB_CONSTANTES:CONST_OUT_BATCH_CONTROL_OK;
	DECLARE v_const_out_batch_control_error INTEGER := EXT.LIB_CONSTANTES:CONST_OUT_BATCH_CONTROL_ERROR;
	DECLARE v_file_name VARCHAR(10) := 'REPEXT_PRD';
	DECLARE v_calendarName VARCHAR(25) := 'Main Monthly Calendar';
	DECLARE v_caracter_unicode_49824 VARCHAR(5) := '힀';
	DECLARE v_suma_pagos DECIMAL(15,2) := 0;
	DECLARE v_existe_tabla INTEGER := 0;
	
	DECLARE v_DesError    VARCHAR(2000):='';
	DECLARE v_offset INT;
	
	DECLARE v_position VARCHAR(2000) := '';
    DECLARE v_ramo VARCHAR(2000) := '';
    DECLARE v_permanencia VARCHAR(2000) := '';
    DECLARE v_tipo_concepto VARCHAR(2000) := '';

    --Variables de control para la ejecucion.
    DECLARE v_num_post BIGINT := 0;
    DECLARE v_seq_ultimo_post BIGINT := 0;
    DECLARE v_fecha_reparto DATETIME;
    DECLARE v_existe_control_reparto INTEGER := 0;
    DECLARE v_control_reparto_estado BIGINT := 0;
    DECLARE v_control_reparto_post_lc_seq BIGINT := 0;
    DECLARE v_control_reparto_post_cierre_seq BIGINT := 0;
    DECLARE v_primera_ejec_LC INTEGER := 0;
    
    
    DECLARE v_total_filas_C_POSITION_DDEE BIGINT := 0;
    DECLARE v_fila_C_POSITION_DDEE BIGINT := 0;
    
    --TABLA TEMPORAL C_POSITION_DDEE
    DECLARE v_c_position_ddee_tipo_liq VARCHAR(255);
    DECLARE v_c_position_ddee_tipo_documento VARCHAR(1);
    DECLARE v_c_position_ddee_importe DECIMAL(15,2);
    DECLARE v_c_position_ddee_manager_pos_prin VARCHAR(255);
    DECLARE v_c_position_ddee_nif VARCHAR(255);
    DECLARE v_c_position_ddee_pos_prin VARCHAR(255);
    DECLARE v_c_position_ddee_pos_callidus VARCHAR(255);
    DECLARE v_c_position_ddee_earninggroupid VARCHAR(255);
    DECLARE v_c_position_ddee_earningcodeid VARCHAR(255);
    DECLARE v_c_position_ddee_positionseq BIGINT;
    DECLARE v_c_position_ddee_participantseq BIGINT;
    
    DECLARE v_importe_directo DECIMAL(15,2);
    DECLARE v_dif_importe_directo DECIMAL(15,2);
    
    DECLARE v_insert_repext_temporal NCLOB := '';
    
    ---Nueva variable para controlar que el tramo2 se calcule como el 1 cuando el 1 se haya calculado como oficina (1), reginal (2)  o compania (3)
    DECLARE v_existe_base_reparto_tramo1 INT := 0;
    DECLARE v_regional VARCHAR(4);
    
    --CONSTANTES ERROR
    DECLARE c_correccion_error VARCHAR(250) := 'CORRECCION_NO_DATA_FOUND';


    --TABLA TEMPORAL
    DECLARE v_control_reparto TABLE (
        "FECHA_BAJA" LONGDATE ,
	    "FECHA_ALTA" LONGDATE ,
	    "ESTADO" BIGINT ,
	    "POST_LC_SEQ" BIGINT ,
	    "POST_CIERRE_SEQ" BIGINT ,
	    "FECHA_CARGO" VARCHAR(8),
	    "PERIODSEQ" BIGINT 
    );
    
    DECLARE TEMP_REPEXT_PAGOS_REPARTO_FILE TABLE (
    	"PORCENTAJE_TRAMO2" DECIMAL(15, 2),
		"TIPO_BASE_TRAMO2" VARCHAR(3),
		"PORCENTAJE_TRAMO1" DECIMAL(15, 2),
		"TIPO_BASE_TRAMO1" VARCHAR(3),
		"NOMBRE_PERIODO" VARCHAR(2),
		"TIPO_REPARTO" VARCHAR(255),
		"CIA_CODIGO" VARCHAR(2),
		"ESTADO_REPARTO" BIGINT,
		"TIPO_DOCUMENTO" VARCHAR(1),
		"EARNINGGROUPID" VARCHAR(255),
		"EARNINGCODEID" VARCHAR(255),
		"IMPORTE" DECIMAL(15, 2),
		"DEPOSITSEQ" BIGINT,
		"DEPOSITO" VARCHAR(255),
		"TIPO_PAGO" VARCHAR(255),
		"PROGRAMA" VARCHAR(255),
		"NIF" VARCHAR(255),
		"TIPO_AGENTE" DECIMAL(5, 2),
		"FECHA_CARGO" VARCHAR(6),
		"MANAGER_POS_PRIN" VARCHAR(255),
		"POS_PRIN" VARCHAR(255),
		"POS_CALLIDUS" VARCHAR(255),
		"PERIODSEQ" BIGINT,
		"POSITIONSEQ" BIGINT ,
		"PARTICIPANTSEQ" BIGINT,
		"PRODUCTO_HASTA" BIGINT,
		"PRODUCTO_DESDE" BIGINT,
		"COEF_CORRECTOR_TRAMO2" DECIMAL(15, 2),
		"COEF_TIPO_BASE_TRAMO2" VARCHAR(3),
		"COEF_CORRECTOR_TRAMO1" DECIMAL(15, 2),
		"COEF_TIPO_BASE_TRAMO1" VARCHAR(3)
    );
    
    DECLARE TEMP_REPEXT_FILE TABLE (
    	"TIPO_LIQ" VARCHAR(255),
		"COEF_CORRECTOR" DECIMAL(5, 2),
		"COEF_TIPO_BASE" VARCHAR(3),
		"PRIMA_COMIS" DECIMAL(25, 10),
