		"TIPO_DOCUMENTO" VARCHAR(1),
		"EARNINGGROUPID" VARCHAR(255),
		"EARNINGCODEID" VARCHAR(255),
		"IMPORTE_PAGO" DECIMAL(15, 2),
		"DEPOSITSEQ" BIGINT,
		"DEPOSITO" VARCHAR(255),
		"TIPO_PAGO" VARCHAR(255),
		"PROGRAMA" VARCHAR(255),
		"ESTADO" VARCHAR(255),
		"COMPENSATIONDATE" LONGDATE,
		"CODIGO_POLIZA" VARCHAR(255),
		"PRODUCTID" VARCHAR(127),
		"EVENTTYPEID" VARCHAR(40),
		"SUBLINENUMBER" BIGINT,
		"LINENUMBER" BIGINT,
