			INNER JOIN :TEMP_FINAL_PAGOS_BASES_102_03_RT T ON F.PERIODSEQ = T.PERIODSEQ AND F.POS_PRIN = T.POS_PRIN
			AND F.TIPO_DOCUMENTO = T.TIPO_DOCUMENTO AND F.DEPOSITSEQ = T.DEPOSITSEQ
