                                NULL AS COEF_TIPO_BASE,
                                NULL AS COEF_CORRECTOR,
                                COD_AGENTE,
                                P.TIPO_LIQ
    					FROM :TEMP_PAGOS_DIRECTOS_123_126_127_01_RT P
