		--SELECT 'TEMP_PAGOS_DIRECTOS_RT',* FROM :TEMP_PAGOS_DIRECTOS_RT;
    
    -- PAGOS GROUPID: NOT 03-RG
    TEMP_PAGOS_DIRECTOS_RG = SELECT *
