    	CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM TEMP_BASES_2_82_03_RG_MACB38P ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
			--SELECT 'TEMP_BASES_2_82_03_RG_MACB38P',* FROM :TEMP_BASES_2_82_03_RG_MACB38P;	
		
