*/
			
		--FINAL
    	TEMP_FINAL_PAGOS_BASES_2_82_RT_MACB38P = SELECT P.PARTICIPANTSEQ,
                                P.POSITIONSEQ,
                                P.PERIODSEQ,
                                :v_periodName AS PERIODO,
                                P.POS_CALLIDUS POSITIONNAME,
