		FROM EXT.FINAL_REPEXT_PAGOS_FILE F
		INNER JOIN :TEMP_FINAL_PAGOS_BASES_2_MAC38P_RT T ON F.PERIODSEQ = T.PERIODSEQ AND F.POS_PRIN = T.POS_PRIN
