		--SELECT 'TEMP_PAGOS_DIRECTOS_5_RT',* FROM :TEMP_PAGOS_DIRECTOS_5_RT;
    
    -- PAGOS GROUPID: NOT 03-RG
    TEMP_PAGOS_DIRECTOS_5_RG = SELECT *
