		--FINAL
    	TEMP_FINAL_PAGOS_BASES_5_03_RG_MACB38P = SELECT P.PARTICIPANTSEQ,
                                P.POSITIONSEQ,
                                P.PERIODSEQ,
                                :v_periodName AS PERIODO,
                                P.POS_CALLIDUS POSITIONNAME,
                                P.POS_PRIN,
                                P.NIF,
                                P.MANAGER_POS_PRIN,
                                ORDERID,
                                LINENUMBER,
                                SUBLINENUMBER,
                                EVENTTYPEID,
                                PRODUCTID,
                                CODIGO_POLIZA,
                                COMPENSATIONDATE,
                                ESTADO,
                                P.PROGRAMA,
                                P.TIPO_PAGO,
                                P.DEPOSITO,
                                P.DEPOSITSEQ,
                                P.IMPORTE IMPORTE_PAGO,
                                P.EARNINGCODEID,
                                P.EARNINGGROUPID,
                                P.TIPO_DOCUMENTO,
                                P.TIPO_AGENTE,
                                B.IMPORTE_COMISION AS IMPORTE,
                                (SELECT SUM(IMPORTE_COMISION)
