			FROM :TEMP_REPEXT_PAGOS_REPARTO_FILE F
			INNER JOIN :TEMP_FINAL_PAGOS_BASES_5_RT T ON F.PERIODSEQ = T.PERIODSEQ AND F.POS_PRIN = T.POS_PRIN
