                                LINENUMBER,
                                SUBLINENUMBER,
                                EVENTTYPEID,
                                PRODUCTID,
                                CODIGO_POLIZA,
                                COMPENSATIONDATE,
                                ESTADO,
                                P.PROGRAMA,
                                P.TIPO_PAGO,
                                P.DEPOSITO,
                                P.DEPOSITSEQ,
                                P.IMPORTE IMPORTE_PAGO,
                                P.EARNINGCODEID,
                                P.EARNINGGROUPID,
                                P.TIPO_DOCUMENTO,
                                P.TIPO_AGENTE,
                                B.LOC_INSP AS IMPORTE,
                                BT.SUMA_IMPORTE AS SUMA_IMPORTE,
                                NULL AS TIPO_REPARTO,
                                0 AS NUM_TRAMO,
                                NULL AS REPARTO_TIPO_BASE,
                                NULL AS REPARTO_PORCENTAJE,
                                POLIZA_FISICA,
                                POLIZA_CORREGIDA,
                                PRIMA_CORREGIDA,
