    					INNER JOIN :TEMP_BASES_5_RG B ON P.POSITIONSEQ = B.POSITIONSEQ
    					WHERE ((B.POS_PRIN = P.POS_PRIN AND (IFNULL(B.CAMBIO_AG_INSP,'0') = '0')) OR B.MANAGER_POS_PRIN = P.POS_PRIN)
