    					;
    	CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM TEMP_FINAL_PAGOS_BASES_5_RG ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');	
    	
