		-- SELECT 'TEMP_PAGOS_DIRECTOS_X_RT',* FROM :TEMP_PAGOS_DIRECTOS_X_RT;
		
    -- PAGOS GROUPID: X-01_RT
    TEMP_PAGOS_DIRECTOS_X_01_RT = SELECT *
