		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM TEMP_PAGOS_DIRECTOS_X_01_RT ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
		
		-- SELECT 'TEMP_PAGOS_DIRECTOS_X_01_RT',* FROM :TEMP_PAGOS_DIRECTOS_X_01_RT;
    
    TEMP_PAGOS_DIRECTOS_X_01_RG = SELECT *
