	            				-- CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_POSITION PROCESADO ' || ROUND((v_cont_cursor_C_POSITION*100)/(v_total_filas_C_POSITION)*(1.0),1) || '% || C_PAGOS_DIRECTOS PROCESADO '|| (v_cont_cursor_C_PAGOS_DIRECTOS*100)/(v_total_filas_C_PAGOS_DIRECTOS)*(1.0) || '%', v_log_count, v_idproceso, 'info');
