                                ELSEIF SUBSTR(v_c_pagos_directos_earninggroupid,10,2) = 'RG' THEN
                                    v_ramo := 'AND PRODUCTID LIKE ''01%'' AND PRODUCTID NOT LIKE ''012%''';
                                        
                                END IF;
                                    
                            ELSEIF SUBSTR(v_c_pagos_directos_earninggroupid,7,2) = '03' THEN
                                IF SUBSTR(v_c_pagos_directos_earninggroupid,10,2) = 'RT' THEN
                                    v_ramo := 'AND PRODUCTID LIKE ''032%''';
                                        
                                ELSEIF SUBSTR(v_c_pagos_directos_earninggroupid,10,2) = 'RG' THEN
                                    v_ramo := 'AND PRODUCTID LIKE ''03%'' AND PRODUCTID NOT LIKE ''032%''';
                                        
                                END IF;
                                
                            ELSE
                                v_DesError := 'Grupo de Pago incorrecto: ' || v_c_pagos_directos_earninggroupid;
