                            END IF;
                            
                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Filtro por ramo: ' || v_ramo, v_log_count, v_idproceso, 'info');
                            
                            --Extraemos los filtros necesarios segun el earningcodeid, donde podemos deducir si son comisiones, diferenciales o locomocion.
                            v_DesError := 'PAGOS DIRECTOS. EARNINGCODEID';
                            
                            IF SUBSTR(v_c_pagos_directos_earningcodeid,1,1) = '1' THEN
                                
                                v_position := 'POS_PRIN = ''' || v_c_pagos_directos_pos_prin || '''';
                                
                                --Dentro de las comisiones, para cada concepto de pago computan permanencias distintas.
                                --ALM 20220401: Anadimos un like por el nombre del deposito por si no llega el programa.
                                IF v_c_pagos_directos_programa = 'MACB38P' OR v_c_pagos_directos_deposito LIKE 'D-%-Pagos-Fijos' THEN
                                    v_ramo := 'AND PRODUCTID LIKE ''%' || RIGHT(v_c_pagos_directos_earningcodeid,5) || '''
                                    AND CODIGO_POLIZA = ''' || v_c_pagos_directos_earninggroupid || ''' AND ESTADO = ''' || SUBSTR(v_c_pagos_directos_earningcodeid,1,3) || '''';
                                    v_permanencia := 'AND EVENTTYPEID = ''Pago Comercial''';
                                    v_tipo_concepto := 'IMPORTE_COMISION';
                                    
