                                    --JGE 20241003 nos llegan 43 COP, no las tenemos en cuenta para el reparto
                                    --v_permanencia := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'',''42'',''43'')';
                                    v_permanencia := 'AND (EVENTTYPEID IN (''71'',''65'',''66'',''72'',''42'')
                                        OR (EVENTTYPEID = ''43'' AND SALESTRANSACTIONSEQ IN (
