                                    v_ramo := 'AND PRODUCTID LIKE ''%' || RIGHT(v_c_pagos_directos_earningcodeid,5) || '''';
                                    v_permanencia := 'AND EVENTTYPEID = ''11''';
                                    v_tipo_concepto := 'IMPORTE_COMISION';
                                    
