                                    ELSEIF v_c_pagos_directos_deposito = 'D-O-COM-ServiciosAsistencia-Pago91' THEN
                                        v_permanencia := 'AND EVENTTYPEID = ''AS91''';
                                    ELSEIF v_c_pagos_directos_deposito = 'D-O-COM-ServiciosAsistencia-Pago110' THEN
