    								--                                v_position := '(POS_PRIN = ''' || v_c_pagos_directos_pos_prin || ''' OR MAN_ACT_POS_PRIN = ''' || v_c_pagos_directos_pos_prin || ''' OR MAN_ACT_POS_PRIN IN (
    								--SELECT DISTINCT R.POS_PRIN FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE R
