                                :v_c_pagos_directos_depositseq|| ' DEPOSITSEQ,'||
                                :v_c_pagos_directos_importe || ' IMPORTE_PAGO,'||
                                '''' || :v_c_pagos_directos_earningcodeid || ''' EARNINGCODEID,'||
                                '''' || :v_c_pagos_directos_earninggroupid || ''' EARNINGGROUPID,'||
                                '''' || :v_c_pagos_directos_tipo_documento || ''' TIPO_DOCUMENTO,'||
                                :v_c_pagos_directos_tipo_agente || ' TIPO_AGENTE,'||
                                :v_tipo_concepto || ' IMPORTE,'||
                                'NULL AS TIPO_REPARTO,'||
                                '0 AS NUM_TRAMO,'||
                                'NULL AS REPARTO_TIPO_BASE,'||
                                'NULL AS REPARTO_PORCENTAJE,'||
                                'POLIZA_FISICA,'||
                                'POLIZA_CORREGIDA,'||
                                'PRIMA_CORREGIDA,'||
                                'PRIMA_NETA,'||
                                'PRIMA_NETA_ANUAL,'||
                                'PRIMA_COMIS_S4 PRIMA_COMIS,'||
                                'NULL AS COEF_TIPO_BASE,'||
                                'NULL AS COEF_CORRECTOR,'||
                                'COD_AGENTE,'||
                                '''' || IFNULL(:v_c_pagos_directos_tipo_liq,'') || ''' TIPO_LIQ'||
                                ' FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE B ' ||
                                ' WHERE ' || :v_position || 
                                ' AND PERIODSEQ = ' || :v_c_pagos_directos_periodseq || ' ' ||
                                :v_ramo || ' ' ||
                                :v_permanencia ||  
                                ' AND ' || :v_tipo_concepto || ' <> 0 '||
								' AND (ORDERID,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) NOT IN ( ' ||
                                    ' SELECT X.ORDERID,X.LINENUMBER,X.SUBLINENUMBER,X.EVENTTYPEID FROM EXT.FINAL_REPEXT_FILE X '||
                                    ' WHERE X.POS_PRIN = ''' || :v_c_pagos_directos_pos_prin || '''' ||
                                       ' AND X.PERIODSEQ = ' || :v_c_pagos_directos_periodseq || 
                                       ' AND X.EARNINGCODEID = ''' || :v_c_pagos_directos_earningcodeid || '''' ||
                                       ' AND X.EARNINGGROUPID = ''' || :v_c_pagos_directos_earninggroupid || '''' ||
                                       ' AND X.TIPO_DOCUMENTO = ''' || :v_c_pagos_directos_tipo_documento || ''' )'
                       
										;

                            
                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_insert_repext_temporal, v_log_count, v_idproceso, 'info');
              --              INSERT INTO EXT.TEMP_REPEXT_FILE_DEBUG SELECT * FROM EXT.TEMP_REPEXT_FILE;
			--		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-2 TEMP_REPEXT_FILE_DEBUG. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
	--				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-2 variables: v_c_pagos_directos_programa: ' || v_c_pagos_directos_programa 
      --                         || ', v_c_pagos_directos_tipo_pago: ' || v_c_pagos_directos_tipo_pago  
        --                       || ', v_c_pagos_directos_deposito: ' || v_c_pagos_directos_deposito
        --                        || ', v_c_pagos_directos_depositseq: ' || v_c_pagos_directos_depositseq
          --                      || ', v_c_pagos_directos_importe: ' || v_c_pagos_directos_importe
          --                      || ', v_c_pagos_directos_earningcodeid: ' || v_c_pagos_directos_earningcodeid
            --                    || ', v_c_pagos_directos_earninggroupid: ' || v_c_pagos_directos_earninggroupid
              --                  || ', v_c_pagos_directos_tipo_documento: ' || v_c_pagos_directos_tipo_documento
                --                || ', v_c_pagos_directos_tipo_agente: ' || v_c_pagos_directos_tipo_agente
                  --              || ', v_tipo_concepto: ' || v_tipo_concepto
                    --            || ', v_c_pagos_directos_tipo_liq: ' || v_c_pagos_directos_tipo_liq
					--			|| ', v_position :' || v_position
                      --          || ', v_ramo: ' || v_ramo
                        --        || ', v_permanencia: ' || v_permanencia
                          --      || ', v_tipo_concepto: ' || v_tipo_concepto
							--	|| ', v_c_pagos_directos_pos_prin :' || v_c_pagos_directos_pos_prin, v_log_count, v_idproceso, 'info');
					
					
							BEGIN
    							DECLARE EXIT HANDLER FOR SQLEXCEPTION
    							BEGIN
    							    -- Aquí defines qué hacer si ocurre un error SQL
    							    SELECT '**************Error atrapado en el handler' AS MENSAJE,v_insert_repext_temporal FROM DUMMY;
    							END;

								 -- Código principal
								-- SELECT v_insert_repext_temporal FROM DUMMY;
                            	EXECUTE IMMEDIATE v_insert_repext_temporal;
							END;
                  
                            
                            -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-2 TEMP_REPEXT_FILE. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                            COMMIT;
                            
                            --JGE 20230117 INICIO Implementacion nueva funcionalidad para el reparto de LC 
                            
                            IF v_num_post > 1 THEN 
                            
                                SELECT SUM(P.IMPORTE) INTO v_suma_pagos  FROM EXT.FINAL_REPEXT_PAGOS_FILE P 
                                WHERE P.PERIODSEQ = v_periodSeq 
                                AND P.POS_PRIN = v_c_position_pos_prin
                                AND P.EARNINGGROUPID = v_c_pagos_directos_earninggroupid 
                                AND P.EARNINGCODEID = v_c_pagos_directos_earningcodeid 
                                AND P.DEPOSITO = v_c_pagos_directos_deposito
                                --JGE 20230505 se añade nuevo campo TIPO_LIQ para dejar fuera a los balances y mejorar la LC
                                AND P.TIPO_LIQ IN ('CIERRE', 'LC');
                                       
                                --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Suma pagos LC: ' || v_suma_pagos, v_log_count, v_idproceso, 'info');          
                                  
                                IF v_suma_pagos <> v_c_pagos_directos_importe  THEN                            
                                    
                                    --Se insertan en la temporal los importes en negativos del cierre y se le cambia el signo. Se hace de esta manera para no updatear la tabla y cambiar todos los importes.
                                    INSERT INTO EXT.TEMP_REPEXT_FILE (
	    					"PARTICIPANTSEQ","POSITIONSEQ","PERIODSEQ","PERIODO","POSITIONNAME","POS_PRIN","NIF","MANAGER_POS_PRIN","ORDERID","LINENUMBER","SUBLINENUMBER","EVENTTYPEID","PRODUCTID","CODIGO_POLIZA","COMPENSATIONDATE",
	    					"ESTADO","PROGRAMA","TIPO_PAGO","DEPOSITO","DEPOSITSEQ","IMPORTE_PAGO","EARNINGCODEID","EARNINGGROUPID","TIPO_DOCUMENTO","TIPO_AGENTE","IMPORTE","TIPO_REPARTO","NUM_TRAMO","REPARTO_TIPO_BASE","REPARTO_PORCENTAJE",
	    					"POLIZA_FISICA","POLIZA_CORREGIDA","PRIMA_CORREGIDA","PRIMA_NETA","PRIMA_NETA_ANUAL","PRIMA_COMIS","COEF_TIPO_BASE","COEF_CORRECTOR","COD_AGENTE","TIPO_LIQ")
                                    SELECT F.PARTICIPANTSEQ, F.POSITIONSEQ, F.PERIODSEQ, F.PERIODO, F.POSITIONNAME, F.POS_PRIN, F.NIF, F.MANAGER_POS_PRIN,    
                                    F.ORDERID, F.LINENUMBER,    F.SUBLINENUMBER,    F.EVENTTYPEID,    F.PRODUCTID,    F.CODIGO_POLIZA,    F.COMPENSATIONDATE,    
                                    F.ESTADO,   F.PROGRAMA,    F.TIPO_PAGO,    F.DEPOSITO,    v_c_pagos_directos_depositseq,    v_c_pagos_directos_importe,    F.EARNINGCODEID,    F.EARNINGGROUPID,
                                    v_c_pagos_directos_tipo_documento, F.TIPO_AGENTE, F.IMPORTE*(-1), F.TIPO_REPARTO,    F.NUM_TRAMO,    F.REPARTO_TIPO_BASE,    F.REPARTO_PORCENTAJE,    
                                    F.POLIZA_FISICA,    F.POLIZA_CORREGIDA,    F.PRIMA_CORREGIDA,    F.PRIMA_NETA,    F.PRIMA_NETA_ANUAL,    F.PRIMA_COMIS,    F.COEF_TIPO_BASE,   
                                    F.COEF_CORRECTOR,    F.COD_AGENTE, F.TIPO_LIQ
                                    FROM EXT.FINAL_REPEXT_FILE F
                                    WHERE F.PERIODSEQ = v_periodSeq 
                                    AND F.POS_PRIN = v_c_position_pos_prin
                                    AND F.EARNINGGROUPID = v_c_pagos_directos_earninggroupid 
                                    AND F.EARNINGCODEID = v_c_pagos_directos_earningcodeid 
                                    AND F.DEPOSITO = v_c_pagos_directos_deposito
                                    --JGE 20230505 se añade nuevo campo TIPO_LIQ para dejar fuera a los balances y mejorar la LC
                                    AND F.TIPO_LIQ IN ('CIERRE', 'LC');
	-- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-3 TEMP_REPEXT_FILE. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
--	INSERT INTO EXT.TEMP_REPEXT_FILE_DEBUG SELECT * FROM EXT.TEMP_REPEXT_FILE;
--					CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-3 TEMP_REPEXT_FILE_DEBUG. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                                    
                                    -- COMMIT;
                                     
                                END IF;
                            END IF;
                            --JGE 20230117 FIN de la nueva implementacion
	
                            --Comprobaciones para cuadrar importes.
                            v_DesError := 'PAGOS DIRECTOS. COMPROBACION IMPORTES';
                            
                            --ALM 20211210: No usamos IFNULL aqui sino en la resta de la diferencia.
                            --SELECT IFNULL(SUM(IMPORTE),0) INTO v_importe_directo
                            SELECT SUM(IMPORTE) INTO v_importe_directo
                            FROM EXT.TEMP_REPEXT_FILE;
                    
                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe DIF: ' || v_dif_importe_directo, v_log_count, v_idproceso, 'info');                            
                            --v_dif_importe_directo := v_c_pagos_directos_importe - v_importe_directo;
                            v_dif_importe_directo := v_c_pagos_directos_importe - IFNULL(v_importe_directo,0);
                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe Pago: ' || v_c_pagos_directos_importe, v_log_count, v_idproceso, 'info');
                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe Detalle sumado: ' || IFNULL(v_importe_directo,0), v_log_count, v_idproceso, 'info');
                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Diferencia Importe: ' || v_dif_importe_directo, v_log_count, v_idproceso, 'info');
                            
                            IF v_dif_importe_directo = 0 THEN
                                
                                UPDATE EXT.FINAL_REPEXT_PAGOS_FILE
                                SET ESTADO_REPARTO = 2 --REPARTO CORRECTO
                                WHERE PERIODSEQ = v_periodSeq
                                    AND POS_PRIN = v_c_pagos_directos_pos_prin
                                    --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                    AND TIPO_DOCUMENTO = v_c_pagos_directos_tipo_documento
                                    AND DEPOSITSEQ = v_c_pagos_directos_depositseq;
                                        
                                COMMIT;
                                
                                --Actualizamos tambien en la tabla de pagos por reparto para que no se tenga en cuenta en el loop de repartos.
                                UPDATE :TEMP_REPEXT_PAGOS_REPARTO_FILE
                                SET ESTADO_REPARTO = 2 --REPARTO CORRECTO
                                WHERE POS_PRIN = v_c_pagos_directos_pos_prin
                                    --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                    AND TIPO_DOCUMENTO = v_c_pagos_directos_tipo_documento
                                    --ALM 20211201: Usamos el nuevo campo DEPOSITSEQ que hace unicos los pagos.
                                    --AND EARNINGCODEID = v_c_pagos_directos_earningcodeid
                                    --AND EARNINGGROUPID = v_c_pagos_directos_earninggroupid
                                    --AND PROGRAMA = v_c_pagos_directos_programa
                                    --AND TIPO_PAGO = v_c_pagos_directos_tipo_pago
                                    ----ALM 20211123: Anadimos la union por importe por si hay balances con los mismos campos. Ej: 0889000218 en agosto 2021.
                                    --AND IMPORTE = v_c_pagos_directos_importe;
                                    AND DEPOSITSEQ = v_c_pagos_directos_depositseq;
                                        
                                COMMIT;
                            
                                --Insertamos los importes repartidos sobre la tabla final.
                                INSERT INTO EXT.FINAL_REPEXT_FILE("TIPO_LIQ","COD_AGENTE","COEF_CORRECTOR","COEF_TIPO_BASE","PRIMA_COMIS","PRIMA_NETA_ANUAL","PRIMA_NETA","PRIMA_CORREGIDA"
                                ,"POLIZA_CORREGIDA","POLIZA_FISICA","REPARTO_PORCENTAJE","REPARTO_TIPO_BASE","NUM_TRAMO","TIPO_REPARTO","IMPORTE","TIPO_AGENTE","TIPO_DOCUMENTO","EARNINGGROUPID"
                                ,"EARNINGCODEID","IMPORTE_PAGO","DEPOSITSEQ","DEPOSITO","TIPO_PAGO","PROGRAMA","ESTADO","COMPENSATIONDATE","CODIGO_POLIZA","PRODUCTID","EVENTTYPEID","SUBLINENUMBER"
                                ,"LINENUMBER","ORDERID","MANAGER_POS_PRIN","NIF","POS_PRIN","POSITIONNAME","PERIODO","PERIODSEQ","POSITIONSEQ","PARTICIPANTSEQ")
                                    SELECT "TIPO_LIQ","COD_AGENTE","COEF_CORRECTOR","COEF_TIPO_BASE","PRIMA_COMIS","PRIMA_NETA_ANUAL","PRIMA_NETA","PRIMA_CORREGIDA"
                                		,"POLIZA_CORREGIDA","POLIZA_FISICA","REPARTO_PORCENTAJE","REPARTO_TIPO_BASE","NUM_TRAMO","TIPO_REPARTO","IMPORTE","TIPO_AGENTE","TIPO_DOCUMENTO","EARNINGGROUPID"
                                		,"EARNINGCODEID","IMPORTE_PAGO","DEPOSITSEQ","DEPOSITO","TIPO_PAGO","PROGRAMA","ESTADO","COMPENSATIONDATE","CODIGO_POLIZA","PRODUCTID","EVENTTYPEID","SUBLINENUMBER"
                                		,"LINENUMBER","ORDERID","MANAGER_POS_PRIN","NIF","POS_PRIN","POSITIONNAME","PERIODO","PERIODSEQ","POSITIONSEQ","PARTICIPANTSEQ"
                                    FROM EXT.TEMP_REPEXT_FILE;
                                
                                COMMIT;
                                
                            --ALM 20211126: Modificamos el rango de redondeo de 1 a 2 euros porque hay position que se desvian demasiado en el redondeo. Ej: 0559003000 en agosto 2021.
                            --ELSEIF v_dif_importe_directo BETWEEN -1 AND 1 THEN
                            --ALM 20211210: Incluimos la comprobacion de que el importe en la tabla temporal v_importe_directo sea distinto de nulo.
                            --ELSEIF v_dif_importe_directo BETWEEN -2 AND 2 THEN
                            ELSEIF (v_dif_importe_directo BETWEEN -2 AND 2) AND v_importe_directo IS NOT NULL THEN
                                
                                --Actualizamos en la tabla temporal el ultimo importe repartido para ajustar la diferencia
                                -- UPDATE :TEMP_REPEXT_FILE
                                -- --BUSCAR LA MEJOR FORMA DE REDONDEAR
                                -- --SET IMPORTE = ROUND(TRUNC(v_importe_directo,2),2) + v_dif_importe_directo
                                -- SET IMPORTE = IMPORTE + v_dif_importe_directo
                                -- WHERE ROWNUM = 1;
                                
								UPDATE TOP 1 EXT.TEMP_REPEXT_FILE
								SET IMPORTE = IMPORTE + :v_dif_importe_directo
								;
								
								
								/* -- LFC: 20251204
								UPDATE EXT.TEMP_REPEXT_FILE
									SET IMPORTE = IMPORTE + :v_dif_importe_directo
								WHERE PERIODSEQ IN (
								    SELECT TOP 1 PERIODSEQ
								    FROM EXT.TEMP_REPEXT_FILE
								    ORDER BY PERIODSEQ
								);*/
                                COMMIT;
                                
                                UPDATE EXT.FINAL_REPEXT_PAGOS_FILE
                                SET ESTADO_REPARTO = 3 --REPARTO CASI CORRECTO
                                WHERE PERIODSEQ = v_periodSeq
                                    AND POS_PRIN = v_c_pagos_directos_pos_prin
                                    --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                    AND TIPO_DOCUMENTO = v_c_pagos_directos_tipo_documento
                                    AND DEPOSITSEQ = v_c_pagos_directos_depositseq;
                                
                                COMMIT;
                                
                                --Actualizamos tambien en la tabla de pagos por reparto para que no se tenga en cuenta en el loop de repartos.
                                UPDATE :TEMP_REPEXT_PAGOS_REPARTO_FILE
                                SET ESTADO_REPARTO = 3 --REPARTO CASI CORRECTO
                                WHERE POS_PRIN = v_c_pagos_directos_pos_prin
                                    --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                    AND TIPO_DOCUMENTO = v_c_pagos_directos_tipo_documento
                                    --ALM 20211201: Usamos el nuevo campo DEPOSITSEQ que hace unicos los pagos.
                                    --AND EARNINGCODEID = v_c_pagos_directos_earningcodeid
                                    --AND EARNINGGROUPID = v_c_pagos_directos_earninggroupid
                                    --AND PROGRAMA = v_c_pagos_directos_programa
                                    --AND TIPO_PAGO = v_c_pagos_directos_tipo_pago
                                    ----ALM 20211123: Anadimos la union por importe por si hay balances con los mismos campos. Ej: 0889000218 en agosto 2021.
                                    --AND IMPORTE = v_c_pagos_directos_importe;
                                    AND DEPOSITSEQ = v_c_pagos_directos_depositseq;
                                        
                                COMMIT;
                            
                                --Insertamos los importes repartidos sobre la tabla final.
                                INSERT INTO EXT.FINAL_REPEXT_FILE("TIPO_LIQ","COD_AGENTE","COEF_CORRECTOR","COEF_TIPO_BASE","PRIMA_COMIS","PRIMA_NETA_ANUAL","PRIMA_NETA","PRIMA_CORREGIDA"
                                ,"POLIZA_CORREGIDA","POLIZA_FISICA","REPARTO_PORCENTAJE","REPARTO_TIPO_BASE","NUM_TRAMO","TIPO_REPARTO","IMPORTE","TIPO_AGENTE","TIPO_DOCUMENTO","EARNINGGROUPID"
                                ,"EARNINGCODEID","IMPORTE_PAGO","DEPOSITSEQ","DEPOSITO","TIPO_PAGO","PROGRAMA","ESTADO","COMPENSATIONDATE","CODIGO_POLIZA","PRODUCTID","EVENTTYPEID","SUBLINENUMBER"
                                ,"LINENUMBER","ORDERID","MANAGER_POS_PRIN","NIF","POS_PRIN","POSITIONNAME","PERIODO","PERIODSEQ","POSITIONSEQ","PARTICIPANTSEQ")
                                    SELECT "TIPO_LIQ","COD_AGENTE","COEF_CORRECTOR","COEF_TIPO_BASE","PRIMA_COMIS","PRIMA_NETA_ANUAL","PRIMA_NETA","PRIMA_CORREGIDA"
                                		,"POLIZA_CORREGIDA","POLIZA_FISICA","REPARTO_PORCENTAJE","REPARTO_TIPO_BASE","NUM_TRAMO","TIPO_REPARTO","IMPORTE","TIPO_AGENTE","TIPO_DOCUMENTO","EARNINGGROUPID"
                                		,"EARNINGCODEID","IMPORTE_PAGO","DEPOSITSEQ","DEPOSITO","TIPO_PAGO","PROGRAMA","ESTADO","COMPENSATIONDATE","CODIGO_POLIZA","PRODUCTID","EVENTTYPEID","SUBLINENUMBER"
                                		,"LINENUMBER","ORDERID","MANAGER_POS_PRIN","NIF","POS_PRIN","POSITIONNAME","PERIODO","PERIODSEQ","POSITIONSEQ","PARTICIPANTSEQ"
                                    FROM EXT.TEMP_REPEXT_FILE;
                                
                                COMMIT;
                                
                            ELSE
                            
                                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'PAGOS DIRECTOS. Position: ' || IFNULL(v_c_position_pos_prin,'') || '. Reparto no cuadra (importe-reparto): ' || 
                                                                        IFNULL(v_c_pagos_directos_importe,0) || '-' || IFNULL(v_importe_directo,0), v_log_count, v_idproceso, 'info');
                                
                                
                                UPDATE EXT.FINAL_REPEXT_PAGOS_FILE
                                SET ESTADO_REPARTO = 4 --REPARTO INCORRECTO. NO CUADRA EL IMPORTE
                                WHERE PERIODSEQ = v_periodSeq
                                    AND POS_PRIN = v_c_pagos_directos_pos_prin
                                    --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                    AND TIPO_DOCUMENTO = v_c_pagos_directos_tipo_documento
                                    AND DEPOSITSEQ = v_c_pagos_directos_depositseq;
                                
                                COMMIT;
                                
                                --No Actualizamos en la tablas de pagos por reparto ya que no ha sido correcto el reparto y asi se puede repartir segun el reparto indicado.
                                --De momento lo dejamos sin comentar para hacer comprobaciones.
                                
                            
                                --NO insertamos los importes repartidos sobre la tabla final.
                                
                                
                            END IF;
                            
                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Repartos Directos.', v_log_count, v_idproceso, 'info');
                            
                        -- EXCEPTION
                        --     WHEN HAY_ERROR_LOOP THEN
                        --         CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'LOOP C_PAGOS_DIRECTOS. Position: ' || v_c_position_pos_prin || '. Error Controlado: ' || v_DesError, v_log_count, v_idproceso, 'info');
                        --     WHEN OTHERS THEN
                        --         v_DesError := 'LOOP C_PAGOS_DIRECTOS. Position: ' || v_c_position_pos_prin || '. Error: ' || v_DesError || '. SQLCOD(' || SQLCODE || ') ' ||SQLERRM;
                        --         RAISE HAY_ERROR;
                        END;
                    END FOR; --PAGOS DIRECTOS
                    
                    --Para cada una de las Position recorremos cada uno de los pagos que hay que repartir.
                    --Tratamos todos los pagos que no han sido repartidos anteriormente (pagos directos o inlcuso aquellos directos que no se han podido repartir).

if  i_par_position <> 'Todas' then
------------------------------LFC:20251202 --TABLA DEBUG PENDIENTE BORRAR
	    SELECT COUNT(1) INTO v_existe_tabla FROM SYS.TABLES WHERE TABLE_NAME = 'FINAL_REPEXT_PAGOS_FILE_3_DEBUG';
		temp_final_reparto = SELECT * FROM EXT.FINAL_REPEXT_PAGOS_FILE where periodseq = v_periodSeq;
		IF v_existe_tabla > 0 THEN
			DROP TABLE EXT.FINAL_REPEXT_PAGOS_FILE_3_DEBUG;
		END IF;
		
		CREATE TABLE EXT.FINAL_REPEXT_PAGOS_FILE_3_DEBUG AS (SELECT * FROM :temp_final_reparto);
	    CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name, 'Creada la tabla temporal FINAL_REPEXT_PAGOS_FILE_3_DEBUG' , v_log_count, v_idproceso, 'debug');
------------------------------
end if;

                    C_PAGOS =
                        SELECT DISTINCT
                            PARTICIPANTSEQ,
                            POSITIONSEQ,
                            PERIODSEQ,
                            POS_CALLIDUS,
                            POS_PRIN,
                            MANAGER_POS_PRIN,
                            TO_DATE(FECHA_CARGO || '01','YYYYMMDD') AS FECHA_CARGO,
                            TIPO_AGENTE,
                            NIF,
                            PROGRAMA,
                            TIPO_PAGO,
                            --ALM 20211201: Incluimos el campo DEPOSITSEQ para poder hacer unicos los pagos.
                            DEPOSITSEQ,
                            --ALM 20220323: Incluimos el campo DEPOSITO para poder inclirlo en la tabla final de cara a los informes.
                            DEPOSITO,
                            IMPORTE,
                            EARNINGCODEID,
                            EARNINGGROUPID,
                            --ALM 20220323: Incluimos el campo TIPO_DOCUMENTO para poder diferenciar los pagos del cierre y de la LC.
                            TIPO_DOCUMENTO,
                            CIA_CODIGO,
                            TIPO_REPARTO,
                            NOMBRE_PERIODO,
                            TIPO_BASE_TRAMO1,
                            PORCENTAJE_TRAMO1,
                            TIPO_BASE_TRAMO2,
                            PORCENTAJE_TRAMO2
                        FROM :TEMP_REPEXT_PAGOS_REPARTO_FILE
                        WHERE POS_PRIN = v_c_position_pos_prin
                        --ALM 20211122: No hace falta filtrar por los parametros de entrada porque ya solo se ejecutaban los pagos sin repartir y para la Positon que indica el bucle inicial.
                        AND ESTADO_REPARTO = 1
                        --PARA DEBUGUEAR
                        --AND TIPO_PAGO = 'RPA'
                        ORDER BY TIPO_PAGO;
                        
                    v_total_filas_C_PAGOS = RECORD_COUNT(:C_PAGOS);
                    CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_PAGOS TOTAL REGISTROS ' || v_total_filas_C_PAGOS, v_log_count, v_idproceso, 'info');   
        			-- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name, 'v_total_filas_C_PAGOS ' || v_total_filas_C_PAGOS, v_log_count, v_idproceso, 'info');
        			v_fila_C_PAGOS := 0;
                    v_cont_cursor_C_PAGOS := 0;


if  i_par_position <> 'Todas' then
------------------------------LFC:20251202 --TABLA DEBUG PENDIENTE BORRAR
	    SELECT COUNT(1) INTO v_existe_tabla FROM SYS.TABLES WHERE TABLE_NAME = 'C_PAGOS_DEBUG';
		
		IF v_existe_tabla > 0 THEN
			DROP TABLE EXT.C_PAGOS_DEBUG;
		END IF;
		
		CREATE TABLE EXT.C_PAGOS_DEBUG AS (SELECT * FROM :C_PAGOS);
	    CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name, 'Creada la tabla temporal C_PAGOS_DEBUG' , v_log_count, v_idproceso, 'debug');
------------------------------
end if;




                    
        			FOR v_fila_C_PAGOS IN 1 .. v_total_filas_C_PAGOS DO
	    			--C_PAGOS
	    			BEGIN
	    				v_offset := v_fila_C_PAGOS - 1;
	    				-- CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_PAGOS  REGISTRO ' || v_offset || ' DEL TOTAL ' || v_total_filas_C_PAGOS, v_log_count, v_idproceso, 'info');   
						 	----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	            			v_cont_cursor_C_PAGOS := v_cont_cursor_C_PAGOS + 1;
	            			IF (MOD(v_cont_cursor_C_PAGOS,100)=0 OR (v_cont_cursor_C_PAGOS = v_total_filas_C_PAGOS)) THEN
	            				CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_PAGOS REGISTRO ' || v_cont_cursor_C_PAGOS || ' DE ' || v_total_filas_C_PAGOS || ' POSITION ' || v_c_position_pos_prin || ' - PROCESADO '|| (v_cont_cursor_C_PAGOS*100)/(v_total_filas_C_PAGOS)*(1.0) || '%', v_log_count, v_idproceso, 'info');
	            				-- CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_POSITION PROCESADO ' || ROUND((v_cont_cursor_C_POSITION*100)/(v_total_filas_C_POSITION)*(1.0),1) || '% || C_PAGOS PROCESADO '|| (v_cont_cursor_C_PAGOS*100)/(v_total_filas_C_PAGOS)*(1.0) || '%', v_log_count, v_idproceso, 'info');
	            			END IF;
	            			----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	    				
	    			    SELECT PARTICIPANTSEQ,
                            POSITIONSEQ,
                            PERIODSEQ,
                            POS_CALLIDUS,
                            POS_PRIN,
                            MANAGER_POS_PRIN,
                            FECHA_CARGO,
                            TIPO_AGENTE,
                            NIF,
                            PROGRAMA,
                            TIPO_PAGO,
                            DEPOSITSEQ,
                            DEPOSITO,
                            IMPORTE,
                            EARNINGCODEID,
                            EARNINGGROUPID,
                            TIPO_DOCUMENTO,
                            CIA_CODIGO,
                            TIPO_REPARTO,
                            NOMBRE_PERIODO,
                            TIPO_BASE_TRAMO1,
                            PORCENTAJE_TRAMO1,
                            TIPO_BASE_TRAMO2,
                            PORCENTAJE_TRAMO2
	    				INTO v_c_pagos_participantseq
	    				, v_c_pagos_positionseq
	    				, v_c_pagos_periodseq
	    				, v_c_pagos_pos_callidus
	    				, v_c_pagos_pos_prin
	    				, v_c_pagos_manager_pos_prin
	    				, v_c_pagos_fecha_cargo
	    				, v_c_pagos_tipo_agente
	    				, v_c_pagos_nif
	    				, v_c_pagos_programa
	    				, v_c_pagos_tipo_pago
	    				, v_c_pagos_depositseq
	    				, v_c_pagos_deposito
	    				, v_c_pagos_importe
	    				, v_c_pagos_earningcodeid
	    				, v_c_pagos_earninggroupid
	    				, v_c_pagos_tipo_documento
	    				, v_c_pagos_cia_codigo
	    				, v_c_pagos_tipo_reparto
	    				, v_c_pagos_nombre_periodo
	    				, v_c_pagos_tipo_base_tramo1
	    				, v_c_pagos_porcentaje_tramo1
	    				, v_c_pagos_tipo_base_tramo2
	    				, v_c_pagos_porcentaje_tramo2
	    				/*v_c_pagos_earninggroupid
	    			    	, v_c_pagos_pos_prin
	    			    	, v_c_pagos_nombre_periodo
	    			    	, v_c_pagos_fecha_cargo
	    			    	, v_c_pagos_porcentaje_tramo1
	    			    	, v_c_pagos_tipo_base_tramo1
	    			    	, v_c_pagos_cia_codigo
	    			    	, v_c_pagos_porcentaje_tramo2
	    			    	, v_c_pagos_tipo_base_tramo2
	    			    	, v_c_pagos_tipo_documento
	    			    	, v_c_pagos_depositseq*/
	    			    	--v_c_pagos_directos_tipo_liq, v_c_pagos_directos_deposito, v_c_pagos_directos_tipo_documento, v_c_pagos_directos_importe, v_c_pagos_directos_tipo_pago
	    			    	-- 	, v_c_pagos_directos_programa, v_c_pagos_directos_manager_pos_prin, v_c_pagos_directos_tipo_agente, v_c_pagos_directos_nif
	    			    	-- 	, v_c_pagos_directos_pos_prin, v_c_pagos_directos_pos_callidus , v_c_pagos_directos_earninggroupid, v_c_pagos_directos_earningcodeid
	    			    	-- 	, v_c_pagos_directos_depositseq, v_c_pagos_directos_periodseq, v_c_pagos_directos_positionseq, 
	    			    FROM :C_PAGOS 
						ORDER BY EARNINGCODEID,EARNINGGROUPID, PROGRAMA, DEPOSITSEQ LIMIT 1 OFFSET :v_offset;
                            
                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio LOOP C_PAGOS: ' || v_c_pagos_tipo_pago, v_log_count, v_idproceso, 'info');
                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe del pago a repartir: ' || v_c_pagos_importe, v_log_count, v_idproceso, 'info');
                            v_DesError := 'PAGOS REPARTIDOS';
                            
                            --Segun los valores del reparto montamos los filtros necesarios para extraer las polizas implicadas en el reparto de cada pago.
                            --Extraemos el filtro necesario por si el agente es un agente normal o es una agente con grupo o superior.
                            --ALM 20211125: Hay que tener en cuenta las tipologias de Eterna.
                            --IF v_c_pagos_tipo_agente >= 50 THEN
                            --ALM 20220713: Usamos la tipologia del EARNINGGROUPID para saber si hay que coger polizas propias, solo agente, o polizas tambien del equipo, inspector.
                            --IF (v_c_pagos_tipo_agente >= 50 AND v_c_pagos_tipo_agente < 300) OR v_c_pagos_tipo_agente >= 350 THEN
                            IF SUBSTR(v_c_pagos_earninggroupid,5,1) = '5' THEN
                                v_position_reparto := '(POS_PRIN = ''' || v_c_pagos_pos_prin || ''' OR MANAGER_POS_PRIN = ''' || v_c_pagos_pos_prin || ''')';
                                
                            ELSE
                                v_position_reparto := 'POS_PRIN = ''' || v_c_pagos_pos_prin || '''';
                                
                            END IF;
                            
                            --Extraemos los filtros necesarios segun la periodicidad.
                            v_DesError := 'PAGOS REPARTIDOS. PERIODICIDAD';
                            
                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Periodicidad: ' || v_c_pagos_nombre_periodo, v_log_count, v_idproceso, 'info');

                            --ALM 20220503: Si la periodicidad es I debemos cargar las poliza del anio N-1 en negativo.
                            IF v_c_pagos_nombre_periodo = 'I' THEN
                                v_periodo_reparto := 'AND PERIODSEQ IN (
    								SELECT X.PERIODSEQ FROM TCMP.CS_PERIOD X 
    								WHERE X.PERIODTYPESEQ = 2814749767106561 AND X.REMOVEDATE = TO_DATE(''22000101'',''YYYYMMDD'') 
    								AND EXTRACT(YEAR FROM X.STARTDATE) = ' || (EXTRACT(YEAR FROM v_c_pagos_fecha_cargo)-1) || ')';

                                IF v_c_pagos_porcentaje_tramo1 > 0 THEN
                                    
                                    --Extraemos los filtros necesarios segun el tipo de base del reparto para este tramo.
                                    --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Reparto Tramo 1.', v_log_count, v_idproceso, 'info');
                                    v_DesError := 'PAGOS REPARTIDOS. PERIODICIDAD I. TRAMO1';

                                    IF v_c_pagos_tipo_base_tramo1 = 'PFP' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --POLIZAS FISICAS PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										AND (POLIZA_FISICA > 0
    										    OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
    										        SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
    										        FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
    										        WHERE ' || v_position_reparto || '
    										        ' || v_periodo_reparto || '
    										        AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										        AND POLIZA_FISICA > 0)
    										    AND POLIZA_FISICA >= 0)';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'UPP' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --POLIZAS CORREGIDAS PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										AND (POLIZA_CORREGIDA > 0
    										    OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
    										        SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
    										        FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
    										        WHERE ' || v_position_reparto || '
    										        ' || v_periodo_reparto || '
    										        AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										        AND POLIZA_CORREGIDA > 0)
    										    AND POLIZA_CORREGIDA >= 0)';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRP' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --PRIMAS CORREGIDAS PRODUCCION
                                        --ALM 20220704: Incluimos la permanencia 11 porque para los inspectores se usa para el pago de diferenciales y COLC y siempre se reparte con la PRP.
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'',''11'')
    										AND PRIMA_CORREGIDA > 0';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PNP' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --PRIMAS NETAS PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										AND PRIMA_NETA > 0';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PAP' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --PRIMAS ANUALIZADAS PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										AND PRIMA_NETA_ANUAL > 0';
                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PCP' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --PRIMAS COMISIONABLES PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										AND PRIMA_COMIS_S4 > 0';
                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PFC' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --POLIZAS FISICAS CARTERA
                                        v_tramo_reparto := 'AND EVENTTYPEID = ''81''
    										AND (POLIZA_FISICA > 0
    										    OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
    										        SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
    										        FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
    										        WHERE ' || v_position_reparto || '
    										        ' || v_periodo_reparto || '
    										        AND EVENTTYPEID = ''81''
    										        AND POLIZA_FISICA > 0)
    										    AND POLIZA_FISICA >= 0)';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PNC' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --PRIMAS NETAS CARTERA
                                        v_tramo_reparto := 'AND EVENTTYPEID = ''81''
    										AND PRIMA_NETA > 0';
                                    
                                    --ALM 20211122: Incluimos los nuevos tipos de bases de reparto solicitados.
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRE' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --POLIZAS RECUPERADAS CON EXITO
                                        --JGE 20230427 miramos estado igual a C en vez de importe comision mayor que 0 
                                        --v_tramo_reparto := 'AND EVENTTYPEID = ''11'' AND IMPORTE_COMISION > 0';
                                        v_tramo_reparto := 'AND EVENTTYPEID = ''11'' AND ESTADO = ''C''';
                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRG' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --POLIZAS GESTIONADAS
                                        v_tramo_reparto := 'AND EVENTTYPEID = ''11'' AND IMPORTE_GRATIF > 0';
                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRR' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --PRIMAS RECUPERADAS
                                        v_tramo_reparto := 'AND EVENTTYPEID = ''11'' AND IMPORTE_COMISION > 0';
                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'NAP' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --NUMERO ASEGURADOS PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'') AND NUM_ASEG > 0';
                                    
                                    ELSE
                                        v_DesError := 'La base de reparto definida del Tramo1 no esta contemplada: ' || v_c_pagos_tipo_base_tramo1 || 
                                                                                   ' o el porcentaje no es valido: ' || v_c_pagos_porcentaje_tramo1 || '. No se puede realizar el reparto.';
                                        --RAISE HAY_ERROR_LOOP;
                                        CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                    END IF;

                                    --Por ultimo, exraemos los filtros necesarios segun los productos a los que aplica este tramo.
                                    --Tambien sacamos el tipo_base y coeficiente correspondiente para cada uno de los rangos de productos.
                                    v_DesError := 'PAGOS REPARTIDOS TRAMO1. PERIODICIDAD I. PRODUCTOS';
                                    v_cont_productos := 0;
                                        
                                    C_TRAMOS1 =
                                        --ALM 20220729: Incluimos un DISTINCT para evitar duplicados con los pagos generados por los DD-O-COLC-.
                                        SELECT DISTINCT PRODUCTO_DESDE,PRODUCTO_HASTA,COEF_TIPO_BASE_TRAMO1,COEF_CORRECTOR_TRAMO1
                                        FROM :TEMP_REPEXT_PAGOS_REPARTO_FILE
                                        WHERE POS_PRIN = v_c_position_pos_prin
                                            --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                            AND TIPO_DOCUMENTO = v_c_pagos_tipo_documento
                                            --ALM 20211201: Usamos el nuevo campo DEPOSITSEQ que hace unicos los pagos.
                                            --AND TIPO_PAGO = v_c_pagos_tipo_pago
                                            ----ALM 20211123: Anadimos mas filtros para evitar duplicados.
                                            --AND EARNINGCODEID = v_c_pagos_earningcodeid
                                            --AND EARNINGGROUPID = v_c_pagos_earninggroupid
                                            --AND PROGRAMA = v_c_pagos_programa
                                            --AND IMPORTE = v_c_pagos_importe
                                            AND DEPOSITSEQ = v_c_pagos_depositseq
                                            --Solo cogemos las bases que tengan un coeficiente mayor que 0 aunque el tipo de base sea N/A (para estos casos aplica el tipo de base del reparto).
                                            AND COEF_CORRECTOR_TRAMO1 > 0
                                        ORDER BY PRODUCTO_DESDE;
                                                
                                    v_total_filas_C_TRAMOS1 = RECORD_COUNT(:C_TRAMOS1);
                    		--	CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_TRAMOS1 TOTAL REGISTROS ' || v_total_filas_C_TRAMOS1, v_log_count, v_idproceso, 'info');   
                                
                                v_select_base_reparto := NULL;
                                v_select_coef_reparto := NULL;  
                                v_producto_reparto := NULL;
                                v_fila_C_TRAMOS1 := 0;
                                v_cont_cursor_C_TRAMOS1 := 0;
                    				FOR v_fila_C_TRAMOS1 IN 1 .. v_total_filas_C_TRAMOS1 DO
            						--C_TRAMOS1
            						BEGIN
            				
                        				v_offset := v_fila_C_TRAMOS1 - 1;
                        				-- CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_TRAMOS1  REGISTRO ' || v_offset || ' DEL TOTAL ' || v_total_filas_C_TRAMOS1, v_log_count, v_idproceso, 'info');  
						 	----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	            			v_cont_cursor_C_TRAMOS1 := v_cont_cursor_C_TRAMOS1 + 1;
	            			IF (MOD(v_cont_cursor_C_TRAMOS1,100)=0 OR (v_cont_cursor_C_TRAMOS1 = v_total_filas_C_TRAMOS1)) THEN
	            				CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_TRAMOS1 REGISTRO ' || v_cont_cursor_C_TRAMOS1  || ' DE ' || v_total_filas_C_TRAMOS1 || ' POSITION ' || v_c_position_pos_prin || ' - PROCESADO '|| (v_cont_cursor_C_TRAMOS1*100)/(v_total_filas_C_TRAMOS1)*(1.0) || '%', v_log_count, v_idproceso, 'info');
	            				-- CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_POSITION PROCESADO ' || ROUND((v_cont_cursor_C_POSITION*100)/(v_total_filas_C_POSITION)*(1.0),1) ||
	            				-- '%  || C_PAGOS PROCESADO '|| (v_cont_cursor_C_PAGOS*100)/(v_total_filas_C_PAGOS)*(1.0) || 
	            				-- '%  || C_TRAMOS1 PROCESADO '|| (v_cont_cursor_C_TRAMOS1*100)/(v_total_filas_C_TRAMOS1)*(1.0) || '%' 
	            				-- , v_log_count, v_idproceso, 'info');
	            			END IF;
	            			----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
                        				
            							SELECT PRODUCTO_DESDE,PRODUCTO_HASTA,COEF_TIPO_BASE_TRAMO1,COEF_CORRECTOR_TRAMO1
            							INTO v_c_tramos1_producto_desde, v_c_tramos1_producto_hasta, v_c_tramos1_coef_tipo_base_tramo1, v_c_tramos1_coef_corrector_tramo1
            							FROM :C_TRAMOS1 LIMIT 1 OFFSET :v_offset;
                                            
                                            
                                            --Como puede tratarse mas de un rango de productos tenemos que diferenciar entre la primera iteracion y las siguientes.
                                            IF v_cont_productos = 0 THEN
                                                v_producto_reparto := '
    												AND (PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_hasta || '''';
                                            
                                                v_select_base_reparto := '
    												(CASE WHEN PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_hasta || '''
        												THEN ''' || v_c_tramos1_coef_tipo_base_tramo1 || '''';
                                            
                                                v_select_coef_reparto := '
    												(CASE WHEN PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_hasta || '''
        												THEN ' || v_c_tramos1_coef_corrector_tramo1;
                                            
                                            ELSE
                                                v_producto_reparto := v_producto_reparto || '
    												OR PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_hasta || '''';
                                            
                                                v_select_base_reparto := v_select_base_reparto || '
    												WHEN PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_hasta || '''
        												THEN ''' || v_c_tramos1_coef_tipo_base_tramo1 || '''';
                                            
                                                v_select_coef_reparto := v_select_coef_reparto || '
    												WHEN PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos1_producto_hasta || '''
        												THEN ' || v_c_tramos1_coef_corrector_tramo1;
                                            END IF;
                                            
                                            v_cont_productos := v_cont_productos + 1;
                                        
                                        -- EXCEPTION
                                        --     WHEN NO_DATA_FOUND THEN
                                        --         v_DesError := 'No hay productos para repartir el Tramo1. No se puede realizar el reparto.';
                                        --         --RAISE HAY_ERROR_LOOP;
                                        --     WHEN OTHERS THEN
