                                    -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM LINEA 3764 v_select_coef_reparto ' || v_select_coef_reparto, v_log_count, v_idproceso, 'info');
                                    IF v_select_coef_reparto IS NULL OR v_select_coef_reparto = '' THEN
