											'''' ||IFNULL(:v_c_pagos_nif,'') || ''' NIF,'||
											'''' ||IFNULL(:v_c_pagos_manager_pos_prin,'') || ''' MANAGER_POS_PRIN,'||
											'ORDERID,'||
    										'LINENUMBER,'||
    										'SUBLINENUMBER,'||
    										'EVENTTYPEID,'||
    										'PRODUCTID,'||
    										'CODIGO_POLIZA,'||
    										'COMPENSATIONDATE,'||
