                                        -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-5 TEMP_REPEXT_FILE. v_insert_repext_temporal: ' || v_insert_repext_temporal, v_log_count, v_idproceso, 'info');
                                        
                                        EXECUTE IMMEDIATE v_insert_repext_temporal;
                                        -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-5 TEMP_REPEXT_FILE. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                                        -- COMMIT;
