                                            -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-6 TEMP_REPEXT_FILE. v_insert_repext_temporal: ' || v_insert_repext_temporal, v_log_count, v_idproceso, 'info');
                                            
                                            EXECUTE IMMEDIATE v_insert_repext_temporal;
