                                            IF v_existe_base_reparto = 0 THEN
                                                
                                                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Position: ' || v_c_position_pos_prin || '. No existe Base de Reparto para el Tramo1. Cogemos la Regional.', v_log_count, v_idproceso, 'info');
                                                
                                                --Volvemos a coger el periodo de reparto correspondiente guardado en la varibale v_periodo_reparto
                                                --v_periodo_reparto_new := 'AND EXTRACT(YEAR FROM COMPENSATIONDATE) = ' || EXTRACT(YEAR FROM v_c_pagos_fecha_cargo);
                                                
                                                --Cogemos la Regional correspondiente a la Position.
                                                SELECT MAX(COD_REGIONAL) INTO v_regional
                                                FROM EXT.OUT_JERARQUIA_REP
                                                WHERE PERIODSEQ = v_periodSeq 
                                                AND POS_PRIN = SUBSTR(v_c_pagos_pos_prin,1,4);
                                                
                                                v_position_reparto_new := 'POS_PRIN LIKE ''' || v_regional || '%''';
                                            -- RAP 20211222 Variable v_base_reparto_tramo1 = 3 (regional)
                                                v_existe_base_reparto_tramo1 := 3;
                                                

                                                
                                                --ALM 20211125: Modificamos la varible v_tramo_reparto si el tipo de base es de polizas porque esta depende del periodo y de la position.
                                                IF v_c_pagos_tipo_base_tramo1 = 'PFP' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --POLIZAS FISICAS PRODUCCION
                                                    v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    													AND (POLIZA_FISICA > 0
    													    OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
    													        SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
    													        FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
    													        WHERE ' || v_position_reparto_new || '
    													        ' || v_periodo_reparto || '
    													        AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    													        AND POLIZA_FISICA > 0)
    													    AND POLIZA_FISICA >= 0)';
                                                    
                                                ELSEIF v_c_pagos_tipo_base_tramo1 = 'UPP' AND v_c_pagos_porcentaje_tramo1 > 0 THEN --POLIZAS CORREGIDAS PRODUCCION
                                                    v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    													AND (POLIZA_CORREGIDA > 0
        													OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
            													SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
            													FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
            													WHERE ' || v_position_reparto_new || '
            													' || v_periodo_reparto || '
