													'(CASE WHEN SUBSTR(PRODUCTID,3,1) = ''2'' THEN SUBSTR(PRODUCTID,1,4) || ''0'' || RIGHT(PRODUCTID,2) ELSE PRODUCTID END) AS SUBLINENUMBER, '||
													'''OFI'' AS EVENTTYPEID,'||
													'PRODUCTID,'||
    												'''99999999999'' AS CODIGO_POLIZA,'||
