                                                -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-7 TEMP_REPEXT_FILE. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
