                                                v_insert_repext_temporal := 'INSERT INTO EXT.TEMP_REPEXT_FILE( ' ||
                            						'PARTICIPANTSEQ,POSITIONSEQ,PERIODSEQ,PERIODO,POSITIONNAME,POS_PRIN,NIF' ||
													',MANAGER_POS_PRIN,ORDERID,LINENUMBER,SUBLINENUMBER,EVENTTYPEID,PRODUCTID,CODIGO_POLIZA,COMPENSATIONDATE' ||
													',ESTADO,PROGRAMA,TIPO_PAGO,DEPOSITO,DEPOSITSEQ,IMPORTE_PAGO,EARNINGCODEID,EARNINGGROUPID,TIPO_DOCUMENTO' ||
													',TIPO_AGENTE,IMPORTE'||
													',TIPO_REPARTO,NUM_TRAMO,REPARTO_TIPO_BASE,REPARTO_PORCENTAJE' ||
													',POLIZA_FISICA,POLIZA_CORREGIDA,PRIMA_CORREGIDA,PRIMA_NETA,PRIMA_NETA_ANUAL,PRIMA_COMIS,COEF_TIPO_BASE,COEF_CORRECTOR,COD_AGENTE,TIPO_LIQ)' ||
                                					'SELECT ' || IFNULL(:v_c_pagos_participantseq,0) || ' PARTICIPANTSEQ, '||
													IFNULL(:v_c_pagos_positionseq,0) ||' POSITIONSEQ,' ||
													:v_periodSeq || ' PERIODSEQ,' ||
													'''' || :v_periodName || ''' PERIODO,' ||
													'''' ||IFNULL(:v_c_pagos_pos_callidus,'') || ''' POSITIONNAME,' ||
													'''' ||IFNULL(:v_c_pagos_pos_prin,'') || ''' POS_PRIN,'||
													'''' ||IFNULL(:v_c_pagos_nif,'') || ''' NIF,'||
													'''' ||IFNULL(:v_c_pagos_manager_pos_prin,'') || ''' MANAGER_POS_PRIN,'||
													'PRODUCTID||''99999999999'' AS ORDERID,'||
													'TO_CHAR(COMPENSATIONDATE,''YYYYMM'') AS LINENUMBER,'||
													'(CASE WHEN SUBSTR(PRODUCTID,3,1) = ''2'' THEN SUBSTR(PRODUCTID,1,4) || ''0'' || RIGHT(PRODUCTID,2) ELSE PRODUCTID END) AS SUBLINENUMBER, '||
													'''CIA'' AS EVENTTYPEID,'||
													'PRODUCTID,'||
    												'''99999999999'' AS CODIGO_POLIZA,'||
    												'COMPENSATIONDATE,'||
    												'''C'' AS ESTADO,'||
    												'''' || IFNULL(:v_c_pagos_programa,'') || ''' PROGRAMA,'||
    												'''' || IFNULL(:v_c_pagos_tipo_pago,'') || ''' TIPO_PAGO,'||
    												'''' || IFNULL(:v_c_pagos_deposito,'') || ''' DEPOSITO,'||
    												IFNULL(:v_c_pagos_depositseq,0) || ' DEPOSITSEQ,'||
    												IFNULL(:v_c_pagos_importe,0) || ' IMPORTE_PAGO,'||
    												'''' || IFNULL(:v_c_pagos_earningcodeid,'') || ''' EARNINGCODEID,'||
    												'''' || IFNULL(:v_c_pagos_earninggroupid,'') || ''' EARNINGGROUPID,'||
    												'''' || IFNULL(:v_c_pagos_tipo_documento,'') || ''' TIPO_DOCUMENTO,'||
    												IFNULL(:v_c_pagos_tipo_agente,0) || ' TIPO_AGENTE,'||
    												'0 AS IMPORTE,'||
    												'''' || IFNULL(:v_c_pagos_tipo_reparto,'') || ''' TIPO_REPARTO,'||
    												'1 AS NUM_TRAMO,'||
    												'''' || IFNULL(:v_c_pagos_tipo_base_tramo1,'') || ''' REPARTO_TIPO_BASE,'||
    												'''' || IFNULL(:v_c_pagos_porcentaje_tramo1,0) || ''' REPARTO_PORCENTAJE,'||
													'SUM(POLIZA_FISICA) POLIZA_FISICA,'||
													'SUM(POLIZA_CORREGIDA) POLIZA_CORREGIDA,'||
													'SUM(PRIMA_CORREGIDA) PRIMA_CORREGIDA,'||
													'SUM(PRIMA_NETA) PRIMA_NETA,'||
													'SUM(PRIMA_NETA_ANUAL) PRIMA_NETA_ANUAL,'||
													'SUM(PRIMA_COMIS_S4) PRIMA_COMIS ,'||
													'' || IFNULL(:v_select_base_reparto,'') || ' COEF_TIPO_BASE,'||
    												:v_select_coef_reparto || ' COEF_CORRECTOR,'||
    												'''' || IFNULL(:v_c_pagos_pos_prin,'') || ''' AS COD_AGENTE,'||
    												'NULL AS TIPO_LIQ '||
													'FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE '||
													'WHERE ' || IFNULL(:v_position_reparto_new,'') || ' ' ||
													IFNULL(:v_periodo_reparto,'') || ' ' ||
													IFNULL(:v_tramo_reparto,'') || ' ' ||
													IFNULL(:v_producto_reparto,'') || ' ' ||
													'GROUP BY PERIODSEQ,' ||
													'PRODUCTID,' ||
													'COMPENSATIONDATE';
                                                
                                                -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-13 TEMP_REPEXT_FILE. v_insert_repext_temporal: ' || v_insert_repext_temporal, v_log_count, v_idproceso, 'info');
                                                
                                                EXECUTE IMMEDIATE v_insert_repext_temporal;
                                                -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-13 TEMP_REPEXT_FILE. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                                                -- COMMIT;
          --                                      INSERT INTO EXT.TEMP_REPEXT_FILE_DEBUG SELECT * FROM EXT.TEMP_REPEXT_FILE;
		--			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-13 TEMP_REPEXT_FILE_DEBUG. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                                                --Comprobamos si se ha encontrado Base de Reparto, sino es asi buscamos la Base sobre el siguiente nivel indicado.
                                                SELECT COUNT(*) INTO v_existe_base_reparto
                                                FROM EXT.TEMP_REPEXT_FILE;
                                                
                                                --ALM 20230831: Incluimos un nuevo nivel en el reparto del tramo 1: Acumulado Anual de toda la Compania.
                                                --              Debido a la incidencia de 202308 del concepto 128: sin base de reparto al no haber ninguna poliza 81 del producto 0120000.
                                                IF v_existe_base_reparto = 0 THEN
                                                        
                                                    CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Position: ' || v_c_position_pos_prin || '. No existe Base de Reparto para el Tramo1. Cogemos el Acumulado de la Compania.', v_log_count, v_idproceso, 'info');
                                                        
                                                    --Usamos la variable utilizada para el acumulado anual v_periodo_reparto_new
                                                    --v_periodo_reparto_new := 'AND EXTRACT(YEAR FROM COMPENSATIONDATE) = ' || EXTRACT(YEAR FROM v_c_pagos_fecha_cargo);
                                                        
                                                    --Mantemos los filtros de Position utilizados en elcaso anterior.
                                                    --v_position_reparto_new := '1 = 1';
                                                    -- RAP 20211222 Variable v_base_reparto_tramo1 = 4 (Compania)
                                                    --ALM 20230831: Nuevo nivel unico para el tramo 1
                                                    v_existe_base_reparto_tramo1 := 5;
                                                        
                                                    --Ejecutamos la insert para guardar los datos de las polizas que van a intervenir en el reparto.
                                                    v_insert_repext_temporal := 'INSERT INTO EXT.TEMP_REPEXT_FILE( ' ||
                            						'PARTICIPANTSEQ,POSITIONSEQ,PERIODSEQ,PERIODO,POSITIONNAME,POS_PRIN,NIF' ||
													',MANAGER_POS_PRIN,ORDERID,LINENUMBER,SUBLINENUMBER,EVENTTYPEID,PRODUCTID,CODIGO_POLIZA,COMPENSATIONDATE' ||
													',ESTADO,PROGRAMA,TIPO_PAGO,DEPOSITO,DEPOSITSEQ,IMPORTE_PAGO,EARNINGCODEID,EARNINGGROUPID,TIPO_DOCUMENTO' ||
													',TIPO_AGENTE,IMPORTE'||
													',TIPO_REPARTO,NUM_TRAMO,REPARTO_TIPO_BASE,REPARTO_PORCENTAJE' ||
													',POLIZA_FISICA,POLIZA_CORREGIDA,PRIMA_CORREGIDA,PRIMA_NETA,PRIMA_NETA_ANUAL,PRIMA_COMIS,COEF_TIPO_BASE,COEF_CORRECTOR,COD_AGENTE,TIPO_LIQ)' ||
                                					'SELECT ' || IFNULL(:v_c_pagos_participantseq,0) || ' PARTICIPANTSEQ, '||
													IFNULL(:v_c_pagos_positionseq,0) ||' POSITIONSEQ,' ||
													:v_periodSeq || ' PERIODSEQ,' ||
													'''' || :v_periodName || ''' PERIODO,' ||
													'''' ||IFNULL(:v_c_pagos_pos_callidus,'') || ''' POSITIONNAME,' ||
													'''' ||IFNULL(:v_c_pagos_pos_prin,'') || ''' POS_PRIN,'||
													'''' ||IFNULL(:v_c_pagos_nif,'') || ''' NIF,'||
													'''' ||IFNULL(:v_c_pagos_manager_pos_prin,'') || ''' MANAGER_POS_PRIN,'||
													'PRODUCTID||''99999999999'' AS ORDERID,'||
													'TO_CHAR(COMPENSATIONDATE,''YYYYMM'') AS LINENUMBER,'||
													'(CASE WHEN SUBSTR(PRODUCTID,3,1) = ''2'' THEN SUBSTR(PRODUCTID,1,4) || ''0'' || RIGHT(PRODUCTID,2) ELSE PRODUCTID END) AS SUBLINENUMBER, '||
													'''CIA'' AS EVENTTYPEID,'||
													'PRODUCTID,'||
    												'''99999999999'' AS CODIGO_POLIZA,'||
    												'COMPENSATIONDATE,'||
    												'''C'' AS ESTADO,'||
    												'''' || IFNULL(:v_c_pagos_programa,'') || ''' PROGRAMA,'||
    												'''' || IFNULL(:v_c_pagos_tipo_pago,'') || ''' TIPO_PAGO,'||
    												'''' || IFNULL(:v_c_pagos_deposito,'') || ''' DEPOSITO,'||
    												IFNULL(:v_c_pagos_depositseq,0) || ' DEPOSITSEQ,'||
    												IFNULL(:v_c_pagos_importe,0) || ' IMPORTE_PAGO,'||
    												'''' || IFNULL(:v_c_pagos_earningcodeid,'') || ''' EARNINGCODEID,'||
    												'''' || IFNULL(:v_c_pagos_earninggroupid,'') || ''' EARNINGGROUPID,'||
    												'''' || IFNULL(:v_c_pagos_tipo_documento,'') || ''' TIPO_DOCUMENTO,'||
    												IFNULL(:v_c_pagos_tipo_agente,0) || ' TIPO_AGENTE,'||
    												'0 AS IMPORTE,'||
    												'''' || IFNULL(:v_c_pagos_tipo_reparto,'') || ''' TIPO_REPARTO,'||
    												'1 AS NUM_TRAMO,'||
    												'''' || IFNULL(:v_c_pagos_tipo_base_tramo1,'') || ''' REPARTO_TIPO_BASE,'||
    												'''' || IFNULL(:v_c_pagos_porcentaje_tramo1,0) || ''' REPARTO_PORCENTAJE,'||
													'SUM(POLIZA_FISICA)*(-1) POLIZA_FISICA,'||
													'SUM(POLIZA_CORREGIDA)*(-1) POLIZA_CORREGIDA,'||
													'SUM(PRIMA_CORREGIDA)*(-1) PRIMA_CORREGIDA,'||
													'SUM(PRIMA_NETA)*(-1) PRIMA_NETA,'||
													'SUM(PRIMA_NETA_ANUAL)*(-1) PRIMA_NETA_ANUAL,'||
													'SUM(PRIMA_COMIS_S4)*(-1) PRIMA_COMIS ,'||
													'' || IFNULL(:v_select_base_reparto,'') || ' COEF_TIPO_BASE,'||
    												:v_select_coef_reparto || ' COEF_CORRECTOR,'||
    												'''' || IFNULL(:v_c_pagos_pos_prin,'') || ''' AS COD_AGENTE,'||
    												'NULL AS TIPO_LIQ '||
													'FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE '||
													'WHERE ' || IFNULL(:v_position_reparto_new,'') || ' ' ||
													IFNULL(:v_periodo_reparto_new,'') || ' ' ||
													IFNULL(:v_tramo_reparto,'') || ' ' ||
													IFNULL(:v_producto_reparto,'') || ' ' ||
													'GROUP BY PERIODSEQ,' ||
													'PRODUCTID,' ||
													'COMPENSATIONDATE';
                                                        
                                                    -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-14 TEMP_REPEXT_FILE. v_insert_repext_temporal: ' || v_insert_repext_temporal, v_log_count, v_idproceso, 'info');
                                                        
                                                    EXECUTE IMMEDIATE v_insert_repext_temporal;
                                                    --  CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-14 TEMP_REPEXT_FILE. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');   
                                                    -- COMMIT;
          --                                              INSERT INTO EXT.TEMP_REPEXT_FILE_DEBUG SELECT * FROM EXT.TEMP_REPEXT_FILE;
		--			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-14 TEMP_REPEXT_FILE_DEBUG. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                                                    --Comprobamos si se ha encontrado Base de Reparto, sino es asi buscamos la Base sobre el siguiente nivel indicado.
                                                    SELECT COUNT(*) INTO v_existe_base_reparto
                                                    FROM EXT.TEMP_REPEXT_FILE;
                                                        
                                                    IF v_existe_base_reparto = 0 THEN
                                                            
                                                        v_DesError := 'No se ha podido encontrar una Base de Reparto para el Tramo1 de la Position: ' || v_c_pagos_pos_prin;
                                                        --RAISE HAY_ERROR_LOOP;
                                                          CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name, v_DesError , v_log_count, v_idproceso, 'debug');   
                                                    END IF;
                                                        
                                                END IF;
                                                
                                            END IF;
                                            
                                        END IF;
                                        
                                    END IF;
                                    
                                END IF;
                                
                                v_DesError := 'PAGOS REPARTIDOS TRAMO1. REPARTO';
                                
                                --Sacamos todos los sumatorios de las variables de polizas y primas para usar aquellos que necesitemos en cada caso.
                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                SELECT SUM(POLIZA_FISICA * (COEF_CORRECTOR/100)),
                                    SUM(POLIZA_CORREGIDA * (COEF_CORRECTOR/100)),
                                    SUM(PRIMA_CORREGIDA * (COEF_CORRECTOR/100)),
                                    SUM(PRIMA_NETA * (COEF_CORRECTOR/100)),
                                    SUM(PRIMA_NETA_ANUAL * (COEF_CORRECTOR/100)),
                                    SUM(PRIMA_COMIS * (COEF_CORRECTOR/100)),
                                    --ALM 20211122: Incluimos los contadores y sumatorios necesarios para los nuevos valores de reparto incluidos.
                                    COUNT(*)
                                INTO v_sum_pol_fis_total,
                                    v_sum_pol_corr_total,
                                    v_sum_prima_corr_total,
                                    v_sum_prima_neta_total,
                                    v_sum_prima_anual_total,
                                    v_sum_prima_comis_total,
                                    --ALM 20211122: Incluimos los contadores y sumatorios necesarios para los nuevos valores de reparto incluidos.
                                    v_cont_pol_total
                                FROM EXT.TEMP_REPEXT_FILE;
                                
                                
        --LFC_CALL                         
										CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por polizas fisicas: ' || v_sum_pol_fis_total, v_log_count, v_idproceso, 'info');
                                 CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por polizas corregidas (todas las garantias): ' || v_sum_pol_corr_total, v_log_count, v_idproceso, 'info');
                                 CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por primas corregidas (todas las garantias): ' || v_sum_prima_corr_total, v_log_count, v_idproceso, 'info');
                                 CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por primas netas (todas las garantias): ' || v_sum_prima_neta_total, v_log_count, v_idproceso, 'info');
                                 CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por primas anualizadas (todas las garantias): ' || v_sum_prima_anual_total, v_log_count, v_idproceso, 'info');
                                 CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por primas comisionable (todas las garantias): ' || v_sum_prima_comis_total, v_log_count, v_idproceso, 'info');
                                 CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Conteo total por polizas recuperadas: ' || v_cont_pol_total, v_log_count, v_idproceso, 'info');
                                
                                        
                                --Comenzamos con el calculo del reparto.
                                --Sacamos el importe que hay que repartir para este tramo. Este sera el porcentaje corespondiente sobre el importe total.
                                v_importe_reparto_tramo1 := v_c_pagos_importe * v_c_pagos_porcentaje_tramo1 / 100;
                                
                               CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe que hay que repartir para este tramo 1: ' || v_importe_reparto_tramo1, v_log_count, v_idproceso, 'info');
                                
                                --Si este importe es distinto de 0 dividimos este importe segun el tipo de base de reparto entre las polizas implicadas.
                                --ALM 20211123: Hay que usar un distinto para repartir tambien los pagos negativos (balances). Ej: 0889000218 en agosto 2021.
                                --IF v_importe_reparto_tramo1 > 0 THEN
                                IF v_importe_reparto_tramo1 <> 0 THEN
                                
                                    IF v_c_pagos_tipo_base_tramo1 = 'PFP' THEN
                                        IF v_sum_pol_fis_total = 0 THEN
                                            v_DesError := 'No hay polizas fisicas para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_sum_pol_fis_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'UPP' THEN
                                        IF v_sum_pol_corr_total = 0 THEN
                                            v_DesError := 'No hay polizas corregidas para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_sum_pol_corr_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRP' THEN
                                        IF v_sum_prima_corr_total = 0 THEN
                                            v_DesError := 'No hay primas corregidas para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_sum_prima_corr_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PNP' THEN
                                        IF v_sum_prima_neta_total = 0 THEN
                                            v_DesError := 'No hay primas netas para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_sum_prima_neta_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PAP' THEN
                                        IF v_sum_prima_anual_total = 0 THEN
                                            v_DesError := 'No hay primas anualizadas para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_sum_prima_anual_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PCP' THEN
                                        IF v_sum_prima_comis_total = 0 THEN
                                            v_DesError := 'No hay primas comisionables para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_sum_prima_comis_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PFC' THEN
                                        IF v_sum_pol_fis_total = 0 THEN
                                            v_DesError := 'No hay polizas fisicas para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_sum_pol_fis_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PNC' THEN
                                        IF v_sum_prima_neta_total = 0 THEN
                                            v_DesError := 'No hay primas netas para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_sum_prima_neta_total;
                                        END IF;
                                        
                                    --ALM 20211122: Incluimos los nuevos tipos de bases de reparto solicitados.
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRE' THEN
                                        IF v_cont_pol_total = 0 THEN
                                            v_DesError := 'No hay polizas recuperadas con exito para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_cont_pol_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRG' THEN
                                        IF v_cont_pol_total = 0 THEN
                                            v_DesError := 'No hay polizas recuperadas sin exito para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_cont_pol_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRR' THEN
                                        IF v_cont_pol_total = 0 THEN
                                            v_DesError := 'No hay primas recuperadas para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_cont_pol_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo1 = 'NAP' THEN
                                        IF v_cont_pol_total = 0 THEN
                                            v_DesError := 'No hay asegurados de produccion para repartir el Tramo1. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo1 / v_cont_pol_total;
                                        END IF;
                                        
                                    ELSE
                                        v_DesError := 'La base de reparto definida del Tramo1 no esta contemplada: ' || v_c_pagos_tipo_base_tramo1 || '. No se puede realizar el reparto.';
                                        --RAISE HAY_ERROR_LOOP;
                                        CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                        
                                    END IF;
                                    
                                END IF;
                                
                      --LFC_CALL          CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe para cada una de las polizas implicadas en el tramo 1: ' || v_importe_por_poliza, v_log_count, v_idproceso, 'info');
                                
                                v_DesError := 'PAGOS REPARTIDOS TRAMO1. LOOP REPARTO';
                                v_importe_repartido := 0;
                                v_importe_comprobacion := 0;
                                
                                --Recorremos las polizas implicadas calculando el importe para cada una.
                                C_REPARTO1 =
                                    SELECT *
                                    FROM EXT.TEMP_REPEXT_FILE
                                    --ALM 20220630: Incluimos la fecha de compensacion para evitar problemas por modificaciones erroneas de Comercial en Commissions.
                                    --              Sino se incluye algunas polizas parecen duplicadas aunque sean la misma. Ej: 01501263150499000000000N3812 para Junio 2022.
                                    --ORDER BY CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID)
                                    ORDER BY CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID,COMPENSATIONDATE;
                                    
                                v_total_filas_C_REPARTO1 = RECORD_COUNT(:C_REPARTO1);
                                -- CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_REPARTO1 TOTAL REGISTROS ' || v_total_filas_C_REPARTO1, v_log_count, v_idproceso, 'info');  
            				v_fila_C_REPARTO1 := 0;
                            v_cont_cursor_C_REPARTO1 := 0;
            				FOR v_fila_C_REPARTO1 IN 1 .. v_total_filas_C_REPARTO1 DO
                            --REPARTO
                            BEGIN
                            	v_offset := v_fila_C_REPARTO1 - 1;
                            	 --CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_REPARTO1  REGISTRO ' || v_offset || ' DEL TOTAL ' || v_total_filas_C_REPARTO1, v_log_count, v_idproceso, 'info');  
	            			----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	            			v_cont_cursor_C_REPARTO1 := v_cont_cursor_C_REPARTO1 + 1;
	            			IF (MOD(v_cont_cursor_C_REPARTO1,100)=0 OR (v_cont_cursor_C_REPARTO1 = v_total_filas_C_REPARTO1)) THEN
	            				CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_REPARTO1 REGISTRO ' || v_cont_cursor_C_REPARTO1  || ' DE ' || v_total_filas_C_REPARTO1 || ' - PROCESADO '|| (v_cont_cursor_C_REPARTO1*100)/(v_total_filas_C_REPARTO1)*(1.0) || '%', v_log_count, v_idproceso, 'info');
	            				-- 	CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_POSITION PROCESADO ' || ROUND((v_cont_cursor_C_POSITION*100)/(v_total_filas_C_POSITION)*(1.0),1) ||
	            				-- '%  || C_PAGOS PROCESADO '|| (v_cont_cursor_C_PAGOS*100)/(v_total_filas_C_PAGOS)*(1.0) || 
	            				-- '%  || C_REPARTO1 PROCESADO '|| (v_cont_cursor_C_REPARTO1*100)/(v_total_filas_C_REPARTO1)*(1.0) || '%' 
	            				-- , v_log_count, v_idproceso, 'info');
	            			END IF;
	            			----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	            				SELECT COEF_CORRECTOR, CODIGO_POLIZA, LINENUMBER, SUBLINENUMBER, EVENTTYPEID, COMPENSATIONDATE
	            					, PRIMA_CORREGIDA, COEF_TIPO_BASE, PRIMA_NETA, PRIMA_NETA_ANUAL, PRIMA_COMIS, ORDERID
	            				INTO v_c_reparto1_coef_corrector, v_c_reparto1_codigo_poliza, v_c_reparto1_linenumber, v_c_reparto1_sublinenumber, v_c_reparto1_eventtypeid, v_c_reparto1_compensationdate
	            					, v_c_reparto1_prima_corregida, v_c_reparto1_reparto_tipo_base, v_c_reparto1_prima_neta, v_c_reparto1_prima_neta_anual, v_c_reparto1_prima_comis, v_c_reparto1_orderid
	            				FROM :C_REPARTO1 
	            				LIMIT 1 OFFSET :v_offset;
                                        
                                        -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio LOOP C_REPARTO1: ' || v_c_reparto1_orderid, v_log_count, v_idproceso, 'info');
                                        
                                        --Si el coeficinete corrector es mayor que 0 calculamos el importe correspondiente.
                                        IF v_c_reparto1_coef_corrector > 0 THEN
                                        
                                            --Primero sacamos los sumatorios de las variables de polizas y primas agrupados para cada poliza (necesario para el reparto de RRTT).
                                            --Ademas, sumamos los porcentajes de los coeficientes para aplicar una base 100 sobre ellos y el numero de registros.
                                            --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                            SELECT SUM(POLIZA_FISICA * (COEF_CORRECTOR/100)),
                                                SUM(POLIZA_CORREGIDA * (COEF_CORRECTOR/100)),
                                                SUM(PRIMA_CORREGIDA * (COEF_CORRECTOR/100)),
                                                SUM(PRIMA_NETA * (COEF_CORRECTOR/100)),
                                                SUM(PRIMA_NETA_ANUAL * (COEF_CORRECTOR/100)),
                                                SUM(PRIMA_COMIS * (COEF_CORRECTOR/100)),
                                                SUM(COEF_CORRECTOR),
                                                COUNT(COEF_CORRECTOR)
                                            INTO v_sum_pol_fis,
                                                v_sum_pol_corr,
                                                v_sum_prima_corr,
                                                v_sum_prima_neta,
                                                v_sum_prima_anual,
                                                v_sum_prima_comis,
                                                v_sum_porc_coef,
                                                v_num_porc_coef
                                            FROM EXT.TEMP_REPEXT_FILE
                                             WHERE CODIGO_POLIZA = v_c_reparto1_codigo_poliza
                                        		AND LINENUMBER = v_c_reparto1_linenumber
                                        		AND SUBLINENUMBER = v_c_reparto1_sublinenumber
                                        		AND EVENTTYPEID = v_c_reparto1_eventtypeid
                                        		--ALM 20220630: Incluimos la fecha de compensacion para evitar problemas por modificaciones erroneas de Comercial en Commissions.
                                        		--              Sino se incluye algunas polizas parecen duplicadas aunque sean la misma. Ej: 01501263150499000000000N3812 para Junio 2022.
                                        		AND COMPENSATIONDATE = v_c_reparto1_compensationdate;
                                            
                                            
                                   --LFC_CALL
								--			 CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio por polizas fisicas (todas las garantias): ' || v_sum_pol_fis, v_log_count, v_idproceso, 'info');
                                --           CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio por polizas corregidas (todas las garantias): ' || v_sum_pol_corr, v_log_count, v_idproceso, 'info');
                                --           CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio por primas corregidas (todas las garantias): ' || v_sum_prima_corr, v_log_count, v_idproceso, 'info');
                                --           CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio por primas netas (todas las garantias): ' || v_sum_prima_neta, v_log_count, v_idproceso, 'info');
                                --           CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio por primas anualizadas (todas las garantias): ' || v_sum_prima_anual, v_log_count, v_idproceso, 'info');
                                --           --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio por primas comisionable (todas las garantias): ' || v_sum_prima_comis, v_log_count, v_idproceso, 'info');
                                --           CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio coeficientes (todas las garantias): ' || v_sum_porc_coef, v_log_count, v_idproceso, 'info');
                                --           CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Conteo coeficientes (todas las garantias): ' || v_num_porc_coef, v_log_count, v_idproceso, 'info');
                                            
                                            
                                            --Multiplicamos el importe a repartir a cada poliza por el sumatorio de polizas o la prima que cuenta para ella.
                                            IF v_c_pagos_tipo_base_tramo1 = 'PFP' THEN
                                                --ALM 20240408: Incluimos la multiplicacion por el porcentaje en caso de tener tipo de base distinta de 'N/A' 
                                                --v_importe_poliza := v_importe_por_poliza * v_sum_pol_fis;
                                                IF v_c_reparto1_reparto_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_pol_fis * (v_c_reparto1_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_pol_fis;
                                                END IF;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo1 = 'UPP' THEN
                                                v_importe_poliza := v_importe_por_poliza * v_sum_pol_corr;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRP' THEN
                                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_corregida,0);
                                                --ALM 20220223: Usamos el sumatorio en lugar del valor de la poliza, si es unica sera lo mismo, pero para RRTT debe usarse.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_corregida,0) * (v_c_reparto1_coef_corrector/100);
                                                IF v_c_reparto1_reparto_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_prima_corr * (v_c_reparto1_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_corregida,0) * (v_c_reparto1_coef_corrector/100);
                                                END IF;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo1 = 'PNP' THEN
                                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_neta,0);
                                                --ALM 20220223: Usamos el sumatorio en lugar del valor de la poliza, si es unica sera lo mismo, pero para RRTT debe usarse.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_neta,0) * (v_c_reparto1_coef_corrector/100);
                                                IF v_c_reparto1_reparto_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_prima_neta * (v_c_reparto1_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_neta,0) * (v_c_reparto1_coef_corrector/100);
                                                END IF;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo1 = 'PAP' THEN
                                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_neta_ANUAL,0);
                                                --ALM 20220223: Usamos el sumatorio en lugar del valor de la poliza, si es unica sera lo mismo, pero para RRTT debe usarse.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_neta_ANUAL,0) * (v_c_reparto1_coef_corrector/100);
                                                IF v_c_reparto1_reparto_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_prima_anual * (v_c_reparto1_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_neta_ANUAL,0) * (v_c_reparto1_coef_corrector/100);
                                                END IF;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo1 = 'PCP' THEN
                                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_comis,0);
                                                --ALM 20220223: Usamos el sumatorio en lugar del valor de la poliza, si es unica sera lo mismo, pero para RRTT debe usarse.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_comis,0) * (v_c_reparto1_coef_corrector/100);
                                                IF v_c_reparto1_reparto_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_prima_comis * (v_c_reparto1_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_comis,0) * (v_c_reparto1_coef_corrector/100);
                                                END IF;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo1 = 'PFC' THEN
                                                v_importe_poliza := v_importe_por_poliza * v_sum_pol_fis;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo1 = 'PNC' THEN
                                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_neta,0);
                                                --ALM 20220223: Usamos el sumatorio en lugar del valor de la poliza, si es unica sera lo mismo, pero para RRTT debe usarse.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_neta,0) * (v_c_reparto1_coef_corrector/100);
                                                IF v_c_reparto1_reparto_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_prima_neta * (v_c_reparto1_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto1_prima_neta,0) * (v_c_reparto1_coef_corrector/100);
                                                END IF;
                                                
                                            --ALM 20211122: Incluimos los nuevos tipos de bases de reparto solicitados.
                                            ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRE' THEN
                                                v_importe_poliza := v_importe_por_poliza;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRG' THEN
                                                v_importe_poliza := v_importe_por_poliza;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo1 = 'PRR' THEN
                                                --ALM 20211122: No esta incluido este valor en las tablas de reparto.
                                                --v_importe_poliza := v_importe_por_poliza * C_REPARTO1.IMPORTE_COMISON;
                                                v_importe_poliza := v_importe_por_poliza;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo1 = 'NAP' THEN
                                                --JGE 20240322 Correo Ismael reparto 02-2024 utilizar primas anualizadas de produccion
                                                --ALM 20240405: Segun el COEF_TIPO_BASE usamos el sumatorio de la base dividida por el total y aplicamos el porcentaje de la misma.
                                                --              Hay multiplicar por el numero total de polizas (v_cont_pol_total) para que se reparta el importe integro y no solo el de una poliza.
                                                --ALM 20240408: No multiplicamos por el procentaje corrector ya que se hace en el paso siguiente.
                                                --              FINALMENTE DESHACEMOS EL CAMBIO PORQUE NO FUNCIONA APLICANDOLO DESPUES PARA TODOS LOS CASOS. PENDIENTE INVESTIGAR.
                                                IF v_c_reparto1_reparto_tipo_base = 'PAP' THEN
												-- LFC 20251231: Errores por división / 0
													IF v_sum_prima_anual_total = 0 THEN
														v_importe_poliza := v_importe_por_poliza ;
													ELSE
														v_importe_poliza := v_importe_por_poliza*v_cont_pol_total*v_sum_prima_anual/v_sum_prima_anual_total
																											*(v_c_reparto1_coef_corrector/100);
													END IF;                                                         
                                                ELSEIF v_c_reparto1_reparto_tipo_base = 'PNP' THEN
                                                    v_importe_poliza := v_importe_por_poliza*v_cont_pol_total*v_sum_prima_neta/v_sum_prima_neta_total
                                                                                                             *(v_c_reparto1_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza;
                                                END IF;
                                                
                                            ELSE
                                                v_DesError := 'La base de reparto definida del Tramo1 no esta contemplada: ' || v_c_pagos_tipo_base_tramo1 || '. No se puede realizar el reparto.';
                                                --RAISE HAY_ERROR_LOOP;
                                               
												CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                            END IF;
                                            
                                            
                                --LFC_CALL
								-- 		  CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe para cada una de las garantias de la poliza implicadas en el tramo 1: ' || v_importe_poliza, v_log_count, v_idproceso, 'info');
                                --        CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'v_importe_por_poliza: ' || v_importe_por_poliza, v_log_count, v_idproceso, 'info');
                                --        CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'v_cont_pol_total: ' || v_cont_pol_total, v_log_count, v_idproceso, 'info');
                                --        CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'v_sum_prima_anual: ' || v_sum_prima_anual, v_log_count, v_idproceso, 'info');
                                --        CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'v_sum_prima_anual_total: ' || v_sum_prima_anual_total, v_log_count, v_idproceso, 'info');
                                            
                                            
                                            --Calculamos el importe de cada una de las polizas.
                                            --ALM 20211105: EN EL CUMPLE DE TANIA!!! Controlamos los valores de la Prima para cada caso para evitar posibles divisiones por 0.
                                            --ALM 20240408: Quitamos el uso de las variables v_num_porc_coef y v_sum_porc_coef ya que se anulan una a la otra.
                                            --              ESTE CAMBIO NO FUNCIONA, HABRIA QUE INVESTIGAR EL MOTIVO. LO DEJAMOS COMO ESTABA HASTA QUE SE PUEDA REVISAR.
                                            IF v_c_reparto1_reparto_tipo_base = 'PRP' THEN
                                                
                                                IF v_c_reparto1_prima_corregida <> 0 THEN
                                                    v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto1_coef_corrector/v_sum_porc_coef)
                                                                                                           *(IFNULL(v_c_reparto1_prima_corregida,0)/v_sum_prima_corr),2);
                                                    --v_importe_repartido := v_importe_poliza*(v_c_reparto1_coef_corrector/100)*(IFNULL(v_c_reparto1_prima_corregida,0)/v_sum_prima_corr);
                                                ELSE
                                                    v_importe_repartido := 0;
                                                END IF;
                                                
                                            ELSEIF v_c_reparto1_reparto_tipo_base = 'PNP' THEN
                                                
                                                IF v_c_reparto1_prima_neta <> 0 THEN
                                                    v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto1_coef_corrector/v_sum_porc_coef)
                                                                                                           *(IFNULL(v_c_reparto1_prima_neta,0)/v_sum_prima_neta),2);
                                                    --v_importe_repartido := v_importe_poliza*(v_c_reparto1_coef_corrector/100)*(IFNULL(v_c_reparto1_prima_neta,0)/v_sum_prima_neta);
                                                ELSE
                                                    v_importe_repartido := 0;
                                                END IF;
                                                
                                            ELSEIF v_c_reparto1_reparto_tipo_base = 'PAP' THEN
                                                
                                                --ALM 20211209: Si el sumatorio de la Prima Anual es 0 y el de la Prima Neta no usamos este ultimo para el calculo.
                                                --IF v_c_reparto1_prima_neta_ANUAL <> 0 THEN
                                                --    v_importe_repartido := v_importe_poliza*v_num_porc_coef*(v_c_reparto1_coef_corrector/v_sum_porc_coef)
                                                --                                                           *(IFNULL(v_c_reparto1_prima_neta_ANUAL,0)/v_sum_prima_anual);
                                                --ELSE
                                                --    v_importe_repartido := 0;
                                                --END IF;
                                                IF v_sum_prima_anual = 0 AND v_sum_prima_neta <> 0 THEN
                                                    
                                                    IF v_c_reparto1_prima_neta <> 0 THEN
                                                        v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto1_coef_corrector/v_sum_porc_coef)
                                                                                               *(IFNULL(v_c_reparto1_prima_neta,0)/v_sum_prima_neta),2);
                                                        --v_importe_repartido := v_importe_poliza*(v_c_reparto1_coef_corrector/100)*(IFNULL(v_c_reparto1_prima_neta,0)/v_sum_prima_neta);
                                                    ELSE
                                                        v_importe_repartido := 0;
                                                    END IF;
                                                    
                                                --Si ambas primas son 0 no usamos ninguna de las primas y aplicamos directamente el porcentaje.
                                                ELSEIF v_sum_prima_anual = 0 AND v_sum_prima_neta = 0 THEN
                                                    
                                                    IF SUBSTR(v_c_reparto1_orderid,3,1) = '2' AND SUBSTR(v_c_reparto1_orderid,5,1) = '0' THEN
                                                        v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto1_coef_corrector/v_sum_porc_coef),2);
                                                        --v_importe_repartido := v_importe_poliza*(v_c_reparto1_coef_corrector/100);
                                                    ELSE
                                                        v_importe_repartido := 0;
                                                    END IF;
                                                    
                                                ELSE
                                                    
                                                    IF v_c_reparto1_prima_neta_ANUAL <> 0 THEN
                                                        v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto1_coef_corrector/v_sum_porc_coef)
                                                                                               *(IFNULL(v_c_reparto1_prima_neta_ANUAL,0)/v_sum_prima_anual),2);
                                                        --v_importe_repartido := v_importe_poliza*(v_c_reparto1_coef_corrector/100)*(IFNULL(v_c_reparto1_prima_neta_ANUAL,0)/v_sum_prima_anual);
                                                    ELSE
                                                        v_importe_repartido := 0;
                                                    END IF;
                                                    
                                                END IF;
                                                
                                            ELSEIF v_c_reparto1_reparto_tipo_base = 'PCP' THEN
                                                
                                                IF v_c_reparto1_prima_comis <> 0 THEN
                                                    v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto1_coef_corrector/v_sum_porc_coef)
                                                                                                           *(IFNULL(v_c_reparto1_prima_comis,0)/v_sum_prima_comis),2);
                                                    --v_importe_repartido := v_importe_poliza*(v_c_reparto1_coef_corrector/100)*(IFNULL(v_c_reparto1_prima_comis,0)/v_sum_prima_comis);
                                                ELSE
                                                    v_importe_repartido := 0;
                                                END IF;
                                                
                                            ELSEIF v_c_reparto1_reparto_tipo_base = 'PNC' THEN
                                                
                                                IF v_c_reparto1_prima_neta <> 0 THEN
                                                    v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto1_coef_corrector/v_sum_porc_coef)
                                                                                                           *(IFNULL(v_c_reparto1_prima_neta,0)/v_sum_prima_neta),2);
                                                    --v_importe_repartido := v_importe_poliza*(v_c_reparto1_coef_corrector/100)*(IFNULL(v_c_reparto1_prima_neta,0)/v_sum_prima_neta);
                                                ELSE
                                                    v_importe_repartido := 0;
                                                END IF;
                                                
                                            --ALM 20211122: Incluimos los nuevos tipos de bases de reparto solicitados.
                                            ELSEIF v_c_reparto1_reparto_tipo_base = 'PRR' THEN
                                                
                                                v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto1_coef_corrector/v_sum_porc_coef),2);
                                                --v_importe_repartido := v_importe_poliza*(v_c_reparto1_coef_corrector/100);
                                                
                                            ELSEIF v_c_reparto1_reparto_tipo_base = 'N/A' THEN
                                            
                                                v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto1_coef_corrector/v_sum_porc_coef),2);
                                                --v_importe_repartido := v_importe_poliza*(v_c_reparto1_coef_corrector/100);
                                            
                                            ELSE
                                                v_DesError := 'La base de los coeficiente de reparto definida del Tramo1 no esta contemplado: ' || 
                                                                                                                      v_c_reparto1_reparto_tipo_base || '. No se puede realizar el reparto.';
                                                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                                --RAISE HAY_ERROR_LOOP;
                                                
                                            END IF;
                                            
                                            
                                          --LFC_CALL
											--		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Coeficiente corrector: ' || v_c_reparto1_coef_corrector, v_log_count, v_idproceso, 'info');
                                            --    --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Prima corregida de la poliza: ' || v_c_reparto1_prima_corregida, v_log_count, v_idproceso, 'info');
                                            --	    CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Prima neta anual de la poliza: ' || v_c_reparto1_prima_neta_ANUAL, v_log_count, v_idproceso, 'info');
											--		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe repartido por registro (cuenta): ' || v_importe_poliza || ' * ' || v_num_porc_coef || '*(' ||
                                            --                                                       v_c_reparto1_coef_corrector || '/' || v_sum_porc_coef || ')*(' ||
                                            --                                                       v_c_reparto1_prima_neta_ANUAL || '/' || v_sum_prima_anual || ')', v_log_count, v_idproceso, 'info');
                                            --		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe repartido por registro: ' || v_importe_repartido, v_log_count, v_idproceso, 'info');
                                            
                                            
                                            --Guardamos el importe repartido acumulado y la ultima transaccion modificada para poder hacer las comprobaciones al acabar el reparto.
                                            --BUSCAR LA MEJOR FORMA DE REDONDEAR
                                            --v_importe_comprobacion := v_importe_comprobacion + ROUND(TRUNC(v_importe_repartido,4),2);
                                            v_importe_comprobacion := v_importe_comprobacion + v_importe_repartido;
                                            --v_importe_comprobacion_tramo1 := v_importe_comprobacion_tramo1 + v_importe_repartido;
                                            v_ult_orderid_modif := v_c_reparto1_orderid;
                                            v_ult_linenumber_modif := v_c_reparto1_linenumber;
                                            v_ult_sublinenumber_modif := v_c_reparto1_sublinenumber;
                                            v_ult_eventtypeid_modif := v_c_reparto1_eventtypeid;
                                            --ALM 20220630: Incluimos la fecha de compensacion para evitar problemas por modificaciones erroneas de Comercial en Commissions.
                                            --              Sino se incluye algunas polizas parecen duplicadas aunque sean la misma. Ej: 01501263150499000000000N3812 para Junio 2022.
                                            v_ult_compensationdate_modif := v_c_reparto1_compensationdate;
                                            
                                            --Actualizamos en la tabla temporal.
                                            UPDATE EXT.TEMP_REPEXT_FILE
                                            --BUSCAR LA MEJOR FORMA DE REDONDEAR
                                            --SET IMPORTE = ROUND(TRUNC(v_importe_repartido,4),2)
                                            SET IMPORTE = v_importe_repartido
                                            WHERE ORDERID = v_c_reparto1_orderid
                                                AND LINENUMBER = v_c_reparto1_linenumber
                                                AND SUBLINENUMBER = v_c_reparto1_sublinenumber
                                                AND EVENTTYPEID = v_c_reparto1_eventtypeid
                                                --ALM 20220630: Incluimos la fecha de compensacion para evitar problemas por modificaciones erroneas de Comercial en Commissions.
                                                --              Sino se incluye algunas polizas parecen duplicadas aunque sean la misma. Ej: 01501263150499000000000N3812 para Junio 2022.
                                                AND COMPENSATIONDATE = v_c_reparto1_compensationdate;

                                 --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'ACTUALIZO IMPORTE en EXT.TEMP_REPEXT_FILE ' || ::ROWCOUNT , v_log_count, v_idproceso, 'info');                                
                                           
                                            COMMIT;
                                        
                                        END IF;
                                        
                                    -- EXCEPTION
                                    --     WHEN NO_DATA_FOUND THEN
                                    --         v_DesError := 'No hay datos para repartir el Tramo1. No se puede realizar el reparto.';
                                    --         --RAISE HAY_ERROR_LOOP;
                                    --     WHEN OTHERS THEN
                                    --         v_DesError := 'LOOP C_REPARTO1. Position: ' || v_c_position_pos_prin || '. Error: ' || v_DesError || '. SQLCOD(' || SQLCODE || ') ' ||SQLERRM;
                                    --         RAISE HAY_ERROR;
                                    END;
                                END FOR; --REPARTO1
                                
                                v_DesError := 'PAGOS REPARTIDOS TRAMO1. COMPROBACION IMPORTES';
                                
                                --HACEMOS LA COMPROBACION DESPUES DE REPARTIR AMBOS TRAMOS
                                --DEJAMOS LA COMPROBACION TRAMO A TRAMO
                                -- --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe Reparto Tramo 1: ' || v_importe_comprobacion_tramo1, v_log_count, v_idproceso, 'info');
                                 CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe Reparto Tramo 1: ' || v_importe_comprobacion, v_log_count, v_idproceso, 'info');
                                
                                v_error_reparto_tramo1 := 0;
                                
                                --Comprobamos si el reparto coincide con el pago y actualizamos el estado del reparto en la tabla de pagos.
                                v_dif_importe_reparto := v_importe_reparto_tramo1 - v_importe_comprobacion;
                                
                                IF v_dif_importe_reparto = 0 THEN
                                    
                                    UPDATE EXT.FINAL_REPEXT_PAGOS_FILE
                                    SET ESTADO_REPARTO = 2 --REPARTO CORRECTO
                                    WHERE PERIODSEQ = v_periodSeq
                                        AND POS_PRIN = v_c_pagos_pos_prin
                                        --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                        AND TIPO_DOCUMENTO = v_c_pagos_tipo_documento
                                        --ALM 20220323: Usamos el campo DEPOSITSEQ que hace unicos los pagos.
                                        --AND EARNINGCODEID = v_c_pagos_earningcodeid
                                        --AND EARNINGGROUPID = v_c_pagos_earninggroupid
                                        --AND PROGRAMA = v_c_pagos_programa
                                        --AND TIPO_PAGO = v_c_pagos_tipo_pago
                                        ----ALM 20211123: Anadimos la union por importe por si hay balances con los mismos campos. Ej: 0889000218 en agosto 2021.
                                        --AND IMPORTE = v_c_pagos_importe;
                                        AND DEPOSITSEQ = v_c_pagos_depositseq;
                                            
                                    COMMIT;
                                   
                                
                                --ALM 20211126: Modificamos el rango de redondeo de 1 a 2 euros porque hay position que se desvian demasiado en el redondeo. Ej: 0375001767 en agosto 2021.
                                --ELSEIF v_dif_importe_directo BETWEEN -1 AND 1 THEN
                                --ALM 20220411: Modificamos el rango de redondeo de 2 a 3 porque hay position que se desvian demasiado, pero solo en el reparto indirecto.
                                --              Ej: 0559002764 en marzo 2022.
                                --ELSEIF v_dif_importe_reparto BETWEEN -2 AND 2 THEN
                                --JGE 20230103: Modificamos el rango de redondeo de 3 a 9 porque hay position que se desvian demasiado, pero solo en el reparto indirecto.
                                --              Ej: 0559002764 en diciembre 2022.
                                --ELSEIF v_dif_importe_reparto BETWEEN -3 AND 3 THEN
                                ELSEIF v_dif_importe_reparto BETWEEN -9 AND 9 THEN
                                    
                                    --Actualizamos en la tabla temporal el ultimo importe repartido para ajustar la diferencia.
                                    UPDATE EXT.TEMP_REPEXT_FILE
                                    --BUSCAR LA MEJOR FORMA DE REDONDEAR
                                    --SET IMPORTE = ROUND(TRUNC(v_importe_repartido,4),2) + v_dif_importe_reparto
                                    SET IMPORTE = v_importe_repartido + v_dif_importe_reparto
                                    WHERE ORDERID = v_ult_orderid_modif
                                        AND LINENUMBER = v_ult_linenumber_modif
                                        AND SUBLINENUMBER = v_ult_sublinenumber_modif
                                        AND EVENTTYPEID = v_ult_eventtypeid_modif
                                        --ALM 20220630: Incluimos la fecha de compensacion para evitar problemas por modificaciones erroneas de Comercial en Commissions.
                                        --              Sino se incluye algunas polizas parecen duplicadas aunque sean la misma. Ej: 01501263150499000000000N3812 para Junio 2022.
                                        AND COMPENSATIONDATE = v_ult_compensationdate_modif;
                                    
                                    COMMIT;
                                    
                                    UPDATE EXT.FINAL_REPEXT_PAGOS_FILE
                                    SET ESTADO_REPARTO = 3 --REPARTO CASI CORRECTO
                                    WHERE PERIODSEQ = v_periodSeq
                                        AND POS_PRIN = v_c_pagos_pos_prin
                                        --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                        AND TIPO_DOCUMENTO = v_c_pagos_tipo_documento
                                        --ALM 20220323: Usamos el campo DEPOSITSEQ que hace unicos los pagos.
                                        --AND EARNINGCODEID = v_c_pagos_earningcodeid
                                        --AND EARNINGGROUPID = v_c_pagos_earninggroupid
                                        --AND PROGRAMA = v_c_pagos_programa
                                        --AND TIPO_PAGO = v_c_pagos_tipo_pago
                                        ----ALM 20211123: Anadimos la union por importe por si hay balances con los mismos campos. Ej: 0889000218 en agosto 2021.
                                        --AND IMPORTE = v_c_pagos_importe;
                                        AND DEPOSITSEQ = v_c_pagos_depositseq;
                                    
                                    COMMIT;
                                    
                                ELSE
                                    CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'REPARTO TRAMO1. Position: ' || IFNULL(v_c_position_pos_prin,'') || '. Reparto no cuadra (importe-reparto): ' || 
                                                                            IFNULL(TO_NVARCHAR(v_importe_reparto_tramo1),'') || '-' || IFNULL(TO_NVARCHAR(v_importe_comprobacion),''), v_log_count, v_idproceso, 'info');
                                    
                                    v_error_reparto_tramo1 := 1;
                                    
                                    UPDATE EXT.FINAL_REPEXT_PAGOS_FILE
                                    SET ESTADO_REPARTO = 4 --REPARTO INCORRECTO. NO CUADRA EL IMPORTE
                                    WHERE PERIODSEQ = v_periodSeq
                                        AND POS_PRIN = v_c_pagos_pos_prin
                                        --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                        AND TIPO_DOCUMENTO = v_c_pagos_tipo_documento
                                        --ALM 20220323: Usamos el campo DEPOSITSEQ que hace unicos los pagos.
                                        --AND EARNINGCODEID = v_c_pagos_earningcodeid
                                        --AND EARNINGGROUPID = v_c_pagos_earninggroupid
                                        --AND PROGRAMA = v_c_pagos_programa
                                        --AND TIPO_PAGO = v_c_pagos_tipo_pago
                                        ----ALM 20211123: Anadimos la union por importe por si hay balances con los mismos campos. Ej: 0889000218 en agosto 2021.
                                        --AND IMPORTE = v_c_pagos_importe;
                                        AND DEPOSITSEQ = v_c_pagos_depositseq;
                                    
                                    COMMIT;
                                    
                                END IF;
                                
                                --Insertamos los importes repartidos sobre la tabla final.
                                --Por el momento insertamos siempre el reparto aunque no sea correcto, asi podemos comprobar.
                                v_DesError := 'PAGOS REPARTIDOS TRAMO1. RECARGA TABLA FINAL';

                                   
                                INSERT INTO EXT.FINAL_REPEXT_FILE("TIPO_LIQ","COD_AGENTE","COEF_CORRECTOR","COEF_TIPO_BASE","PRIMA_COMIS","PRIMA_NETA_ANUAL","PRIMA_NETA","PRIMA_CORREGIDA"
                                ,"POLIZA_CORREGIDA","POLIZA_FISICA","REPARTO_PORCENTAJE","REPARTO_TIPO_BASE","NUM_TRAMO","TIPO_REPARTO","IMPORTE","TIPO_AGENTE","TIPO_DOCUMENTO","EARNINGGROUPID"
                                ,"EARNINGCODEID","IMPORTE_PAGO","DEPOSITSEQ","DEPOSITO","TIPO_PAGO","PROGRAMA","ESTADO","COMPENSATIONDATE","CODIGO_POLIZA","PRODUCTID","EVENTTYPEID","SUBLINENUMBER"
                                ,"LINENUMBER","ORDERID","MANAGER_POS_PRIN","NIF","POS_PRIN","POSITIONNAME","PERIODO","PERIODSEQ","POSITIONSEQ","PARTICIPANTSEQ")
                                    SELECT "TIPO_LIQ","COD_AGENTE","COEF_CORRECTOR","COEF_TIPO_BASE","PRIMA_COMIS","PRIMA_NETA_ANUAL","PRIMA_NETA","PRIMA_CORREGIDA"
                                		,"POLIZA_CORREGIDA","POLIZA_FISICA","REPARTO_PORCENTAJE","REPARTO_TIPO_BASE","NUM_TRAMO","TIPO_REPARTO","IMPORTE","TIPO_AGENTE","TIPO_DOCUMENTO","EARNINGGROUPID"
                                		,"EARNINGCODEID","IMPORTE_PAGO","DEPOSITSEQ","DEPOSITO","TIPO_PAGO","PROGRAMA","ESTADO","COMPENSATIONDATE","CODIGO_POLIZA","PRODUCTID","EVENTTYPEID","SUBLINENUMBER"
                                		,"LINENUMBER","ORDERID","MANAGER_POS_PRIN","NIF","POS_PRIN","POSITIONNAME","PERIODO","PERIODSEQ","POSITIONSEQ","PARTICIPANTSEQ"
                                        --Ya no es necesario el campo LIQUIDACION porque no hay diferencia entre cierre y LC.
                                        --(CASE WHEN v_existe_control_reparto = 0 THEN 2 ELSE
                                        --    (CASE WHEN v_control_reparto.ESTADO = 1 THEN 2 ELSE 4 END)
                                        --END) AS LIQUIDACION
                                    FROM EXT.TEMP_REPEXT_FILE RT;

                                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inserto en EXT.FINAL_REPEXT_FILE ' || ::ROWCOUNT , v_log_count, v_idproceso, 'info');                                
                                COMMIT;
                            
                            END IF;    

                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Reparto Tramo 1.', v_log_count, v_idproceso, 'info');
                            
                            --Tratamos el Tramo2.
                            --ALM 20220503: Si la periodicidad es I debemos cargar las poliza del anio N-1 en negativo.
                            v_DesError := 'PAGOS REPARTIDOS. PERIODICIDAD';
                            
                            IF v_c_pagos_nombre_periodo = 'I' THEN
                                v_periodo_reparto := 'AND PERIODSEQ IN (
    								SELECT X.PERIODSEQ FROM TCMP.CS_PERIOD X 
    								WHERE X.PERIODTYPESEQ = 2814749767106561 AND X.REMOVEDATE = TO_DATE(''22000101'',''YYYYMMDD'') 
    								AND EXTRACT(YEAR FROM X.STARTDATE) = ' || (EXTRACT(YEAR FROM v_c_pagos_fecha_cargo)-1) || ')';
    						CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM LINEA 5968 ' || v_c_pagos_porcentaje_tramo2, v_log_count, v_idproceso, 'info');
                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM LINEA 5969 v_c_pagos_porcentaje_tramo2 .' || v_c_pagos_porcentaje_tramo2, v_log_count, v_idproceso, 'info');
                                --SMM v_c_pagos_porcentaje_tramo2 = 2
                                v_c_pagos_porcentaje_tramo2 = 2; 
                                IF v_c_pagos_porcentaje_tramo2 > 0 THEN
                                    
                                    --Extraemos los filtros necesarios segun el tipo de base del reparto para este tramo.
                                    --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Reparto Tramo 2.', v_log_count, v_idproceso, 'info');
                                    v_DesError := 'PAGOS REPARTIDOS. PERIODICIDAD I. TRAMO2';
                                    
                                    IF v_c_pagos_tipo_base_tramo2 = 'PFP' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --POLIZAS FISICAS PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										AND (POLIZA_FISICA > 0
    										    OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
    										        SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
    										        FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
    										        WHERE ' || v_position_reparto || '
    										        ' || v_periodo_reparto || '
    										        AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										        AND POLIZA_FISICA > 0)
    										    AND POLIZA_FISICA >= 0)';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'UPP' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --POLIZAS CORREGIDAS PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										AND (POLIZA_CORREGIDA > 0
        										OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
            										SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
            										FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
            										WHERE ' || v_position_reparto || '
            										' || v_periodo_reparto || '
            										AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
            										AND POLIZA_CORREGIDA > 0)
        										AND POLIZA_CORREGIDA >= 0)';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRP' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --PRIMAS CORREGIDAS PRODUCCION
                                        --ALM 20220704: Incluimos la permanencia 11 porque para los inspectores se usa para el pago de diferenciales y COLC y siempre se reparte con la PRP.
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'',''11'')
    										AND PRIMA_CORREGIDA > 0';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PNP' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --PRIMAS NETAS PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										AND PRIMA_NETA > 0';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PAP' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --PRIMAS ANUALIZADAS PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										AND PRIMA_NETA_ANUAL > 0';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PCP' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --PRIMAS COMISIONABLES PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    										AND PRIMA_COMIS_S4 > 0';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PFC' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --POLIZAS FISICAS CARTERA
                                        v_tramo_reparto := 'AND EVENTTYPEID = ''81''
    										AND (POLIZA_FISICA > 0
    										    OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
    										    SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
    										        FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
    										        WHERE ' || v_position_reparto || '
    										        ' || v_periodo_reparto || '
    										        AND EVENTTYPEID = ''81''
    										        AND POLIZA_FISICA > 0)
    										    AND POLIZA_FISICA >= 0)';
                                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PNC' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --PRIMAS NETAS CARTERA
                                        v_tramo_reparto := 'AND EVENTTYPEID = ''81''
    										AND PRIMA_NETA > 0';
                                    
                                    --ALM 20211122: Incluimos los nuevos tipos de bases de reparto solicitados.
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRE' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --POLIZAS RECUPERADAS CON EXITO
                                        --JGE 20230427 miramos estado igual a C en vez de importe comision mayor que 0 
                                        --v_tramo_reparto := 'AND EVENTTYPEID = ''11'' AND IMPORTE_COMISION > 0';
                                        v_tramo_reparto := 'AND EVENTTYPEID = ''11'' AND ESTADO = ''C''';
                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRG' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --POLIZAS GESTIONADAS
                                        v_tramo_reparto := 'AND EVENTTYPEID = ''11'' AND IMPORTE_GRATIF > 0';
                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRR' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --PRIMAS RECUPERADAS
                                        v_tramo_reparto := 'AND EVENTTYPEID = ''11'' AND IMPORTE_COMISION > 0';
                                    
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'NAP' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --NUMERO ASEGURADOS PRODUCCION
                                        v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'') AND NUM_ASEG > 0';
                                    
                                    ELSE
                                        v_DesError := 'La base de reparto definida del Tramo2 no esta contemplada: ' || v_c_pagos_tipo_base_tramo2 || 
                                                                                   ' o el porcentaje no es valido: ' ||v_c_pagos_porcentaje_tramo2 || '. No se puede realizar el reparto.';
                                        --RAISE HAY_ERROR_LOOP;
                                        CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                    END IF;
                                    
                                    --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Filtros Tipo Base Tramo2: ' || v_tramo_reparto, v_log_count, v_idproceso, 'info');
                                    
                                    --Por ultimo, exraemos los filtros necesarios segun los productos a los que aplica este tramo.
                                    --Tambien sacamos el tipo_base y coeficiente correspondiente para cada uno de los rangos de productos.
                                    v_DesError := 'PAGOS REPARTIDOS TRAMO2. PERIODICIDAD I. PRODUCTOS';
                                    v_cont_productos := 0;
                                        
                                    C_TRAMOS2 =
                                        --ALM 20220729: Incluimos un DISTINCT para evitar duplicados con los pagos generados por los DD-O-COLC-.
                                        SELECT DISTINCT PRODUCTO_DESDE,PRODUCTO_HASTA,COEF_TIPO_BASE_TRAMO2,COEF_CORRECTOR_TRAMO2
                                        FROM :TEMP_REPEXT_PAGOS_REPARTO_FILE
                                        WHERE POS_PRIN = v_c_position_pos_prin
                                            --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                            AND TIPO_DOCUMENTO = v_c_pagos_tipo_documento
                                            --ALM 20211201: Usamos el nuevo campo DEPOSITSEQ que hace unicos los pagos.
                                            --AND TIPO_PAGO = v_c_pagos_tipo_pago
                                            ----ALM 20211123: Anadimos mas filtros para evitar duplicados.
                                            --AND EARNINGCODEID = v_c_pagos_earningcodeid
                                            --AND EARNINGGROUPID = v_c_pagos_earninggroupid
                                            --AND PROGRAMA = v_c_pagos_programa
                                            --AND IMPORTE = v_c_pagos_importe
                                            AND DEPOSITSEQ = v_c_pagos_depositseq
                                            --Solo cogemos las bases que tengan un coeficiente mayor que 0 aunque el tipo de base sea N/A (para estos casos aplica el tipo de base del reparto).
                                            AND COEF_CORRECTOR_TRAMO2 > 0
                                        ORDER BY PRODUCTO_DESDE;
  
if  i_par_position <> 'Todas' then
 ------------------------------LFC:20251202 --TABLA DEBUG PENDIENTE BORRAR
	    SELECT COUNT(1) INTO v_existe_tabla FROM SYS.TABLES WHERE TABLE_NAME = 'C_TRAMOS2_DEBUG';
		
		IF v_existe_tabla > 0 THEN
			DROP TABLE EXT.C_TRAMOS2_DEBUG;
		END IF;
		
		CREATE TABLE EXT.C_TRAMOS2_DEBUG AS (SELECT * FROM :C_TRAMOS2);
	    CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name, 'Creada la tabla temporal C_TRAMOS2_DEBUG' , v_log_count, v_idproceso, 'debug');
------------------------------ 
end if;


  
                                    v_total_filas_C_TRAMOS2 = RECORD_COUNT(:C_TRAMOS2);
                        		-- CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_TRAMOS2 TOTAL REGISTROS ' || v_total_filas_C_TRAMOS2, v_log_count, v_idproceso, 'info');  
                        		v_producto_reparto = NULL;
                        		v_select_coef_reparto = NULL;
                        		v_select_base_reparto = NULL;
                        		v_fila_C_TRAMOS2 := 0;
                                v_cont_cursor_C_TRAMOS2 := 0;
                                
                        		FOR v_fila_C_TRAMOS2 IN 1 .. v_total_filas_C_TRAMOS2 DO
            					--C_TRAMOS2
            					BEGIN
            						v_offset := v_fila_C_TRAMOS2 - 1;
                                      --CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_TRAMOS2  REGISTRO ' || v_offset || ' DEL TOTAL ' || v_total_filas_C_TRAMOS2, v_log_count, v_idproceso, 'info');        
						 	----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	            			v_cont_cursor_C_TRAMOS2 := v_cont_cursor_C_TRAMOS2 + 1;
	            			IF (MOD(v_cont_cursor_C_TRAMOS2,100)=0 OR (v_cont_cursor_C_TRAMOS2 = v_total_filas_C_TRAMOS2)) THEN
	            				CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_TRAMOS2 REGISTRO ' || v_cont_cursor_C_TRAMOS2  || ' DE ' || v_total_filas_C_TRAMOS2 || ' - PROCESADO '|| (v_cont_cursor_C_TRAMOS2*100)/(v_total_filas_C_TRAMOS2)*(1.0) || '%', v_log_count, v_idproceso, 'info');
	            				-- CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_POSITION PROCESADO ' || ROUND((v_cont_cursor_C_POSITION*100)/(v_total_filas_C_POSITION)*(1.0),1) ||
	            				-- '%  || C_PAGOS PROCESADO '|| (v_cont_cursor_C_PAGOS*100)/(v_total_filas_C_PAGOS)*(1.0) || 
	            				-- '%  || C_TRAMOS2 PROCESADO '|| (v_cont_cursor_C_TRAMOS2*100)/(v_total_filas_C_TRAMOS2)*(1.0) || '%' 
	            				-- , v_log_count, v_idproceso, 'info');
	            			END IF;
	            			----------------------------------------------------------------------------------------------------------------------------------------------------------------------------                                      
                                	SELECT PRODUCTO_DESDE,PRODUCTO_HASTA,COEF_TIPO_BASE_TRAMO2,COEF_CORRECTOR_TRAMO2
            						INTO v_c_tramos2_producto_desde, v_c_tramos2_producto_hasta, v_c_tramos2_coef_tipo_base_tramo2, v_c_tramos2_coef_corrector_tramo2
            						FROM :C_TRAMOS2 LIMIT 1 OFFSET :v_offset;
                                    
                                            --Como puede tratarse mas de un rango de productos tenemos que diferenciar entre la primera iteracion y las siguientes.
                                            IF v_cont_productos = 0 THEN
                                                v_producto_reparto := '
    												AND (PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_hasta || '''';
                                            
                                                v_select_base_reparto := '
    												(CASE WHEN PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_hasta || '''
        												THEN ''' || v_c_tramos2_coef_tipo_base_tramo2 || '''';
                                            
                                                v_select_coef_reparto := '
    												(CASE WHEN PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_hasta || '''
        												THEN ' || v_c_tramos2_coef_corrector_tramo2;
                                            
                                            ELSE
                                                v_producto_reparto := v_producto_reparto || '
    												OR PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_hasta || '''';
                                            
                                                v_select_base_reparto := v_select_base_reparto || '
    												WHEN PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_hasta || '''
    												    THEN ''' || v_c_tramos2_coef_tipo_base_tramo2 || '''';
                                            
                                                v_select_coef_reparto := v_select_coef_reparto || '
    												WHEN PRODUCTID BETWEEN ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_desde || ''' AND ''' || v_c_pagos_cia_codigo || v_c_tramos2_producto_hasta || '''
        												THEN ' || v_c_tramos2_coef_corrector_tramo2;
                                            END IF;
                                            
                                            v_cont_productos := v_cont_productos + 1;
                                            
                                        -- EXCEPTION
                                        --     WHEN NO_DATA_FOUND THEN
                                        --         v_DesError := 'No hay productos para repartir el Tramo2. No se puede realizar el reparto.';
                                        --         --RAISE HAY_ERROR_LOOP;
                                        --     WHEN OTHERS THEN
                                        --         v_DesError := 'LOOP C_TRAMOS2. Position: ' || v_c_position_pos_prin || '. Error: ' || v_DesError || '. SQLCOD(' || SQLCODE || ') ' ||SQLERRM;
                                        --         RAISE HAY_ERROR;
                                        END;
                                END FOR; --TRAMOS
                                    
                                    --Completamos los filtros de los rangos de productos necesarios.
                                    --v_producto_reparto := v_producto_reparto || ')';
                                    IF v_producto_reparto IS NULL OR v_producto_reparto = '' THEN
                                		v_producto_reparto := '';
                                	ELSE	
                                		v_producto_reparto := v_producto_reparto || ')';
                                	END IF;
                                    
                                    --v_select_base_reparto := v_select_base_reparto || ' END),';
                                    IF v_select_base_reparto IS NULL OR v_select_base_reparto = '' THEN
                                		v_select_base_reparto := '';
                                	ELSE	
                                		v_select_base_reparto := v_select_base_reparto || ' END),';
                                	END IF;
                                    
                                    --ALM 20211215: Ponemos una coma al final porque se ha anadido un nuevo campo a la tabla TEMPORAL y FINAL.
                                    --v_select_coef_reparto := v_select_coef_reparto || ' END)';
                                   -- v_select_coef_reparto := v_select_coef_reparto || ' END),';
                                   IF v_select_coef_reparto IS NULL OR v_select_coef_reparto = '' THEN
                                		v_select_coef_reparto := 0;
                                	ELSE	
                                		v_select_coef_reparto := v_select_coef_reparto || ' END),';
                                	END IF;
                                    
                                    --ALM 20220704: Si en el EARNINGCODEID viene el producto filtramos unicamente para ese producto.
                                    IF v_c_pagos_earningcodeid LIKE '%-%' THEN
                                        v_producto_reparto := 'AND PRODUCTID = ''' || RIGHT(v_c_pagos_earningcodeid,7) || '''';
                                        --ALM 20220705: No tenemos en cuenta la base de reparto ni el coeficiente de las tablas de workflow ya que son casos excepcionales.
                                        v_select_base_reparto := '''N/X'',';
                                        v_select_coef_reparto := '100,';
                                    END IF;
                                    
                                   
                                    v_DesError := 'PAGOS REPARTIDOS TRAMO2. PERIODICIDAD I. INSERT TABLA TEMPORAL';
                                    
                                    --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Filtros Productos Tramo2: ' || v_producto_reparto, v_log_count, v_idproceso, 'info');
                                    --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Campos Base Coef. Tramo2: ' || v_select_base_reparto, v_log_count, v_idproceso, 'info');
                                    --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Campos Porcentaje Coef. Tramo2: ' || v_select_coef_reparto, v_log_count, v_idproceso, 'info');
                                    
                                    --Borramos la tabla temporal para cargar unicamente las polizas del reparto en curso
                                    -- EXECUTE IMMEDIATE 'TRUNCATE TABLE EXT.TEMP_REPEXT_FILE';
                                   -- CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-TRUNCATE TEMP_REPEXT_FILE LINEA 6304 ', v_log_count, v_idproceso, 'info');
                                    TRUNCATE TABLE EXT.TEMP_REPEXT_FILE;
                                    
                                    -- RAP 20211222 Si el tramo 1 se ha calculado con acumulado anual, el tramo 2 se calculara con acumulado anual tambien
                                    IF v_existe_base_reparto_tramo1 = 0 THEN
                                        --Ejecutamos la insert para guardar los datos de las polizas que van a intervenir en el reparto.
                                        v_insert_repext_temporal := 'INSERT INTO EXT.TEMP_REPEXT_FILE( ' ||
                            				'PARTICIPANTSEQ,POSITIONSEQ,PERIODSEQ,PERIODO,POSITIONNAME,POS_PRIN,NIF' ||
											',MANAGER_POS_PRIN,ORDERID,LINENUMBER,SUBLINENUMBER,EVENTTYPEID,PRODUCTID,CODIGO_POLIZA,COMPENSATIONDATE' ||
											',ESTADO,PROGRAMA,TIPO_PAGO,DEPOSITO,DEPOSITSEQ,IMPORTE_PAGO,EARNINGCODEID,EARNINGGROUPID,TIPO_DOCUMENTO' ||
											',TIPO_AGENTE,IMPORTE'||
											',TIPO_REPARTO,NUM_TRAMO,REPARTO_TIPO_BASE,REPARTO_PORCENTAJE' ||
											',POLIZA_FISICA,POLIZA_CORREGIDA,PRIMA_CORREGIDA,PRIMA_NETA,PRIMA_NETA_ANUAL,PRIMA_COMIS,COEF_TIPO_BASE,COEF_CORRECTOR,COD_AGENTE,TIPO_LIQ)' ||
                                			'SELECT ' || IFNULL(:v_c_pagos_participantseq,0) || ' PARTICIPANTSEQ, '||
											IFNULL(:v_c_pagos_positionseq,0) ||' POSITIONSEQ,' ||
											:v_periodSeq || ' PERIODSEQ,' ||
											'''' || :v_periodName || ''' PERIODO,' ||
											'''' ||IFNULL(:v_c_pagos_pos_callidus,'') || ''' POSITIONNAME,' ||
											'''' ||IFNULL(:v_c_pagos_pos_prin,'') || ''' POS_PRIN,'||
											'''' ||IFNULL(:v_c_pagos_nif,'') || ''' NIF,'||
											'''' ||IFNULL(:v_c_pagos_manager_pos_prin,'') || ''' MANAGER_POS_PRIN,'||
											'ORDERID,'||
    										'LINENUMBER,'||
    										'SUBLINENUMBER,'||
    										'EVENTTYPEID,'||
    										'PRODUCTID,'||
    										'CODIGO_POLIZA,'||
    										'COMPENSATIONDATE,'||
    										'ESTADO,'||
    										'''' || IFNULL(:v_c_pagos_programa,'') || ''' PROGRAMA,'||
    										'''' || IFNULL(:v_c_pagos_tipo_pago,'') || ''' TIPO_PAGO,'||
    										'''' || IFNULL(:v_c_pagos_deposito,'') || ''' DEPOSITO,'||
    										IFNULL(:v_c_pagos_depositseq,0) || ' DEPOSITSEQ,'||
    										IFNULL(:v_c_pagos_importe,0) || ' IMPORTE_PAGO,'||
    										'''' || IFNULL(:v_c_pagos_earningcodeid,'') || ''' EARNINGCODEID,'||
    										'''' || IFNULL(:v_c_pagos_earninggroupid,'') || ''' EARNINGGROUPID,'||
    										'''' || IFNULL(:v_c_pagos_tipo_documento,'') || ''' TIPO_DOCUMENTO,'||
    										IFNULL(:v_c_pagos_tipo_agente,0) || ' TIPO_AGENTE,'||
    										'0 AS IMPORTE,'||
    										'''' || IFNULL(:v_c_pagos_tipo_reparto,'') || ''' TIPO_REPARTO,'||
    										'2 AS NUM_TRAMO,'||
    										'''' || IFNULL(:v_c_pagos_tipo_base_tramo2,'') || ''' REPARTO_TIPO_BASE,'||
    										'''' || IFNULL(:v_c_pagos_porcentaje_tramo2,0) || ''' REPARTO_PORCENTAJE,'||
    										'POLIZA_FISICA*(-1),'||
    										'POLIZA_CORREGIDA*(-1),'||
    										'PRIMA_CORREGIDA*(-1),'||
    										'PRIMA_NETA*(-1),'||
    										'PRIMA_NETA_ANUAL*(-1),'||
    										'PRIMA_COMIS_S4*(-1),'||
    										'' || IFNULL(:v_select_base_reparto,'') || ' COEF_TIPO_BASE,'||
    										:v_select_coef_reparto || ' COEF_CORRECTOR,'||
    										'COD_AGENTE,'||
    										'NULL AS TIPO_LIQ ' ||
    										'FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE ' ||
    										'WHERE ' || :v_position_reparto || ' '||
    										IFNULL(:v_periodo_reparto,'') || ' ' ||
											IFNULL(:v_tramo_reparto,'') || ' ' ||
											IFNULL(:v_producto_reparto,'');
                                    
                                        -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-15 TEMP_REPEXT_FILE. v_insert_repext_temporal: ' || v_insert_repext_temporal, v_log_count, v_idproceso, 'info');
                                        
                                        EXECUTE IMMEDIATE v_insert_repext_temporal;
                                        -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-15 TEMP_REPEXT_FILE. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                                        -- COMMIT;
          --                              INSERT INTO EXT.TEMP_REPEXT_FILE_DEBUG SELECT * FROM EXT.TEMP_REPEXT_FILE;
		--			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-15 TEMP_REPEXT_FILE_DEBUG. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                                    END IF; --RAP
                                    
                                    --Comprobamos si se ha encontrado Base de Reparto, sino es asi buscamos la Base sobre el siguiente nivel indicado.
                                    SELECT COUNT(*) INTO v_existe_base_reparto
                                    FROM EXT.TEMP_REPEXT_FILE;
                                    
                                    IF v_existe_base_reparto = 0 THEN
                                        
                                        CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Position: ' || IFNULL(v_c_pagos_pos_prin,'') || ', EarningCodeId: ' 
                                                             || IFNULL(v_c_pagos_earningcodeid,'') || ', EarningGroupId: ' 
                                                             || IFNULL(v_c_pagos_earninggroupid,'') || '. No existe Base de Reparto para el Tramo2. Cogemos el Acumulado Anual.', v_log_count, v_idproceso, 'info');
                                        
                                        --Cogemos como Base de Reparto el Acumulado del Anio.
                                        --Utilizamos el PERIODSEQ porque la tabla esta particionada por este campo y la consulta funcionara mas rapido asi.
                                        --v_periodo_reparto_new := 'AND EXTRACT(YEAR FROM COMPENSATIONDATE) = ' || EXTRACT(YEAR FROM v_c_pagos_fecha_cargo);
                                        v_periodo_reparto_new := 'AND PERIODSEQ IN (
        									SELECT X.PERIODSEQ FROM TCMP.CS_PERIOD X 
        									WHERE X.PERIODTYPESEQ = 2814749767106561 AND X.REMOVEDATE = TO_DATE(''22000101'',''YYYYMMDD'') 
        									AND EXTRACT(YEAR FROM X.STARTDATE) = ' || EXTRACT(YEAR FROM v_c_pagos_fecha_cargo) || ')';
                                        
                                        --ALM 20211125: Modificamos la varible v_tramo_reparto si el tipo de base es de polizas porque esta depende del periodo y de la position.
                                        IF v_c_pagos_tipo_base_tramo2 = 'PFP' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --POLIZAS FISICAS PRODUCCION
                                            v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    											AND (POLIZA_FISICA > 0
    											    OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
    											        SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
    											        FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
    											        WHERE ' || v_position_reparto || '
    											        ' || v_periodo_reparto_new || '
    											        AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    											        AND POLIZA_FISICA > 0)
    											    AND POLIZA_CORREGIDA >= 0)';
                                            
                                        ELSEIF v_c_pagos_tipo_base_tramo2 = 'UPP' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --POLIZAS CORREGIDAS PRODUCCION
                                            v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
    											AND (POLIZA_CORREGIDA > 0
        											OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
            											SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
            											FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
            											WHERE ' || v_position_reparto || '
            											' || v_periodo_reparto_new || '
            											AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
            											AND POLIZA_CORREGIDA > 0)
        											AND POLIZA_CORREGIDA >= 0)';
                                            
                                        ELSEIF v_c_pagos_tipo_base_tramo2 = 'PFC' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --POLIZAS FISICAS CARTERA
                                            v_tramo_reparto := 'AND EVENTTYPEID = ''81''
    											AND (POLIZA_FISICA > 0
        											OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
            											SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
            											FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
            											WHERE ' || v_position_reparto || '
            											' || v_periodo_reparto_new || '
            											AND EVENTTYPEID = ''81''
            											AND POLIZA_FISICA > 0)
        											AND POLIZA_FISICA >= 0)';
                                            
                                        END IF;
                                        
                                        -- RAP 20211223 tiene que coger la base de acumulado anual si no encuentra reparto para el tramo 2 o 
                                        -- si no ha encontrado reparto para el tramo1 y lo ha calculado con el acumulado anual
                                        
                                        IF v_existe_base_reparto_tramo1 = 1 THEN
                                            --Ejecutamos la insert para guardar los datos de las polizas que van a intervenir en el reparto.
                                            v_insert_repext_temporal := 'INSERT INTO EXT.TEMP_REPEXT_FILE( ' ||
                            					'PARTICIPANTSEQ,POSITIONSEQ,PERIODSEQ,PERIODO,POSITIONNAME,POS_PRIN,NIF' ||
