    												'''' || IFNULL(:v_c_pagos_earninggroupid,'') || ''' EARNINGGROUPID,'||
    												'''' || IFNULL(:v_c_pagos_tipo_documento,'') || ''' TIPO_DOCUMENTO,'||
    												IFNULL(:v_c_pagos_tipo_agente,0) || ' TIPO_AGENTE,'||
    												'0 AS IMPORTE,'||
    												'''' || IFNULL(:v_c_pagos_tipo_reparto,'') || ''' TIPO_REPARTO,'||
    												'2 AS NUM_TRAMO,'||
    												'''' || IFNULL(:v_c_pagos_tipo_base_tramo2,'') || ''' REPARTO_TIPO_BASE,'||
    												'''' || IFNULL(:v_c_pagos_porcentaje_tramo2,0) || ''' REPARTO_PORCENTAJE,'||
													'SUM(POLIZA_FISICA)*(-1) POLIZA_FISICA,'||
													'SUM(POLIZA_CORREGIDA)*(-1) POLIZA_CORREGIDA,'||
													'SUM(PRIMA_CORREGIDA)*(-1) PRIMA_CORREGIDA,'||
													'SUM(PRIMA_NETA)*(-1) PRIMA_NETA,'||
													'SUM(PRIMA_NETA_ANUAL)*(-1) PRIMA_NETA_ANUAL,'||
													'SUM(PRIMA_COMIS_S4)*(-1) PRIMA_COMIS ,'||
													'' || IFNULL(:v_select_base_reparto,'') || ' COEF_TIPO_BASE,'||
    												:v_select_coef_reparto || ' COEF_CORRECTOR,'||
    												'''' || IFNULL(:v_c_pagos_pos_prin,'') || ''' AS COD_AGENTE,'||
    												'NULL AS TIPO_LIQ '||
													'FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE '||
													'WHERE ' || IFNULL(:v_position_reparto_new,'') || ' ' ||
													IFNULL(:v_periodo_reparto_new,'') || ' ' ||
													IFNULL(:v_tramo_reparto,'') || ' ' ||
													IFNULL(:v_producto_reparto,'') || ' ' ||
													'GROUP BY PERIODSEQ,' ||
													'PRODUCTID,' ||
													'COMPENSATIONDATE';
                                        
                                            
                                            -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-23 TEMP_REPEXT_FILE. v_insert_repext_temporal: ' || v_insert_repext_temporal, v_log_count, v_idproceso, 'info');
                                            
                                            EXECUTE IMMEDIATE v_insert_repext_temporal;
                                            -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-23 TEMP_REPEXT_FILE. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                                            -- COMMIT;
             --                               INSERT INTO EXT.TEMP_REPEXT_FILE_DEBUG SELECT * FROM EXT.TEMP_REPEXT_FILE;
			--		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-23 TEMP_REPEXT_FILE_DEBUG. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                                    END IF; -- RAP
            
                                            --Comprobamos si se ha encontrado Base de Reparto, sino es asi buscamos la Base sobre el siguiente nivel indicado.
                                            SELECT COUNT(*) INTO v_existe_base_reparto
                                            FROM EXT.TEMP_REPEXT_FILE;
                                            
                                            IF v_existe_base_reparto = 0 THEN
                                                
                                                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Position: ' || v_c_position_pos_prin || '. No existe Base de Reparto para el Tramo2. Cogemos la Compania.', v_log_count, v_idproceso, 'info');
                                                
                                                --Volvemos a coger el periodo de reparto correspondiente guardado en la varibale v_periodo_reparto
                                                --v_periodo_reparto_new := 'AND EXTRACT(YEAR FROM COMPENSATIONDATE) = ' || EXTRACT(YEAR FROM v_c_pagos_fecha_cargo);
                                                
                                                --No filtramos por Position.
                                                v_position_reparto_new := '1 = 1';
                                                
                                                --ALM 20211125: Modificamos la varible v_tramo_reparto si el tipo de base es de polizas porque esta depende del periodo y de la position.
                                                IF v_c_pagos_tipo_base_tramo2 = 'PFP' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --POLIZAS FISICAS PRODUCCION
                                                    v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
														AND (POLIZA_FISICA > 0
    														OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
        														SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
        														FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
        														WHERE ' || v_position_reparto_new || '
        														' || v_periodo_reparto || '
        														AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
        														AND POLIZA_FISICA > 0)
    														AND POLIZA_FISICA >= 0)';
                                                    
                                                ELSEIF v_c_pagos_tipo_base_tramo2 = 'UPP' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --POLIZAS CORREGIDAS PRODUCCION
                                                    v_tramo_reparto := 'AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
														AND (POLIZA_CORREGIDA > 0
    														OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
        														SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
        														FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
        														WHERE ' || v_position_reparto_new || '
        														' || v_periodo_reparto || '
        														AND EVENTTYPEID IN (''71'',''65'',''66'',''72'')
        														AND POLIZA_CORREGIDA > 0)
    														AND POLIZA_CORREGIDA >= 0)';
                                                    
                                                ELSEIF v_c_pagos_tipo_base_tramo2 = 'PFC' AND v_c_pagos_porcentaje_tramo2 > 0 THEN --POLIZAS FISICAS CARTERA
                                                    v_tramo_reparto := 'AND EVENTTYPEID = ''81''
														AND (POLIZA_FISICA > 0
    														OR (CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID) IN (
        														SELECT DISTINCT CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID
        														FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE
        														WHERE ' || v_position_reparto_new || '
        														' || v_periodo_reparto || '
        														AND EVENTTYPEID = ''81''
        														AND POLIZA_FISICA > 0)
    														AND POLIZA_FISICA >= 0)';
                                                    
                                                END IF;
                                                
                                                --Ejecutamos la insert para guardar los datos de las polizas que van a intervenir en el reparto.
                                                --ALM 20211124: No podemos usar la tabla por producto para el reparto por oficina, regional o compania;
                                                --              porque no podemos aplicar los filtros por poliza necesarios para extraer los datos correctos.
                                                --              Tendremos que usar la tabla por polizas y agrupar datos.
                                               
                                                --ALM 20211125: Modificamos el sublinenumber para que coja el producto entero en vez de la familia salvo para RRTT, sino no reparte correctamente.
                                                --(CASE WHEN SUBSTR(PRODUCTID,3,1)=''2'' THEN SUBSTR(PRODUCTID,1,4)||''0''||SUBSTR(PRODUCTID,-2) ELSE SUBSTR(PRODUCTID,1,5)||''00'' END),
                                                -- RAP 20211223 tiene que coger la compania si no encuentra reparto para el tramo 2 o 
                                                -- si no ha encontrado reparto para el tramo1 y lo ha calculado con la compania
                                                
                                                IF v_existe_base_reparto_tramo1 = 4 THEN
                                                    
                                                    --ALM 20220315: Devolvemos siempre estado C para no tener registros duplicados para las recuperaciones de SERCO.
                                                    v_insert_repext_temporal := 'INSERT INTO EXT.TEMP_REPEXT_FILE( ' ||
                            				'PARTICIPANTSEQ,POSITIONSEQ,PERIODSEQ,PERIODO,POSITIONNAME,POS_PRIN,NIF' ||
											',MANAGER_POS_PRIN,ORDERID,LINENUMBER,SUBLINENUMBER,EVENTTYPEID,PRODUCTID,CODIGO_POLIZA,COMPENSATIONDATE' ||
											',ESTADO,PROGRAMA,TIPO_PAGO,DEPOSITO,DEPOSITSEQ,IMPORTE_PAGO,EARNINGCODEID,EARNINGGROUPID,TIPO_DOCUMENTO' ||
											',TIPO_AGENTE,IMPORTE'||
											',TIPO_REPARTO,NUM_TRAMO,REPARTO_TIPO_BASE,REPARTO_PORCENTAJE' ||
											',POLIZA_FISICA,POLIZA_CORREGIDA,PRIMA_CORREGIDA,PRIMA_NETA,PRIMA_NETA_ANUAL,PRIMA_COMIS,COEF_TIPO_BASE,COEF_CORRECTOR,COD_AGENTE,TIPO_LIQ)' ||
                                			'SELECT ' || IFNULL(:v_c_pagos_participantseq,0) || ' PARTICIPANTSEQ, '||
													IFNULL(:v_c_pagos_positionseq,0) ||' POSITIONSEQ,' ||
													:v_periodSeq || ' PERIODSEQ,' ||
													'''' || :v_periodName || ''' PERIODO,' ||
													'''' ||IFNULL(:v_c_pagos_pos_callidus,'') || ''' POSITIONNAME,' ||
													'''' ||IFNULL(:v_c_pagos_pos_prin,'') || ''' POS_PRIN,'||
													'''' ||IFNULL(:v_c_pagos_nif,'') || ''' NIF,'||
													'''' ||IFNULL(:v_c_pagos_manager_pos_prin,'') || ''' MANAGER_POS_PRIN,'||
													'PRODUCTID||''99999999999'' AS ORDERID,'||
													'TO_CHAR(COMPENSATIONDATE,''YYYYMM'') AS LINENUMBER,'||
													'(CASE WHEN SUBSTR(PRODUCTID,3,1) = ''2'' THEN SUBSTR(PRODUCTID,1,4) || ''0'' || RIGHT(PRODUCTID,2) ELSE PRODUCTID END) AS SUBLINENUMBER, '||
													'''CIA'' AS EVENTTYPEID,'||
													'PRODUCTID,'||
    												'''99999999999'' AS CODIGO_POLIZA,'||
    												'COMPENSATIONDATE,'||
    												'''C'' AS ESTADO,'||
    												'''' || IFNULL(:v_c_pagos_programa,'') || ''' PROGRAMA,'||
    												'''' || IFNULL(:v_c_pagos_tipo_pago,'') || ''' TIPO_PAGO,'||
    												'''' || IFNULL(:v_c_pagos_deposito,'') || ''' DEPOSITO,'||
    												IFNULL(:v_c_pagos_depositseq,0) || ' DEPOSITSEQ,'||
    												IFNULL(:v_c_pagos_importe,0) || ' IMPORTE_PAGO,'||
    												'''' || IFNULL(:v_c_pagos_earningcodeid,'') || ''' EARNINGCODEID,'||
    												'''' || IFNULL(:v_c_pagos_earninggroupid,'') || ''' EARNINGGROUPID,'||
    												'''' || IFNULL(:v_c_pagos_tipo_documento,'') || ''' TIPO_DOCUMENTO,'||
    												IFNULL(:v_c_pagos_tipo_agente,0) || ' TIPO_AGENTE,'||
    												'0 AS IMPORTE,'||
    												'''' || IFNULL(:v_c_pagos_tipo_reparto,'') || ''' TIPO_REPARTO,'||
    												'2 AS NUM_TRAMO,'||
    												'''' || IFNULL(:v_c_pagos_tipo_base_tramo2,'') || ''' REPARTO_TIPO_BASE,'||
    												'''' || IFNULL(:v_c_pagos_porcentaje_tramo2,0) || ''' REPARTO_PORCENTAJE,'||
													'SUM(POLIZA_FISICA)*(-1) POLIZA_FISICA,'||
													'SUM(POLIZA_CORREGIDA)*(-1) POLIZA_CORREGIDA,'||
													'SUM(PRIMA_CORREGIDA)*(-1) PRIMA_CORREGIDA,'||
													'SUM(PRIMA_NETA)*(-1) PRIMA_NETA,'||
													'SUM(PRIMA_NETA_ANUAL)*(-1) PRIMA_NETA_ANUAL,'||
													'SUM(PRIMA_COMIS_S4)*(-1) PRIMA_COMIS ,'||
													'' || IFNULL(:v_select_base_reparto,'') || ' COEF_TIPO_BASE,'||
    												:v_select_coef_reparto || ' COEF_CORRECTOR,'||
    												'''' || IFNULL(:v_c_pagos_pos_prin,'') || ''' AS COD_AGENTE,'||
    												'NULL AS TIPO_LIQ '||
													'FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE '||
													'WHERE ' || IFNULL(:v_position_reparto_new,'') || ' ' ||
													IFNULL(:v_periodo_reparto_new,'') || ' ' ||
													IFNULL(:v_tramo_reparto,'') || ' ' ||
													IFNULL(:v_producto_reparto,'') || ' ' ||
													'GROUP BY PERIODSEQ,' ||
													'PRODUCTID,' ||
													'COMPENSATIONDATE';
                                        
                                                
                                                    -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-24 TEMP_REPEXT_FILE. v_insert_repext_temporal: ' || v_insert_repext_temporal, v_log_count, v_idproceso, 'info');
                                                    
                                                    EXECUTE IMMEDIATE v_insert_repext_temporal;
                                                    -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-24 TEMP_REPEXT_FILE. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                                                    -- COMMIT;
              --                                      INSERT INTO EXT.TEMP_REPEXT_FILE_DEBUG SELECT * FROM EXT.TEMP_REPEXT_FILE;
			--		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'SMM Insert-24 TEMP_REPEXT_FILE_DEBUG. Número de registros: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
                                                END IF; --RAP
                
                                                --Comprobamos si se ha encontrado Base de Reparto, sino es asi buscamos la Base sobre el siguiente nivel indicado.
                                                SELECT COUNT(*) INTO v_existe_base_reparto
                                                FROM EXT.TEMP_REPEXT_FILE;
                                                
                                                IF v_existe_base_reparto = 0 THEN
                                                    
                                                    v_DesError := 'No se ha podido encontrar una Base de Reparto para el Tramo2 de la Position: ' || v_c_pagos_pos_prin;
                                                    --RAISE HAY_ERROR_LOOP;
														 CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name, v_DesError , v_log_count, v_idproceso, 'debug');
                                                END IF;
                                                
                                            END IF;
                                            
                                        END IF;
                                        
                                    END IF;
                                    
                                END IF;
                                
                                v_DesError := 'PAGOS REPARTIDOS TRAMO2. REPARTO';
                                
                                --Sacamos todos los sumatorios de las variables de polizas y primas para usar aquellos que necesitemos en cada caso.
                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                SELECT SUM(POLIZA_FISICA * (COEF_CORRECTOR/100)),
                                    SUM(POLIZA_CORREGIDA * (COEF_CORRECTOR/100)),
                                    SUM(PRIMA_CORREGIDA * (COEF_CORRECTOR/100)),
                                    SUM(PRIMA_NETA * (COEF_CORRECTOR/100)),
                                    SUM(PRIMA_NETA_ANUAL * (COEF_CORRECTOR/100)),
                                    SUM(PRIMA_COMIS * (COEF_CORRECTOR/100)),
                                    --ALM 20211122: Incluimos los contadores y sumatorios necesarios para los nuevos valores de reparto incluidos.
                                    COUNT(*)
                                INTO v_sum_pol_fis_total,
                                    v_sum_pol_corr_total,
                                    v_sum_prima_corr_total,
                                    v_sum_prima_neta_total,
                                    v_sum_prima_anual_total,
                                    v_sum_prima_comis_total,
                                    --ALM 20211122: Incluimos los contadores y sumatorios necesarios para los nuevos valores de reparto incluidos.
                                    v_cont_pol_total
                                FROM EXT.TEMP_REPEXT_FILE;
                                
                                
                                -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por polizas fisicas: ' || v_sum_pol_fis_total, v_log_count, v_idproceso, 'info');
                                -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por polizas corregidas (todas las garantias): ' || v_sum_pol_corr_total, v_log_count, v_idproceso, 'info');
                                -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por primas corregidas (todas las garantias): ' || v_sum_prima_corr_total, v_log_count, v_idproceso, 'info');
                                -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por primas netas (todas las garantias): ' || v_sum_prima_neta_total, v_log_count, v_idproceso, 'info');
                                -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por primas anualizadas (todas las garantias): ' || v_sum_prima_anual_total, v_log_count, v_idproceso, 'info');
                                -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Sumatorio total por primas comisionable (todas las garantias): ' || v_sum_prima_comis_total, v_log_count, v_idproceso, 'info');
                                -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Conteo total por polizas recuperadas: ' || v_cont_pol_total, v_log_count, v_idproceso, 'info');
                                
                                
                                --Comenzamos con el calculo del reparto.
                                --Sacamos el importe que hay que repartir para este tramo. Este sera el porcentaje corespondiente sobre el importe total.
                                v_importe_reparto_tramo2 := v_c_pagos_importe *v_c_pagos_porcentaje_tramo2 / 100;
                                
                                --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe que hay que repartir para este tramo 2: ' || v_importe_reparto_tramo2, v_log_count, v_idproceso, 'info');
                                
                                --Si este importe es distinto de 0 dividimos este importe segun el tipo de base de reparto entre las polizas implicadas.
                                --ALM 20211123: Hay que usar un distinto para repartir tambien los pagos negativos (balances). Ej: 0889000218 en agosto 2021.
                                --IF v_importe_reparto_tramo2 > 0 THEN
                                IF v_importe_reparto_tramo2 <> 0 THEN
                                
                                    IF v_c_pagos_tipo_base_tramo2 = 'PFP' THEN
                                        IF v_sum_pol_fis_total = 0 THEN
                                            v_DesError := 'No hay polizas fisicas para repartir el Tramo2. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_sum_pol_fis_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'UPP' THEN
                                        IF v_sum_pol_corr_total = 0 THEN
                                            v_DesError := 'No hay polizas corregidas para repartir el Tramo2. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_sum_pol_corr_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRP' THEN
                                        IF v_sum_prima_corr_total = 0 THEN
                                            v_DesError := 'No hay primas corregidas para repartir el Tramo2. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_sum_prima_corr_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PNP' THEN
                                        IF v_sum_prima_neta_total = 0 THEN
                                            v_DesError := 'No hay primas netas para repartir el Tramo2. No se puede realizar el reparto.';
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_sum_prima_neta_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PAP' THEN
                                        IF v_sum_prima_anual_total = 0 THEN
                                            v_DesError := 'No hay primas anualizadas para repartir el Tramo2. No se puede realizar el reparto.';
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_sum_prima_anual_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PCP' THEN
                                        IF v_sum_prima_comis_total = 0 THEN
                                            v_DesError := 'No hay primas comisionables para repartir el Tramo2. No se puede realizar el reparto.';
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_sum_prima_comis_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PFC' THEN
                                        IF v_sum_pol_fis_total = 0 THEN
                                            v_DesError := 'No hay polizas fisicas para repartir el Tramo2. No se puede realizar el reparto.';
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_sum_pol_fis_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PNC' THEN
                                        IF v_sum_prima_neta_total = 0 THEN
                                            v_DesError := 'No hay primas netas para repartir el Tramo2. No se puede realizar el reparto.';
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_sum_prima_neta_total;
                                        END IF;
                                        
                                    --ALM 20211122: Incluimos los nuevos tipos de bases de reparto solicitados.
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRE' THEN
                                        IF v_cont_pol_total = 0 THEN
                                            v_DesError := 'No hay polizas recuperadas con exito para repartir el Tramo2. No se puede realizar el reparto.';
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_cont_pol_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRG' THEN
                                        IF v_cont_pol_total = 0 THEN
                                            v_DesError := 'No hay polizas recuperadas sin exito para repartir el Tramo2. No se puede realizar el reparto.';
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_cont_pol_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRR' THEN
                                        IF v_cont_pol_total = 0 THEN
                                            v_DesError := 'No hay primas recuperadas para repartir el Tramo2. No se puede realizar el reparto.';
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_cont_pol_total;
                                        END IF;
                                        
                                    ELSEIF v_c_pagos_tipo_base_tramo2 = 'NAP' THEN
                                        IF v_cont_pol_total = 0 THEN
                                            v_DesError := 'No hay asegurados de produccion para repartir el Tramo2. No se puede realizar el reparto.';
                                            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                            --RAISE HAY_ERROR_LOOP;
                                        ELSE
                                            v_importe_por_poliza := v_importe_reparto_tramo2 / v_cont_pol_total;
                                        END IF;
                                        
                                    ELSE
                                        v_DesError := 'La base de reparto definida del Tramo2 no esta contemplada: ' || v_c_pagos_tipo_base_tramo2 || '. No se puede realizar el reparto.';
                                        --RAISE HAY_ERROR_LOOP;
                                        CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                    END IF;
                                    
                                END IF;
                                
                                --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe para cada una de las polizas implicadas en el tramo 2: ' || v_importe_por_poliza, v_log_count, v_idproceso, 'info');
                                
                                v_DesError := 'PAGOS REPARTIDOS TRAMO2. LOOP REPARTO';
                                v_importe_repartido := 0;
                                v_importe_comprobacion := 0;
                                
                                --Recorremos las polizas implicadas calculando el importe para cada una.
                                C_REPARTO2 =
                                    SELECT *
                                    FROM EXT.TEMP_REPEXT_FILE
                                    --ALM 20220630: Incluimos la fecha de compensacion para evitar problemas por modificaciones erroneas de Comercial en Commissions.
                                    --              Sino se incluye algunas polizas parecen duplicadas aunque sean la misma. Ej: 01501263150499000000000N3812 para Junio 2022.
                                    --ORDER BY CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID)
                                    ORDER BY CODIGO_POLIZA,LINENUMBER,SUBLINENUMBER,EVENTTYPEID,COMPENSATIONDATE;


                                    
                                v_total_filas_C_REPARTO2 = RECORD_COUNT(:C_REPARTO2);
                              --  CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_REPARTO2 TOTAL REGISTROS ' || v_total_filas_C_REPARTO2, v_log_count, v_idproceso, 'info');  
            					v_fila_C_REPARTO2 := 0;
                            	v_cont_cursor_C_REPARTO2 := 0;
                            	
            					FOR v_fila_C_REPARTO2 IN 1 .. v_total_filas_C_REPARTO2 DO
                            	--REPARTO2
                            	BEGIN
                            		v_offset := v_fila_C_REPARTO2 - 1;
	            					-- CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_REPARTO2  REGISTRO ' || v_offset || ' DEL TOTAL ' || v_total_filas_C_REPARTO2, v_log_count, v_idproceso, 'info');  
						 	----------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	            			v_cont_cursor_C_REPARTO2 := v_cont_cursor_C_REPARTO2 + 1;
	            			IF (MOD(v_cont_cursor_C_REPARTO2,100)=0 OR (v_cont_cursor_C_REPARTO2 = v_total_filas_C_REPARTO2)) THEN
	            				CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_REPARTO2 REGISTRO ' || v_cont_cursor_C_REPARTO2|| ' DE ' || v_total_filas_C_REPARTO2 || ' - PROCESADO '|| (v_cont_cursor_C_REPARTO2*100)/(v_total_filas_C_REPARTO2)*(1.0) || '%', v_log_count, v_idproceso, 'info');
	            				-- 	CALL EXT.LIB_CONSTANTES:WRITE_LOG(v_permisos_log,v_proc_name,'SMM-CURSOR C_POSITION PROCESADO ' || ROUND((v_cont_cursor_C_POSITION*100)/(v_total_filas_C_POSITION)*(1.0),1) ||
	            				-- '%  || C_PAGOS PROCESADO '|| (v_cont_cursor_C_PAGOS*100)/(v_total_filas_C_PAGOS)*(1.0) || 
	            				-- '%  || C_REPARTO2 PROCESADO '|| (v_cont_cursor_C_REPARTO2*100)/(v_total_filas_C_REPARTO2)*(1.0) || '%' 
	            				-- , v_log_count, v_idproceso, 'info');
	            			END IF;
	            			---------------------------------------------------------------------------------------------------------------------------------------------------------------------------- 	            					
	            					SELECT COEF_CORRECTOR, CODIGO_POLIZA, LINENUMBER, SUBLINENUMBER, EVENTTYPEID, COMPENSATIONDATE
	            						, PRIMA_CORREGIDA, COEF_TIPO_BASE, PRIMA_NETA, PRIMA_NETA_ANUAL, PRIMA_COMIS, ORDERID
	            					INTO v_c_reparto2_coef_corrector, v_c_reparto2_codigo_poliza, v_c_reparto2_linenumber, v_c_reparto2_sublinenumber, v_c_reparto2_eventtypeid, v_c_reparto2_compensationdate
	            						, v_c_reparto2_prima_corregida, v_c_reparto2_coef_tipo_base, v_c_reparto2_prima_neta, v_c_reparto2_prima_neta_anual, v_c_reparto2_prima_comis, v_c_reparto2_orderid
	            					FROM :C_REPARTO2 
	            					LIMIT 1 OFFSET :v_offset;
                                        
                                        --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio LOOP C_REPARTO2: ' || v_c_reparto2_orderid, v_log_count, v_idproceso, 'info');
                                        
                                        --Si el coeficinete corrector es mayor que 0 calculamos el importe correspondiente.
                                        IF v_c_reparto2_coef_corrector > 0 THEN
                                        
                                            --Primero sacamos los sumatorios de las variables de polizas y primas agrupados para cada poliza (necesario para el reparto de RRTT).
                                            --Ademas, sumamos los porcentajes de los coeficientes para aplicar una base 100 sobre ellos y el numero de registros.
                                            --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                            SELECT SUM(POLIZA_FISICA * (COEF_CORRECTOR/100)),
                                                SUM(POLIZA_CORREGIDA * (COEF_CORRECTOR/100)),
                                                SUM(PRIMA_CORREGIDA * (COEF_CORRECTOR/100)),
                                                SUM(PRIMA_NETA * (COEF_CORRECTOR/100)),
                                                SUM(PRIMA_NETA_ANUAL * (COEF_CORRECTOR/100)),
                                                SUM(PRIMA_COMIS * (COEF_CORRECTOR/100)),
                                                SUM(COEF_CORRECTOR),
                                                COUNT(COEF_CORRECTOR)
                                            INTO v_sum_pol_fis,
                                                v_sum_pol_corr,
                                                v_sum_prima_corr,
                                                v_sum_prima_neta,
                                                v_sum_prima_anual,
                                                v_sum_prima_comis,
                                                v_sum_porc_coef,
                                                v_num_porc_coef
                                            FROM EXT.TEMP_REPEXT_FILE
                                            WHERE CODIGO_POLIZA = v_c_reparto2_codigo_poliza
                                            	AND LINENUMBER = v_c_reparto2_linenumber
                                            	AND SUBLINENUMBER = v_c_reparto2_sublinenumber
                                            	AND EVENTTYPEID = v_c_reparto2_eventtypeid
                                            	--ALM 20220630: Incluimos la fecha de compensacion para evitar problemas por modificaciones erroneas de Comercial en Commissions.
                                            	--              Sino se incluye algunas polizas parecen duplicadas aunque sean la misma. Ej: 01501263150499000000000N3812 para Junio 2022.
                                            	AND COMPENSATIONDATE = v_c_reparto2_compensationdate;
                                            
                                            --Multiplicamos el importe a repartir a cada poliza por el sumatorio de polizas o primas que cuentan para ella.
                                            IF v_c_pagos_tipo_base_tramo2 = 'PFP' THEN
                                                --ALM 20240408: Incluimos la multiplicacion por el porcentaje en caso de tener tipo de base distinta de 'N/A' 
                                                --v_importe_poliza := v_importe_por_poliza * v_sum_pol_fis;
                                                IF v_c_reparto2_coef_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_pol_fis * (v_c_reparto2_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_pol_fis;
                                                END IF;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo2 = 'UPP' THEN
                                                v_importe_poliza := v_importe_por_poliza * v_sum_pol_corr;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRP' THEN
                                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_corregida,0);
                                                --ALM 20220223: Usamos el sumatorio en lugar del valor de la poliza, si es unica sera lo mismo, pero para RRTT debe usarse.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_corregida,0) * (v_c_reparto2_coef_corrector/100);
                                                IF v_c_reparto2_coef_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_prima_corr * (v_c_reparto2_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_corregida,0) * (v_c_reparto2_coef_corrector/100);
                                                END IF;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo2 = 'PNP' THEN
                                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_neta,0);
                                                --ALM 20220223: Usamos el sumatorio en lugar del valor de la poliza, si es unica sera lo mismo, pero para RRTT debe usarse.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_neta,0) * (v_c_reparto2_coef_corrector/100);
                                                IF v_c_reparto2_coef_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_prima_neta * (v_c_reparto2_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_neta,0) * (v_c_reparto2_coef_corrector/100);
                                                END IF;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo2 = 'PAP' THEN
                                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_neta_ANUAL,0);
                                                --ALM 20220223: Usamos el sumatorio en lugar del valor de la poliza, si es unica sera lo mismo, pero para RRTT debe usarse.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_neta_ANUAL,0) * (v_c_reparto2_coef_corrector/100);
                                                IF v_c_reparto2_coef_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_prima_anual * (v_c_reparto2_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_neta_ANUAL,0) * (v_c_reparto2_coef_corrector/100);
                                                END IF;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo2 = 'PCP' THEN
                                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_comis,0);
                                                --ALM 20220223: Usamos el sumatorio en lugar del valor de la poliza, si es unica sera lo mismo, pero para RRTT debe usarse.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_comis,0) * (v_c_reparto2_coef_corrector/100);
                                                IF v_c_reparto2_coef_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_prima_comis * (v_c_reparto2_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_comis,0) * (v_c_reparto2_coef_corrector/100);
                                                END IF;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo2 = 'PFC' THEN
                                                v_importe_poliza := v_importe_por_poliza * v_sum_pol_fis;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo2 = 'PNC' THEN
                                                --ALM 20211209: Multiplicamos por el Coeficiente Corrector para tenerlo en cuenta en el reparto.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_neta,0);
                                                --ALM 20220223: Usamos el sumatorio en lugar del valor de la poliza, si es unica sera lo mismo, pero para RRTT debe usarse.
                                                --v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_neta,0) * (v_c_reparto2_coef_corrector/100);
                                                IF v_c_reparto2_coef_tipo_base <> 'N/A' THEN
                                                    v_importe_poliza := v_importe_por_poliza * v_sum_prima_neta * (v_c_reparto2_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza * IFNULL(v_c_reparto2_prima_neta,0) * (v_c_reparto2_coef_corrector/100);
                                                END IF;
                                                
                                            --ALM 20211122: Incluimos los nuevos tipos de bases de reparto solicitados.
                                            ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRE' THEN
                                                v_importe_poliza := v_importe_por_poliza;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRG' THEN
                                                v_importe_poliza := v_importe_por_poliza;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo2 = 'PRR' THEN
                                                --ALM 20211122: No esta incluido este valor en las tablas de reparto.
                                                --v_importe_poliza := v_importe_por_poliza * C_REPARTO2.IMPORTE_COMISON;
                                                v_importe_poliza := v_importe_por_poliza;
                                                
                                            ELSEIF v_c_pagos_tipo_base_tramo2 = 'NAP' THEN
                                                --JGE 20240322 Correo Ismael reparto 02-2024 utilizar primas anualizadas de produccion                                            
                                                --ALM 20240405: Segun el COEF_TIPO_BASE usamos el sumatorio de la base dividida por el total y aplicamos el porcentaje de la misma.
                                                --              Hay multiplicar por el numero total de polizas (v_cont_pol_total) para que se reparta el importe integro y no solo el de una pooliza.
                                                --ALM 20240408: No multiplicamos por el procentaje corrector ya que se hace en el paso siguiente.
                                                --              FINALMENTE DESHACEMOS EL CAMBIO PORQUE NO FUNCIONA APLICANDOLO DESPUES PARA TODOS LOS CASOS. PENDIENTE INVESTIGAR.
                                                IF v_c_reparto2_coef_tipo_base = 'PAP' THEN
												-- LFC 20251231: Cambio por error en división / 0
													IF v_sum_prima_anual_total = 0 THEN
														v_importe_poliza := v_importe_por_poliza ;
													ELSE
														v_importe_poliza := v_importe_por_poliza*v_cont_pol_total*v_sum_prima_anual/v_sum_prima_anual_total
																												*(v_c_reparto2_coef_corrector/100);
													END IF;															
                                                ELSEIF v_c_reparto2_coef_tipo_base = 'PNP' THEN
                                                    v_importe_poliza := v_importe_por_poliza*v_cont_pol_total*v_sum_prima_neta/v_sum_prima_neta_total
                                                                                                             *(v_c_reparto2_coef_corrector/100);
                                                ELSE
                                                    v_importe_poliza := v_importe_por_poliza;
                                                END IF;
                                                
                                            ELSE
                                                v_DesError := 'La base de reparto definida del Tramo2 no esta contemplada: ' || v_c_pagos_tipo_base_tramo2 || '. No se puede realizar el reparto.';
                                                --RAISE HAY_ERROR_LOOP;
                                                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                            END IF;
                                            
                                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe para cada una de las polizas implicadas en el tramo 2: ' || v_importe_poliza, v_log_count, v_idproceso, 'info');
                                        
                                            --Calculamos el importe de cada una de las polizas
                                            --ALM 20211105: EN EL CUMPLE DE TANIA!!! Controlamos los valores de la Prima para cada caso para evitar posibles divisiones por 0.
                                            --ALM 20240408: Quitamos el uso de las variables v_num_porc_coef y v_sum_porc_coef ya que se anulan una a la otra.
                                            --              ESTE CAMBIO NO FUNCIONA, HABRIA QUE INVESTIGAR EL MOTIVO. LO DEJAMOS COMO ESTABA HASTA QUE SE PUEDA REVISAR.
                                            IF v_c_reparto2_coef_tipo_base = 'PRP' THEN
                                                
                                                IF v_c_reparto2_prima_corregida <> 0 THEN
                                                    v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto2_coef_corrector/v_sum_porc_coef)
                                                                                                           *(IFNULL(v_c_reparto2_prima_corregida,0)/v_sum_prima_corr),2);
                                                    --v_importe_repartido := v_importe_poliza*(v_c_reparto2_coef_corrector/100)*(IFNULL(v_c_reparto2_prima_corregida,0)/v_sum_prima_corr);
                                                ELSE
                                                    v_importe_repartido := 0;
                                                END IF;
                                                
                                            ELSEIF v_c_reparto2_coef_tipo_base = 'PNP' THEN
                                                
                                                IF v_c_reparto2_prima_neta <> 0 THEN
                                                    v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto2_coef_corrector/v_sum_porc_coef)
                                                                                                           *(IFNULL(v_c_reparto2_prima_neta,0)/v_sum_prima_neta),2);
                                                    --v_importe_repartido := v_importe_poliza*(v_c_reparto2_coef_corrector/100)*(IFNULL(v_c_reparto2_prima_neta,0)/v_sum_prima_neta);
                                                ELSE
                                                    v_importe_repartido := 0;
                                                END IF;
                                                
                                            ELSEIF v_c_reparto2_coef_tipo_base = 'PAP' THEN
                                                
                                                --ALM 20211209: Si el sumatorio de la Prima Anual es 0 y el de la Prima Neta no usamos este ultimo para el calculo.
                                                --IF v_c_reparto2_prima_neta_ANUAL <> 0 THEN
                                                --    v_importe_repartido := v_importe_poliza*v_num_porc_coef*(v_c_reparto2_coef_corrector/v_sum_porc_coef)
                                                --                                                           *(IFNULL(v_c_reparto2_prima_neta_ANUAL,0)/v_sum_prima_anual);
                                                --ELSE
                                                --    v_importe_repartido := 0;
                                                --END IF;
                                                IF v_sum_prima_anual = 0 AND v_sum_prima_neta <> 0 THEN
                                                    
                                                    IF v_c_reparto2_prima_neta <> 0 THEN
                                                        v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto2_coef_corrector/v_sum_porc_coef)
                                                                                                               *(IFNULL(v_c_reparto2_prima_neta,0)/v_sum_prima_neta),2);
                                                        --v_importe_repartido := v_importe_poliza*(v_c_reparto2_coef_corrector/100)*(IFNULL(v_c_reparto2_prima_neta,0)/v_sum_prima_neta);
                                                    ELSE
                                                        v_importe_repartido := 0;
                                                    END IF;
                                                    
                                                --Si ambas primas son 0 no usamos ninguna de las primas y aplicamos directamente el porcentaje.
                                                ELSEIF v_sum_prima_anual = 0 AND v_sum_prima_neta = 0 THEN
                                                    
                                                    IF SUBSTR(v_c_reparto2_orderid,3,1) = '2' AND SUBSTR(v_c_reparto2_orderid,5,1) = '0' THEN
                                                        v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto2_coef_corrector/v_sum_porc_coef),2);
                                                        --v_importe_repartido := v_importe_poliza*(v_c_reparto2_coef_corrector/100);
                                                    ELSE
                                                        v_importe_repartido := 0;
                                                    END IF;
                                                    
                                                ELSE
                                                    
                                                    IF v_c_reparto2_prima_neta_ANUAL <> 0 THEN
                                                        v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto2_coef_corrector/v_sum_porc_coef)
                                                                                                               *(IFNULL(v_c_reparto2_prima_neta_ANUAL,0)/v_sum_prima_anual),2);
                                                        --v_importe_repartido := v_importe_poliza*(v_c_reparto2_coef_corrector/100)*(IFNULL(v_c_reparto2_prima_neta_ANUAL,0)/v_sum_prima_anual);
                                                    ELSE
                                                        v_importe_repartido := 0;
                                                    END IF;
                                                    
                                                END IF;
                                                
                                            ELSEIF v_c_reparto2_coef_tipo_base = 'PCP' THEN
                                                
                                                IF v_c_reparto2_prima_comis <> 0 THEN
                                                    v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto2_coef_corrector/v_sum_porc_coef)
                                                                                                           *(IFNULL(v_c_reparto2_prima_comis,0)/v_sum_prima_comis),2);
                                                    --v_importe_repartido := v_importe_poliza*(v_c_reparto2_coef_corrector/100)*(IFNULL(v_c_reparto2_prima_comis,0)/v_sum_prima_comis);
                                                ELSE
                                                    v_importe_repartido := 0;
                                                END IF;
                                                
                                            ELSEIF v_c_reparto2_coef_tipo_base = 'PNC' THEN
                                                
                                                IF v_c_reparto2_prima_neta <> 0 THEN
                                                    v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto2_coef_corrector/v_sum_porc_coef)
                                                                                                           *(IFNULL(v_c_reparto2_prima_neta,0)/v_sum_prima_neta),2);
                                                    --v_importe_repartido := v_importe_poliza*(v_c_reparto2_coef_corrector/100)*(IFNULL(v_c_reparto2_prima_neta,0)/v_sum_prima_neta);
                                                ELSE
                                                    v_importe_repartido := 0;
                                                END IF;
                                                
                                            --ALM 20211122: Incluimos los nuevos tipos de bases de reparto solicitados.
                                            ELSEIF v_c_reparto2_coef_tipo_base = 'PRR' THEN
                                                
                                                v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto2_coef_corrector/v_sum_porc_coef),2);
                                                --v_importe_repartido := v_importe_poliza*(v_c_reparto2_coef_corrector/100);
                                                
                                            ELSEIF v_c_reparto2_coef_tipo_base = 'N/A' THEN
                                            
                                                v_importe_repartido := round(v_importe_poliza*v_num_porc_coef*(v_c_reparto2_coef_corrector/v_sum_porc_coef),2);
                                                --v_importe_repartido := v_importe_poliza*(v_c_reparto2_coef_corrector/100);
                                            
                                            ELSE
                                                v_DesError := 'La base de los coeficiente de reparto definida del Tramo2 no esta contemplado: ' || 
                                                                                                                      v_c_reparto2_coef_tipo_base || '. No se puede realizar el reparto.';
                                                --RAISE HAY_ERROR_LOOP;
                                                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,v_DesError, v_log_count, v_idproceso, 'info');
                                            END IF;
                                            
                                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe repartido por registro: ' || v_importe_repartido, v_log_count, v_idproceso, 'info');
                                            
                                            --Guardamos el importe repartido acumulado y la ultima transaccion modificada para poder hacer las comprobaciones al acabar el reparto.
                                            --BUSCAR LA MEJOR FORMA DE REDONDEAR
                                            --v_importe_comprobacion := v_importe_comprobacion + ROUND(TRUNC(v_importe_repartido,2),2);
                                            v_importe_comprobacion := v_importe_comprobacion + v_importe_repartido;
                                            --v_importe_comprobacion_tramo2 := v_importe_comprobacion_tramo2 + v_importe_repartido;
                                            v_ult_orderid_modif := v_c_reparto2_orderid;
                                            v_ult_linenumber_modif := v_c_reparto2_linenumber;
                                            v_ult_sublinenumber_modif := v_c_reparto2_sublinenumber;
                                            v_ult_eventtypeid_modif := v_c_reparto2_eventtypeid;
                                            --ALM 20220630: Incluimos la fecha de compensacion para evitar problemas por modificaciones erroneas de Comercial en Commissions.
                                            --              Sino se incluye algunas polizas parecen duplicadas aunque sean la misma. Ej: 01501263150499000000000N3812 para Junio 2022.
                                            v_ult_compensationdate_modif := v_c_reparto2_compensationdate;
                                            
                                            --Actualizamos en la tabla temporal
                                            UPDATE EXT.TEMP_REPEXT_FILE
                                            --BUSCAR LA MEJOR FORMA DE REDONDEAR
                                            --SET IMPORTE = ROUND(TRUNC(v_importe_repartido,2),2)
                                            SET IMPORTE = v_importe_repartido
                                            WHERE ORDERID = v_c_reparto2_orderid
                                                AND LINENUMBER = v_c_reparto2_linenumber
                                                AND SUBLINENUMBER = v_c_reparto2_sublinenumber
                                                AND EVENTTYPEID = v_c_reparto2_eventtypeid
                                                --ALM 20220630: Incluimos la fecha de compensacion para evitar problemas por modificaciones erroneas de Comercial en Commissions.
                                                --              Sino se incluye algunas polizas parecen duplicadas aunque sean la misma. Ej: 01501263150499000000000N3812 para Junio 2022.
                                                AND COMPENSATIONDATE = v_c_reparto2_compensationdate;
                                            
                                            COMMIT;
                                            
                                        END IF;
                                        
                                    -- EXCEPTION
                                    --     WHEN NO_DATA_FOUND THEN
                                    --         v_DesError := 'No hay datos para repartir el Tramo2. No se puede realizar el reparto.';
                                    --         --RAISE HAY_ERROR_LOOP;
                                    --     WHEN OTHERS THEN
                                    --         v_DesError := 'LOOP C_REPARTO2. Position: ' || v_c_position_pos_prin || '. Error: ' || v_DesError || '. SQLCOD(' || SQLCODE || ') ' ||SQLERRM;
                                    --         RAISE HAY_ERROR;
                                    END;
                                END FOR; --REPARTO1
                                
                                v_DesError := 'PAGOS REPARTIDOS TRAMO2. COMPROBACION IMPORTES';
                                
                                --HACEMOS LA COMPROBACION DESPUES DE REPARTIR AMBOS TRAMOS
                                --DEJAMOS LA COMPROBACION TRAMO A TRAMO
                                ----CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe Reparto Tramo 2: ' || v_importe_comprobacion_tramo2, v_log_count, v_idproceso, 'info');
                                --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe Reparto Tramo 2: ' || v_importe_comprobacion, v_log_count, v_idproceso, 'info');     --198,89
                                
                                --Comprobamos si el reparto coincide con el pago y actualizamos el estado del reparto en la tabla de pagos
                                --v_dif_importe_reparto := v_c_pagos_importe - v_importe_comprobacion_tramo1 - v_importe_comprobacion_tramo2;
                                v_dif_importe_reparto := v_importe_reparto_tramo2 - v_importe_comprobacion;
                                
                                --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Diferencia Importe Tramo 2: ' || v_dif_importe_reparto, v_log_count, v_idproceso, 'info');   -- -0.01
                                
                                --Tambien tenemos que comprobar si la suma de ambos tramos coincide con el total o falta algun decimal.
                                --ALM 20211124: Usamos ROUND en lugar de TRUNC para que el importe sea el correcto. Ej: 0559003000 para agosto 2021.
                                --ALM 20211126: YA no hace falta el redondeo porque hemos cambiado las variables para que tengan dos decimales.
                                --v_dif_importe_reparto := v_dif_importe_reparto + (v_c_pagos_importe - (ROUND(v_importe_reparto_tramo1,2) + ROUND(v_importe_reparto_tramo2,2)));
                                v_dif_importe_reparto := v_dif_importe_reparto + (v_c_pagos_importe - (v_importe_reparto_tramo1 + v_importe_reparto_tramo2));
                                
                                --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe Total Reparto: ' || v_c_pagos_importe, v_log_count, v_idproceso, 'info');              --397,77
                                --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe Reparto Tramo 1: ' || v_importe_reparto_tramo1, v_log_count, v_idproceso, 'info');   --198.885
                                --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Importe Reparto Tramo 2: ' || v_importe_reparto_tramo2, v_log_count, v_idproceso, 'info');   --198.885
                                --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Diferencia Importe: ' || v_dif_importe_reparto, v_log_count, v_idproceso, 'info');
                                
                                IF v_dif_importe_reparto = 0 THEN
                                    
                                    --Solo actualizamos el Estado del Reparto del Pago si el tramo 1 se ha repartido correctamente.
                                    IF v_error_reparto_tramo1 = 0 THEN
                                        UPDATE EXT.FINAL_REPEXT_PAGOS_FILE
                                        SET ESTADO_REPARTO = 2 --REPARTO CORRECTO
                                        WHERE PERIODSEQ = v_periodSeq
                                            AND POS_PRIN = v_c_pagos_pos_prin
                                            --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                            AND TIPO_DOCUMENTO = v_c_pagos_tipo_documento
                                            --ALM 20220323: Usamos el campo DEPOSITSEQ que hace unicos los pagos.
                                            --AND EARNINGCODEID = v_c_pagos_earningcodeid
                                            --AND EARNINGGROUPID = v_c_pagos_earninggroupid
                                            --AND PROGRAMA = v_c_pagos_programa
                                            --AND TIPO_PAGO = v_c_pagos_tipo_pago
                                            ----ALM 20211123: Anadimos la union por importe por si hay balances con los mismos campos. Ej: 0889000218 en agosto 2021.
                                            --AND IMPORTE = v_c_pagos_importe;
                                            AND DEPOSITSEQ = v_c_pagos_depositseq;
                                                
                                        COMMIT;
                                    END IF;
                                    

                                --ALM 20211126: Modificamos el rango de redondeo de 1 a 2 euros porque hay position que se desvian demasiado en el redondeo. Ej: 0375001767 en agosto 2021.
                                --ELSEIF v_dif_importe_directo BETWEEN -1 AND 1 THEN
                                --ALM 20220411: Modificamos el rango de redondeo de 2 a 3 porque hay position que se desvian demasiado, pero solo en el reparto indirecto.
                                --              Ej: 0559002764 en marzo 2022.
                                --ELSEIF v_dif_importe_reparto BETWEEN -2 AND 2 THEN
                                ELSEIF v_dif_importe_reparto BETWEEN -3 AND 3 THEN
                                    
                                    --Actualizamos en la tabla temporal el ultimo importe repartido para ajustar la diferencia
                                    UPDATE EXT.TEMP_REPEXT_FILE
                                    --BUSCAR LA MEJOR FORMA DE REDONDEAR
                                    --SET IMPORTE = ROUND(TRUNC(v_importe_repartido,2),2) + v_dif_importe_reparto
                                    SET IMPORTE = v_importe_repartido + v_dif_importe_reparto
                                    WHERE ORDERID = v_ult_orderid_modif
                                        AND LINENUMBER = v_ult_linenumber_modif
                                        AND SUBLINENUMBER = v_ult_sublinenumber_modif
                                        AND EVENTTYPEID = v_ult_eventtypeid_modif
                                        --ALM 20220630: Incluimos la fecha de compensacion para evitar problemas por modificaciones erroneas de Comercial en Commissions.
                                        --              Sino se incluye algunas polizas parecen duplicadas aunque sean la misma. Ej: 01501263150499000000000N3812 para Junio 2022.
                                        AND COMPENSATIONDATE = v_ult_compensationdate_modif;
                                    
                                    COMMIT;
                                    
                                    --Solo actualizamos el Estado del Reparto del Pago si el tramo 1 se ha repartido correctamente.
                                    IF v_error_reparto_tramo1 = 0 THEN
                                        UPDATE EXT.FINAL_REPEXT_PAGOS_FILE
                                        SET ESTADO_REPARTO = 3 --REPARTO CASI CORRECTO
                                        WHERE PERIODSEQ = v_periodSeq
                                            AND POS_PRIN = v_c_pagos_pos_prin
                                            --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                            AND TIPO_DOCUMENTO = v_c_pagos_tipo_documento
                                            --ALM 20220323: Usamos el campo DEPOSITSEQ que hace unicos los pagos.
                                            --AND EARNINGCODEID = v_c_pagos_earningcodeid
                                            --AND EARNINGGROUPID = v_c_pagos_earninggroupid
                                            --AND PROGRAMA = v_c_pagos_programa
                                            --AND TIPO_PAGO = v_c_pagos_tipo_pago
                                            ----ALM 20211123: Anadimos la union por importe por si hay balances con los mismos campos. Ej: 0889000218 en agosto 2021.
                                            --AND IMPORTE = v_c_pagos_importe;
                                            AND DEPOSITSEQ = v_c_pagos_depositseq;
                                        
                                        COMMIT;
                                    END IF;
                                    
                                    
                                ELSE
                             --       CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'REPARTO TRAMO2. Position: ' || IFNULL(v_c_position_pos_prin,'') || '. Reparto no cuadra (importe-reparto): ' ||
                             --                                               IFNULL(TO_NVARCHAR(v_importe_reparto_tramo2),'') || '-' || IFNULL(TO_NVARCHAR(v_importe_comprobacion),''), v_log_count, v_idproceso, 'info');
                                    
                                    UPDATE EXT.FINAL_REPEXT_PAGOS_FILE
                                    SET ESTADO_REPARTO = 4 --REPARTO INCORRECTO. NO CUADRA EL IMPORTE
                                    WHERE PERIODSEQ = v_periodSeq
                                        AND POS_PRIN = v_c_pagos_pos_prin
                                        --ALM 20220323: Filtramos por el campo TIPO_DOCUMENTO porque el deposito englobaria tanto al pago del cierre como al de la LC.
                                        AND TIPO_DOCUMENTO = v_c_pagos_tipo_documento
                                        --ALM 20220323: Usamos el campo DEPOSITSEQ que hace unicos los pagos.
                                        --AND EARNINGCODEID = v_c_pagos_earningcodeid
                                        --AND EARNINGGROUPID = v_c_pagos_earninggroupid
                                        --AND PROGRAMA = v_c_pagos_programa
                                        --AND TIPO_PAGO = v_c_pagos_tipo_pago
                                        ----ALM 20211123: Anadimos la union por importe por si hay balances con los mismos campos. Ej: 0889000218 en agosto 2021.
                                        --AND IMPORTE = v_c_pagos_importe;
                                        AND DEPOSITSEQ = v_c_pagos_depositseq;
                                    
                                    COMMIT;
                                    
                                END IF;
                                
                                --Insertamos los importes repartidos sobre la tbala final.
                                --Por el momento insertamos siempre el reparto aunque no sea correcto, asi podemos comprobar.
                                v_DesError := 'PAGOS REPARTIDOS TRAMO2. RECARGA TABLA FINAL';
                                
                                INSERT INTO EXT.FINAL_REPEXT_FILE("TIPO_LIQ","COD_AGENTE","COEF_CORRECTOR","COEF_TIPO_BASE","PRIMA_COMIS","PRIMA_NETA_ANUAL","PRIMA_NETA","PRIMA_CORREGIDA"
                                ,"POLIZA_CORREGIDA","POLIZA_FISICA","REPARTO_PORCENTAJE","REPARTO_TIPO_BASE","NUM_TRAMO","TIPO_REPARTO","IMPORTE","TIPO_AGENTE","TIPO_DOCUMENTO","EARNINGGROUPID"
                                ,"EARNINGCODEID","IMPORTE_PAGO","DEPOSITSEQ","DEPOSITO","TIPO_PAGO","PROGRAMA","ESTADO","COMPENSATIONDATE","CODIGO_POLIZA","PRODUCTID","EVENTTYPEID","SUBLINENUMBER"
                                ,"LINENUMBER","ORDERID","MANAGER_POS_PRIN","NIF","POS_PRIN","POSITIONNAME","PERIODO","PERIODSEQ","POSITIONSEQ","PARTICIPANTSEQ")
                                    SELECT "TIPO_LIQ","COD_AGENTE","COEF_CORRECTOR","COEF_TIPO_BASE","PRIMA_COMIS","PRIMA_NETA_ANUAL","PRIMA_NETA","PRIMA_CORREGIDA"
                                		,"POLIZA_CORREGIDA","POLIZA_FISICA","REPARTO_PORCENTAJE","REPARTO_TIPO_BASE","NUM_TRAMO","TIPO_REPARTO","IMPORTE","TIPO_AGENTE","TIPO_DOCUMENTO","EARNINGGROUPID"
                                		,"EARNINGCODEID","IMPORTE_PAGO","DEPOSITSEQ","DEPOSITO","TIPO_PAGO","PROGRAMA","ESTADO","COMPENSATIONDATE","CODIGO_POLIZA","PRODUCTID","EVENTTYPEID","SUBLINENUMBER"
                                		,"LINENUMBER","ORDERID","MANAGER_POS_PRIN","NIF","POS_PRIN","POSITIONNAME","PERIODO","PERIODSEQ","POSITIONSEQ","PARTICIPANTSEQ"
                                        --Ya no es necesario el campo LIQUIDACION porque no hay diferencia entre cierre y LC.
                                        --(CASE WHEN v_existe_control_reparto = 0 THEN 2 ELSE
                                        --    (CASE WHEN v_control_reparto.ESTADO = 1 THEN 2 ELSE 4 END)
                                        --END) AS LIQUIDACION
                                    FROM EXT.TEMP_REPEXT_FILE RT;
                                
                                COMMIT;
                                
                            END IF;
                            
                            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Reparto Tramo 2.', v_log_count, v_idproceso, 'info');
                            
                        -- EXCEPTION
                        --     WHEN HAY_ERROR_LOOP THEN
                        --         CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Position: ' || v_c_position_pos_prin || '. Error Controlado: ' || v_DesError, v_log_count, v_idproceso, 'info');
                        --     WHEN OTHERS THEN
                        --         v_DesError := 'LOOP C_PAGOS. Position: ' || v_c_position_pos_prin || '. Error: ' || v_DesError || '. SQLCOD(' || SQLCODE || ') ' ||SQLERRM;
                        --         RAISE HAY_ERROR;
                        END;
                    END FOR;--PAGOS
                   
                END;
            END FOR;--AGENTES
            
            -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Actualizacion de Indices de la tabla INYC_REPEXT_FINAL.', v_log_count, v_idproceso, 'info');
            
            --EXECUTE IMMEDIATE 'ANALYZE TABLE EXT.FINAL_REPEXT_FILE COMPUTE STATISTICS FOR ALL INDEXES';
            -- DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_REPEXT_FINAL');
            
            -- CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Actualizacion de Indices de la tabla INYC_REPEXT_FINAL.', v_log_count, v_idproceso, 'info');
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Reparto.', v_log_count, v_idproceso, 'info');
            
        --ALM 20220802: La correccion de centimos la aplicamos siempre que el parametro i_par_position sea igual a Todas.
        END IF;

------------------------------LFC:20251202 --TABLA DEBUG PENDIENTE BORRAR
	    SELECT COUNT(1) INTO v_existe_tabla FROM SYS.TABLES WHERE TABLE_NAME = 'FINAL_REPEXT_PAGOS_FILE_4_DEBUG';
		TEMP_FINAL_REPEXT_PAGOS_FILE_4_DEBUG =
			SELECT * FROM EXT.FINAL_REPEXT_PAGOS_FILE WHERE PERIODSEQ = v_periodSeq
			;
		IF v_existe_tabla > 0 THEN
			DROP TABLE EXT.FINAL_REPEXT_PAGOS_FILE_4_DEBUG;
		END IF;
		
		CREATE TABLE EXT.FINAL_REPEXT_PAGOS_FILE_4_DEBUG AS (SELECT * FROM :TEMP_FINAL_REPEXT_PAGOS_FILE_4_DEBUG);
	    CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name, 'Creada la tabla temporal FINAL_REPEXT_PAGOS_FILE_4_DEBUG' , v_log_count, v_idproceso, 'debug');


	    SELECT COUNT(1) INTO v_existe_tabla FROM SYS.TABLES WHERE TABLE_NAME = 'FINAL_REPEXT_FILE_4_DEBUG';
		TEMP_FINAL_REPEXT_FILE_4_DEBUG =
			SELECT * FROM EXT.FINAL_REPEXT_FILE WHERE PERIODSEQ = v_periodSeq
			;
		IF v_existe_tabla > 0 THEN
			DROP TABLE EXT.FINAL_REPEXT_FILE_4_DEBUG;
		END IF;
		
		CREATE TABLE EXT.FINAL_REPEXT_FILE_4_DEBUG AS (SELECT * FROM :TEMP_FINAL_REPEXT_FILE_4_DEBUG);
	    CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name, 'Creada la tabla temporal FINAL_REPEXT_FILE_4_DEBUG' , v_log_count, v_idproceso, 'debug');
------------------------------
    
           IF i_par_position = 'Todas' THEN
            
            --ALM 20220711: Incluimos la correccion de registros para evitar diferencias en los centimos para el fichero de SAP.
            --              Se aplica antes de la generacion de los 3 ficheros para que la informacion sea la miama en todos ellos.
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Correccion Centimos.', v_log_count, v_idproceso, 'info');
                
            v_DesError := 'CORRECCION CENTIMOS';
                
            C_CORRECCION =
                SELECT X.NIF,X.CIA,X.TIPO_DOC,X.OFI,X.AGE,X.PERIODSEQ,X.REF,SUM(IMP_PAG) + SUM(IMP_AUT) - SUM(IMP_REP) + SUM(IMP_LIQ) AS AJUSTE
                FROM (
                    SELECT
                        TRIM(PAGEXT.PER_CIF_NIF) AS NIF,
                        PAGEXT.CIA_CODIGO AS CIA,
                        --ALM 20230110: Hay que coger el dato de la referencia del pago porque sino no diferencia entre cierre y LC.
                        --SUBSTR(PAGEXT.CONCEP_CODIGO,3,1) AS TIPO_DOC,
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1) AS TIPO_DOC,
                        PAGEXT.PAG_OFICINA AS OFI,
                        PAGEXT.PAG_AGENTE AS AGE,
                        PAGEXT.PERIODSEQ,
                        TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN) AS REF,
                        SUM(REP.IMPORTE) AS IMP_REP,0 AS IMP_LIQ,0 AS IMP_PAG,0 AS IMP_AUT
                    FROM EXT.FINAL_REPEXT_FILE REP
                    INNER JOIN EXT.FINAL_EXTRACTPAGOS_FILE PAGEXT ON TRIM(PAGEXT.PER_CIF_NIF) = REP.NIF
                        AND PAGEXT.CIA_CODIGO = SUBSTR(REP.EARNINGGROUPID,7,2)
                        AND SUBSTR(PAGEXT.CONCEP_CODIGO,3,1) = SUBSTR(REP.EARNINGGROUPID,5,1)
                        AND PAGEXT.PAG_OFICINA = SUBSTR(REP.POS_PRIN,1,4) 
                        AND PAGEXT.PAG_AGENTE = SUBSTR(REP.POS_PRIN,5,6)
                        AND PAGEXT.PERIODSEQ = REP.PERIODSEQ
                        --ALM 20230109: Cogemos el campo TIPO_DOCUMENTO del reparto para diferenciar entre cierre y complementaria.
                        --AND TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN) = SUBSTR(REP.EARNINGGROUPID,8,1) || SUBSTR(REP.EARNINGGROUPID,5,1) || TO_CHAR(v_PeriodStartDate,'YYYYMM') || 
                        AND TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN) = SUBSTR(REP.EARNINGGROUPID,8,1) || REP.TIPO_DOCUMENTO || TO_CHAR(v_PeriodStartDate,'YYYYMM') || 
                                                                 SUBSTR(REP.POS_PRIN,2,3) || SUBSTR(REP.POS_PRIN,7,4)
                    WHERE REP.PERIODSEQ = v_periodSeq
                    GROUP BY
                        TRIM(PAGEXT.PER_CIF_NIF),
                        PAGEXT.CIA_CODIGO,
                        --SUBSTR(PAGEXT.CONCEP_CODIGO,3,1),
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1),
                        PAGEXT.PAG_OFICINA,
                        PAGEXT.PAG_AGENTE,
                        PAGEXT.PERIODSEQ,
                        TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN)
                        
                    UNION ALL
                        
                    SELECT
                        TRIM(PAGEXT.PER_CIF_NIF) AS NIF,
                        PAGEXT.CIA_CODIGO AS CIA,
                        --ALM 20230110: Hay que coger el dato de la referencia del pago porque sino no diferencia entre cierre y LC.
                        --SUBSTR(PAGEXT.CONCEP_CODIGO,3,1) AS TIPO_DOC,
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1) AS TIPO_DOC,
                        PAGEXT.PAG_OFICINA AS OFI,
                        PAGEXT.PAG_AGENTE AS AGE,
                        PAGEXT.PERIODSEQ,
                        TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN) AS REF,
                        0 AS IMP_REP,ROUND(SUM(CASE WHEN LIQ.COD_CONCEPTO <> '601' THEN (-1)*LIQ.IMPORTE ELSE LIQ.IMPORTE END),2) AS IMP_LIQ,0 AS IMP_PAG,0 AS IMP_AUT
                    FROM EXT.FINAL_LIQEXT_CABECERA_FILE LIQ
					-- LFC 20251211:  INNER JOIN EXT.FINAL_EXTRACTPAGOS_FILE PAGEXT ON PAGEXT.PER_CIF_NIF = (
                    INNER JOIN EXT.FINAL_EXTRACTPAGOS_FILE PAGEXT ON TRIM(PAGEXT.PER_CIF_NIF) = (
                    CASE WHEN LENGTH(LIQ.DOC_NIF) = 9 THEN RPAD(SUBSTR(LIQ.DOC_NIF,1,9),9,' ') ELSE RPAD(SUBSTR(LIQ.DOC_NIF,2,9),9,' ') END)
                        AND PAGEXT.CIA_CODIGO = LIQ.COMPANIA
                        AND SUBSTR(PAGEXT.CONCEP_CODIGO,3,1) = LIQ.TIPODOCUMENTO
                        AND PAGEXT.PAG_OFICINA = SUBSTR(LIQ.POSICION_COMERCIAL,1,4) 
                        AND PAGEXT.PAG_AGENTE = SUBSTR(LIQ.POSICION_COMERCIAL,5,6)
                        AND PAGEXT.PERIODSEQ = LIQ.PERIODSEQ
                        AND TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN) = TRIM(LIQ.PAG_REFERENCIA_ORIGEN)
                    WHERE LIQ.DOC_NIF IS NOT NULL
                        AND SUBSTR(LIQ.COD_CONCEPTO,1,1) IN ('6','8') 
                        AND PAGEXT.PERIODSEQ = v_periodSeq
                    GROUP BY
                        TRIM(PAGEXT.PER_CIF_NIF),
                        PAGEXT.CIA_CODIGO,
                        --SUBSTR(PAGEXT.CONCEP_CODIGO,3,1),
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1),
                        PAGEXT.PAG_OFICINA,
                        PAGEXT.PAG_AGENTE,
                        PAGEXT.PERIODSEQ,
                        TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN)
                        
                    UNION ALL

                    SELECT
                        TRIM(PAGEXT.PER_CIF_NIF) AS NIF,
                        PAGEXT.CIA_CODIGO AS CIA,
                        --ALM 20230110: Hay que coger el dato de la referencia del pago porque sino no diferencia entre cierre y LC.
                        --SUBSTR(PAGEXT.CONCEP_CODIGO,3,1) AS TIPO_DOC,
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1) AS TIPO_DOC,
                        PAGEXT.PAG_OFICINA AS OFI,
                        PAGEXT.PAG_AGENTE AS AGE,
                        PAGEXT.PERIODSEQ,
                        TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN) AS REF,
                        0 AS IMP_REP,0 AS IMP_LIQ,SUM(PAGEXT.PAG_IMPORTE) AS IMP_PAG,0 AS IMP_AUT
                    FROM EXT.FINAL_EXTRACTPAGOS_FILE PAGEXT
                    WHERE PAGEXT.PERIODSEQ = v_periodSeq
                    GROUP BY
                        TRIM(PAGEXT.PER_CIF_NIF),
                        PAGEXT.CIA_CODIGO,
                        --SUBSTR(PAGEXT.CONCEP_CODIGO,3,1),
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1),
                        PAGEXT.PAG_OFICINA,
                        PAGEXT.PAG_AGENTE,
                        PAGEXT.PERIODSEQ,
                        TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN)

                    UNION ALL

                    SELECT
                        TRIM(PAGEXT.PER_CIF_NIF) AS NIF,
                        PAGEXT.CIA_CODIGO AS CIA,
                        --ALM 20230110: Hay que coger el dato de la referencia del pago porque sino no diferencia entre cierre y LC.
                        --SUBSTR(PAGEXT.CONCEP_CODIGO,3,1) AS TIPO_DOC,
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1) AS TIPO_DOC,
                        PAGEXT.PAG_OFICINA AS OFI,
                        PAGEXT.PAG_AGENTE AS AGE,
                        PAGEXT.PERIODSEQ,
                        TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN) AS REF,
                        0 AS IMP_REP,0 AS IMP_LIQ,0 AS IMP_PAG,
                        SUM(AUT.IMP - (CASE WHEN PAGEXT.PAG_IMPORTE = 0 THEN 0 ELSE ROUND((PAGEXT.DC_IMPORTE1 * (100 - PAGEXT.DC_IMPORTE30)/100),2) END)) AS IMP_AUT
                    FROM (
                        --JGE 20230113: Actualizamos para usar nuevos campos PERIODSEQ y  PAG_REFERENCIA_ORIGEN
                        
                        SELECT AUT.PAG_REFERENCIA_ORIGEN,SUM(AUT.IMPCOMIS) - ROUND((SUM(AUT.IMPCOMIS)*MAX(AUT.IRPF)),2) AS IMP
                        FROM EXT.FINAL_EXTRACTPAGOS_AUT_FILE AUT
                        WHERE AUT.PERIODSEQ = v_periodSeq
                        GROUP BY AUT.PAG_REFERENCIA_ORIGEN
                    ) AUT
                    INNER JOIN EXT.FINAL_EXTRACTPAGOS_FILE PAGEXT ON  TRIM(AUT.PAG_REFERENCIA_ORIGEN) = TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN)
                        --PAGEXT.CIA_CODIGO = '0' || AUT.CCOMPANI
                        --AND PAGEXT.PAG_OFICINA = AUT.COFICINA
                        --AND PAGEXT.PAG_AGENTE = '0' || AUT.CAGENTE
                        --AND SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,3,6) = AUT.FCARGO
                    WHERE PAGEXT.PERIODSEQ = v_periodSeq
                    GROUP BY
                        TRIM(PAGEXT.PER_CIF_NIF),
                        PAGEXT.CIA_CODIGO,
                        --SUBSTR(PAGEXT.CONCEP_CODIGO,3,1),
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1),
                        PAGEXT.PAG_OFICINA,
                        PAGEXT.PAG_AGENTE,
                        PAGEXT.PERIODSEQ,
                        TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN)
                ) X
                GROUP BY X.NIF,X.CIA,X.TIPO_DOC,X.OFI,X.AGE,X.PERIODSEQ,X.REF
                HAVING SUM(IMP_REP) - SUM(IMP_LIQ) <> SUM(IMP_PAG) + SUM(IMP_AUT)
                    --Solo seria necesario corregir los descuadres mayores de un centimo, pero en principio actualizamos todos.
                    --Por el momento solo arreglamos los mayores de un centimo.
                    --ALM 20220802: Arreglamos tambien los de un solo centimo. 
                    --AND SUM(IMP_REP) - SUM(IMP_LIQ) <> SUM(IMP_PAG) + SUM(IMP_AUT) + 0.01
                    --AND SUM(IMP_REP) - SUM(IMP_LIQ) <> SUM(IMP_PAG) + SUM(IMP_AUT) - 0.01
                ;
				

