-- LFC 20250107: Llamada al procedimiento RELLENARTABLAS para recargar informes de VB reparto
CALL "EXT"."SP_RELLENAR_TABLAS"(I_PERIODSEQ => v_PeriodSeq,I_LISTA_INFORMES => 'REPEXT',I_ID_PROCESO => v_idproceso,I_LOG_COUNT => v_log_count);
 

        --Carga en las tablas de los informes.
        --20211103 - TGV -- Inserccion en las tablas de los informes
        --ALM 20211230: Solo recargamos informes para el tipo de ejecucion completa (1) y para una especifica para ello (8).
        IF i_par_tipo_ejecucion IN (1,8) THEN
			
            
			----------------------------EXT.FINAL_REPEXT_INF_PYG_FILE----------------------------
            
            --Solo se recargan en la ejecucion inicial.
            IF i_par_tipo_ejecucion = 1 THEN
            --IF i_par_tipo_ejecucion IN (1,8) THEN
                v_DesError := 'CARGA PYG'; 
              --Nueva tabla para los datos pendientes
                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Borrado de la tabla OUT_REPEXT_INF_PYG_P_FILE.', v_log_count, v_idproceso, 'info');
                
                DELETE FROM EXT.OUT_REPEXT_INF_PYG_P_FILE WHERE PERIODSEQ = v_periodSeq;
                
                v_num_rows = ::ROWCOUNT;          
                -- COMMIT;
                
                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Borrado de la tabla OUT_REPEXT_INF_PYG_P_FILE: ' || to_char(v_num_rows) || ' filas borradas.', v_log_count, v_idproceso, 'info');
                
                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Carga de la tabla OUT_REPEXT_INF_PYG_P_FILE. Commissions.', v_log_count, v_idproceso, 'info');
        
                INSERT INTO EXT.OUT_REPEXT_INF_PYG_P_FILE(PERIODSEQ,LINE)
                    SELECT
                        --ALM 20220527: Nuevo campo para las particiones.
                        v_periodSeq AS PERIODSEQ,
                        LPAD(IFNULL(SUBSTR(ST.PRODUCTID,1,2),'0'),2,'0') ||                                -- COMPANIA
                        --ALM 20220224: Quitamos un mes a la fecha de compensacion porque las trx pendientes llevan un mes mas del actual.
                        LPAD(IFNULL(TO_CHAR(ADD_MONTHS(ST.COMPENSATIONDATE,-1),'YYYYMM'), '0'),6,'0') ||   -- FECHA_CARGO
                        RPAD(' ',10) ||                                                                 -- CONCEPTO
                        RPAD('COMER',6,' ') ||                                                          -- SISTEMA
                        --RAP 20220311: En el Genericattribute1 en el caso de los pagos comerciales, puede venir el numero de poliza o el earninggroupid, 
                        --              si viene el earninggroupid ponemos 9999999 en poliza, 0s en subpoliza y 'C' en situacion
                        --LPAD(IFNULL(CASE WHEN SUBSTR(ST.PRODUCTID,3,1) = '2'
                        --    THEN SUBSTR(ST.GENERICATTRIBUTE1,1,11)
                        --    ELSE SUBSTR(ST.GENERICATTRIBUTE1,1,7)
                        --END,'0'),11, '0') ||                                                            -- POLIZA
                        LPAD(IFNULL(CASE WHEN ST.GENERICATTRIBUTE1 LIKE '%S%' THEN '99999999999' ELSE (
                            CASE WHEN SUBSTR(ST.PRODUCTID,3,1) = '2'
                                THEN SUBSTR(ST.GENERICATTRIBUTE1,1,11)
                                ELSE SUBSTR(ST.GENERICATTRIBUTE1,1,7)
                            END)
                        END,'0'),11,'0') ||                                                             -- POLIZA
                        LPAD(IFNULL(CASE WHEN ST.GENERICATTRIBUTE1 LIKE '%S%' THEN '00000' ELSE (
                            CASE WHEN SUBSTR(ST.PRODUCTID,3,1) = '2'
                                THEN SUBSTR(ST.GENERICATTRIBUTE1,12,5)
                                ELSE SUBSTR(ST.GENERICATTRIBUTE1,8,5)
                            END)
                        END,'0'),5,'0') ||                                                              -- SUBPOLIZA
                        LPAD(IFNULL(CASE WHEN ST.GENERICATTRIBUTE1 LIKE '%S%' THEN '000' ELSE (
                            CASE WHEN SUBSTR(ST.PRODUCTID,3,1) = '2'
                                THEN '0'
                                --ELSE TO_CHAR(SUBSTR(ST.GENERICATTRIBUTE1,13,3))
                                ELSE TO_CHAR(RIGHT(ST.GENERICATTRIBUTE1,3))
                            END)
                        END,'0'),3,'0') ||                                                              -- ORDEN
                        LPAD(IFNULL(SUBSTR(ST.PRODUCTID,3,5),'0'),5,'0') ||                                -- PRODUCTO
                        
                        --ALM 20220506: Por peticion de Mariano cogemos el valor de las transacciones salvo para los recibos de cobro que no lo tenemos.
                        (CASE WHEN ST.EVENTTYPEID = '20' THEN
                            RPAD(IFNULL(CASE WHEN C.VALUE < 0
                                THEN '-' ELSE '+' END,' '),1,' ' ) ||                                   -- SIGNO
                            --LPAD(IFNULL((TRUNC(ABS(ROUND(C.VALUE,2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(C.VALUE,2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(C.VALUE,2),1)*100),'0'),2,'0')                       -- IMPORTE
                        ELSE
                            RPAD(IFNULL(CASE WHEN ST.NATIVECURRENCYAMOUNT < 0
                                THEN '-' ELSE '+' END,' '),1,' ' ) ||                                   -- SIGNO
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(ST.NATIVECURRENCYAMOUNT,2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(ST.NATIVECURRENCYAMOUNT,2)) AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(ST.NATIVECURRENCYAMOUNT,2),1)*100),'0'),2,'0')       -- IMPORTE
                        END) ||

                        LPAD(IFNULL(SUBSTR(TA.GENERICATTRIBUTE3,1,4),'0'),4,'0') ||                        -- OFICINA CONTABLE
                        LPAD('0000',4) ||                                                               -- OFICINA GESTORA
                        LPAD('0000',4) ||                                                               -- OFICINA COBRADORA
                        LPAD(IFNULL(SUBSTR(TA.GENERICATTRIBUTE3,1,4),'0'),4,'0') ||
                        --ALM 20220630: Si el codigo de agente es 999999 ponemos 000000.
                        --LPAD(IFNULL(SUBSTR(TA.GENERICATTRIBUTE3,7,4),'0'),4,'0') ||                        --CODIGO AGENTE
                        LPAD(IFNULL(CASE WHEN SUBSTR(TA.GENERICATTRIBUTE3,5,6) = '999999'
                            THEN '0000'
                            ELSE SUBSTR(TA.GENERICATTRIBUTE3,7,4)
                        END,'0'),4,'0') ||                                                              --CODIGO AGENTE
                        
                        --ALM 20220224: Cambiamos el orden del MAX porque sino puede haber nulos.
                        --(SELECT MAX(LPAD(IFNULL(SUBSTR(J.MANAGER_POS_PRIN,1,4),'0'),4,'0') || LPAD(IFNULL(SUBSTR(J.MANAGER_POS_PRIN,7,4),'0'),4,'0'))
                        --ALM 20220321: Como son pagos de comisiones devolvemos manager a 0.
                        --(SELECT LPAD(IFNULL(MAX(SUBSTR(J.MANAGER_POS_PRIN,1,4)),'0'),4,'0') || LPAD(IFNULL(MAX(SUBSTR(J.MANAGER_POS_PRIN,7,4)),'0'),4,'0')
                        --    FROM EXT.OUT_JERARQUIA_REP J
                        --    WHERE J.PERIODSEQ = C.PERIODSEQ
                        --    --ALM 20220224: Volvemos a usar el TA.POSITIONNAME porque es el que verdaderamente tiene asignada en Commissions la trx.
                        --    --              Lo malo que en INYC_JERARQUIA el POS_CALLIDUS puede aparecer para varias POS_PRIN.
                        --    --PUEDE DAR ALGUN ERROR EN EL MANAGER EN ALGUN CASO CONCRETO DE AGENTES CON VARIAS POSITION. 
                        --    --AND J.POS_PRIN = TA.GENERICATTRIBUTE3)
                        --    AND J.POS_CALLIDUS = TA.POSITIONNAME)
                        '00000000' ||                                                                   --INSPECTOR
                        RPAD(' ',4) ||                                                                  --SUBCUENTA
                        
                        --ALM 20220506: Usamos el eventtypeid de la transaccion para determinar si la comision es de produccion o de conservacion.
                        --LPAD(IFNULL(CASE WHEN C.NAME LIKE '%NuevaProduccion%'
                        --    THEN '101'
                        --    ELSE '102'
                        --END,'0'),4,'0')||                                                               --CONCEPTO ORIGEN
                        LPAD(IFNULL(CASE WHEN ST.EVENTTYPEID IN ('20','81')
                            THEN '102'
                            ELSE '101'
                        END,'0'),4,'0')||                                                               --CONCEPTO ORIGEN
                        
                        RPAD(' ',1) ||                                                                  --DESTINO CONTABLE
                        RPAD(' ',4) ||                                                                  --DEPARTAMENTO
                        RPAD(' ',5) ||                                                                  --REFERENCIA
                        'P'     AS LINE                                                                        --SITUACION
                    --ALM 20220506: Por peticion de Mariano cogemos el valor de las transacciones que nos llegan salvo para los recibos de cobro que no la tenemos.
                    --              Para ello tiramos de las tablas de stage porque estas no pueden ser modificadas por los usuarios.
                    --              Lo malo de usar estas tablas es que los datos se purgan el segundo sabado despues de su carga, pero siempre deberian haberse cargado con anterioridad.
                    --              Ademas usamos un LEFT para unir con los creditos ya que solo sera necesario para las transacciones con eventtypeid 20.
                    --FROM TCMP.CS_SALESTRANSACTION ST
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = v_idtenant AND TA.PROCESSINGUNITSEQ = 38280596832649217
                    --INNER JOIN TCMP.CS_PLRUN PL ON ST.PIPELINERUNSEQ = PL.PIPELINERUNSEQ
                    --    AND PL.TENANTID = v_idtenant AND PL.PROCESSINGUNITSEQ = 38280596832649217 AND PL.MODELSEQ = 0
                    --    AND PL.REMOVEDATE = to_date('22000101','yyyymmdd')--v_eot
                    --    AND PL.COMMAND = 'Import' AND PL.RUNPARAMETERS LIKE '%[Sequence]ValidateAndTransfer%'
                    --    AND PL.STARTTIME <= v_fecha_reparto
                    FROM TCMP.CS_STAGESALESTRANSACTION ST
                    INNER JOIN TCMP.CS_STAGETRANSACTIONASSIGN TA ON ST.STAGESALESTRANSACTIONSEQ = TA.STAGESALESTRANSACTIONSEQ AND TA.TENANTID = v_idtenant
                    LEFT JOIN (
                            SELECT C.SALESTRANSACTIONSEQ,C.PERIODSEQ,C.NAME,C.VALUE
                            FROM TCMP.CS_CREDIT C
                            INNER JOIN TCMP.CS_PLRUN PL ON C.PIPELINERUNSEQ = PL.PIPELINERUNSEQ
                            AND PL.TENANTID = v_idtenant AND PL.PROCESSINGUNITSEQ = 38280596832649217 AND PL.MODELSEQ = 0
                            WHERE C.TENANTID = v_idtenant AND C.PROCESSINGUNITSEQ = 38280596832649217
                            AND (C.NAME LIKE 'DC-O-COM-%' OR C.NAME LIKE 'DC-E-COM-%')
                            AND C.PERIODSEQ = (
                                SELECT PER.PERIODSEQ FROM TCMP.CS_PERIOD PER
                                WHERE PER.TENANTID = v_idtenant AND PER.REMOVEDATE = v_eot
                                AND PER.PERIODTYPESEQ = 2814749767106561
                                AND PER.STARTDATE = ADD_MONTHS(v_PeriodStartDate,1))
                        ) C ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                    --WHERE ST.TENANTID = v_idtenant AND ST.PROCESSINGUNITSEQ = 38280596832649217 AND ST.MODELSEQ = 0
                    WHERE ST.TENANTID = v_idtenant
                        AND ST.COMPENSATIONDATE = ADD_MONTHS(v_PeriodStartDate,1)
                        AND ST.GENERICATTRIBUTE6 = 'P'
                        --ALM 20220524: Filtramos las transacciones con POSITIONNAME NO_ENCONTRADO y NO_INSPECTOR
                        --              Tambien las que tengan el GA20 a 1 ya que no van a pagar comisiones.
                        AND (ST.GENERICATTRIBUTE20 = '0' OR ST.GENERICATTRIBUTE20 IS NULL)
                        AND TA.POSITIONNAME NOT IN ('NO_ENCONTRADO','NO_INSPECTOR')
                    ;
                
                v_num_rows = ::ROWCOUNT;  
                -- COMMIT;
                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Carga de la tabla OUT_REPEXT_INF_PYG_P_FILE. Commissions: '|| to_char(v_num_rows) || ' filas.', v_log_count, v_idproceso, 'info');
                
                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Carga de la tabla OUT_REPEXT_INF_PYG_P_FILE. Cartera DDEE LP.', v_log_count, v_idproceso, 'info');
        
                INSERT INTO EXT.OUT_REPEXT_INF_PYG_P_FILE(PERIODSEQ,LINE)
                    SELECT
                        --ALM 20220527: Nuevo campo para las particiones.
                        v_periodSeq AS PERIODSEQ,
                        LPAD(IFNULL(SUBSTR(CAR_LP.PRODUCTID,1,2),'0'),2,'0') ||                                -- COMPANIA
                        --ALM 20220224: Quitamos un mes a la fecha de compensacion porque las trx pendientes llevan un mes mas del actual.
                        LPAD(IFNULL(TO_CHAR(ADD_MONTHS(CAR_LP.COMPENSATIONDATE,-1),'YYYYMM'), '0'),6,'0') ||   -- FECHA_CARGO
                        RPAD(' ',10) ||                                                                     -- CONCEPTO
                        RPAD('COMER',6,' ') ||                                                              -- SISTEMA
                        LPAD(IFNULL(CASE WHEN CAR_LP.POLIZA LIKE '%S%' THEN '99999999999' ELSE (
                            CASE WHEN SUBSTR(CAR_LP.PRODUCTID,3,1) = '2'
                                THEN SUBSTR(CAR_LP.POLIZA,1,11)
                                ELSE SUBSTR(CAR_LP.POLIZA,1,7)
                            END)
                        END,'0'),11,'0') ||                                                                 -- POLIZA
                        LPAD(IFNULL(CASE WHEN CAR_LP.POLIZA LIKE '%S%' THEN '00000' ELSE (
                            CASE WHEN SUBSTR(CAR_LP.PRODUCTID,3,1) = '2'
                                THEN SUBSTR(CAR_LP.POLIZA,12,5)
                                ELSE SUBSTR(CAR_LP.POLIZA,8,5)
                            END)
                        END,'0'),5,'0') ||                                                                  -- SUBPOLIZA
                        LPAD(IFNULL(CASE WHEN CAR_LP.POLIZA LIKE '%S%' THEN '000' ELSE (
                            CASE WHEN SUBSTR(CAR_LP.PRODUCTID,3,1) = '2'
                                THEN '0'
                                --ELSE TO_CHAR(SUBSTR(ST.GENERICATTRIBUTE1,13,3))
                                ELSE TO_CHAR(RIGHT(CAR_LP.POLIZA,3))
                            END)
                        END,'0'),3,'0') ||                                                                  -- ORDEN
                        LPAD(IFNULL(SUBSTR(CAR_LP.PRODUCTID,3,5),'0'),5,'0') ||                                -- PRODUCTO
                        RPAD(IFNULL(CASE WHEN CAR_LP.IMPORTE < 0
                            THEN '-' ELSE '+' END,' '),1,' ' ) ||                                           -- SIGNO
                        --LPAD(IFNULL((TRUNC(ABS(ROUND(CAR_LP.IMPORTE,2)))),'0'),12,'0') ||
                        LPAD(IFNULL((CAST(ABS(ROUND(CAR_LP.IMPORTE,2)) AS INTEGER)),'0'),12,'0') || 
                        LPAD(IFNULL(ABS(MOD(ROUND(CAR_LP.IMPORTE,2),1)*100),'0'),2,'0') ||                     -- IMPORTE
                        LPAD(IFNULL(SUBSTR(CAR_LP.COD_AGENTE,1,4),'0'),4,'0') ||                               -- OFICINA CONTABLE
                        LPAD('0000',4) ||                                                                   -- OFICINA GESTORA
                        LPAD('0000',4) ||                                                                   -- OFICINA COBRADORA
                        LPAD(IFNULL(SUBSTR(CAR_LP.COD_AGENTE,1,4),'0'),4,'0') || 
                        LPAD(IFNULL(SUBSTR(CAR_LP.COD_AGENTE,7,4),'0'),4,'0') ||                               --CODIGO AGENTE
                        '00000000' ||                                                                       --INSPECTOR
                        RPAD(' ',4) ||                                                                      --SUBCUENTA
                        '0102' ||                                                                           --CONCEPTO ORIGEN
                        RPAD(' ',1) ||                                                                      --DESTINO CONTABLE
                        RPAD(' ',4) ||                                                                      --DEPARTAMENTO
                        RPAD(' ',5) ||                                                                      --REFERENCIA
                        'P'                                                                                 --SITUACION
                    FROM EXT.CARTERA_DDEE CAR_LP
                    INNER JOIN TCMP.CS_POSITION POS ON CAR_LP.POSITIONNAME = POS.NAME
                        AND POS.TENANTID = v_idtenant AND POS.PROCESSINGUNITSEQ = 38280596832649217
                        AND POS.CREATEDATE < v_fecha_reparto
                        AND POS.REMOVEDATE > v_fecha_reparto
                        AND POS.EFFECTIVESTARTDATE <= ADD_DAYS(v_periodEndDate,-1)
                        AND POS.EFFECTIVEENDDATE > ADD_DAYS(v_periodEndDate,-1)
                    INNER JOIN TCMP.CS_PARTICIPANT PART ON POS.PAYEESEQ = PART.PAYEESEQ
                        AND PART.TENANTID = v_idtenant
                        AND (PART.TERMINATIONDATE IS NULL OR PART.TERMINATIONDATE > v_fecha_reparto)
                        AND PART.CREATEDATE < v_fecha_reparto
                        AND PART.REMOVEDATE > v_fecha_reparto
                        AND PART.EFFECTIVESTARTDATE <= ADD_DAYS(v_periodEndDate,-1)
                        AND PART.EFFECTIVEENDDATE > ADD_DAYS(v_periodEndDate,-1)
                    WHERE CAR_LP.COMPENSATIONDATE = ADD_MONTHS(v_PeriodStartDate,1)
                        AND CAR_LP.ESTADO = 'P'
                        AND CAR_LP.IMPORTE <> 0
                    ;
                
                v_num_rows = ::ROWCOUNT;  
                -- COMMIT;
                CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Carga de la tabla OUT_REPEXT_INF_PYG_P_FILE. Cartera DDEE LP: '|| to_char(v_num_rows) || ' filas.', v_log_count, v_idproceso, 'info');
               
            END IF;
           
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Borrado de la tabla FINAL_REPEXT_INF_PYG_FILE.', v_log_count, v_idproceso, 'info');
            
            DELETE FROM EXT.FINAL_REPEXT_INF_PYG_FILE WHERE PERIODSEQ = v_periodSeq;
            
            v_num_rows = ::ROWCOUNT;            
            -- COMMIT;
         
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Borrado de la tabla FINAL_REPEXT_INF_PYG_FILE: ' || to_char(v_num_rows) || ' filas borradas.', v_log_count, v_idproceso, 'info');
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Carga de la tabla FINAL_REPEXT_INF_PYG_FILE. Recibos Cobrados.', v_log_count, v_idproceso, 'info');
           
            INSERT INTO EXT.FINAL_REPEXT_INF_PYG_FILE(PERIODSEQ,LINE)
                SELECT
                    --ALM 20220527: Nuevo campo para las particiones.
                    v_periodSeq AS PERIODSEQ,
                    --DEFINIR PARA LOS PAGOS COMERCIALES QUE VALORES HAY QUE PONER EN CADA CAMPO.
                    LPAD(IFNULL(SUBSTR(PRODUCTID,1,2),'0'),2,'0') ||                                   -- COMPANIA      (A2)
                    --ALM 20220309: Por peticion de Pedro, ponemos la fecha del mes de ejecucion.
                    --LPAD(IFNULL(TO_CHAR(COMPENSATIONDATE,'YYYYMM'), '0'),6,'0') ||                   -- FECHA_CARGO   (N6)
                    LPAD(IFNULL(TO_CHAR(v_PeriodStartDate,'YYYYMM'), '0'),6,'0') ||                -- FECHA_CARGO   (N6)
                    RPAD(' ',10) ||                                                                 -- CONCEPTO
                    RPAD('COMER',6,' ') ||                                                          -- SISTEMA
                    --En pagos comerciales en el codigo de poliza puede venir el earninggroupid, en ese caso ponemos 9999999 en poliza, 0s en subpoliza y 'C' en situacion    
                    --LPAD(IFNULL(CASE WHEN SUBSTR(PRODUCTID,3,1) = '2'
                    --    THEN SUBSTR(CODIGO_POLIZA,1,11)
                    --    ELSE SUBSTR(CODIGO_POLIZA,1,7)
                    --END,'0'),11, '0') ||                                                            -- POLIZA                        
                    --LPAD(IFNULL(CASE WHEN SUBSTR(PRODUCTID,3,1) = '2'
                    --    THEN SUBSTR(CODIGO_POLIZA,12,5)
                    --    ELSE SUBSTR(CODIGO_POLIZA,8,5)
                    --END,'0'),5,'0') ||                                                              -- SUBPOLIZA
                    LPAD(IFNULL(CASE WHEN CODIGO_POLIZA LIKE '%S%' THEN '99999999999' ELSE (
                        CASE WHEN SUBSTR(PRODUCTID,3,1) = '2'
                            THEN SUBSTR(CODIGO_POLIZA,1,11)
                            ELSE SUBSTR(CODIGO_POLIZA,1,7)
                        END) 
                    END,'0'),11,'0') ||                                                             -- POLIZA           (N11)         
                    LPAD(IFNULL(CASE WHEN CODIGO_POLIZA LIKE '%S%' THEN '00000' ELSE (
                        CASE WHEN SUBSTR(PRODUCTID,3,1) = '2'
                            THEN SUBSTR(CODIGO_POLIZA,12,5)
                            ELSE SUBSTR(CODIGO_POLIZA,8,5)
                        END)
                    END,'0'),5,'0') ||                                                              -- SUBPOLIZA
                    LPAD(IFNULL(CASE WHEN CODIGO_POLIZA LIKE '%S%' THEN '000' ELSE (
                        CASE WHEN SUBSTR(PRODUCTID,3,1) = '2'
                            THEN '0'
                            --ELSE TO_CHAR(SUBSTR(CODIGO_POLIZA,13,3))
                            ELSE TO_CHAR(RIGHT(CODIGO_POLIZA,3))
                        END)
                    END,'0'),3,'0') ||                                                              -- ORDEN

                    LPAD(IFNULL(SUBSTR(PRODUCTID,3,5),'0'),5,'0') ||                                   -- PRODUCTO
                        
                    --ALM 20220309: Agrupamos para que por cada poliza salga unicamente una fila con todo el importe sumado.
                    --              De momento se queda sin agrupar hasta que Pedro nos confirme.
                    RPAD(IFNULL(CASE WHEN IMPORTE < 0
                        THEN '-' ELSE '+' END,' '),1,' ' ) ||                                       -- SIGNO
                    -- LPAD(IFNULL((TRUNC(ABS(ROUND(IMPORTE,2)))),'0'),12,'0') ||
                     LPAD(IFNULL((CAST(ABS(ROUND(IMPORTE,2)) AS INTEGER)),'0'),12,'0') || 
                    LPAD(IFNULL(ABS(MOD(ROUND(IMPORTE,2),1)*100),'0'),2,'0')  ||                       -- IMPORTE
                    --RPAD(IFNULL(CASE WHEN SUM(IMPORTE) < 0
                    --    THEN '-' ELSE '+' END,' '),1,' ' ) ||                                       -- SIGNO
                    --LPAD(IFNULL((TRUNC(ABS(SUM(IMPORTE)))),'0'),12,'0') || 
                    --LPAD(IFNULL(ABS(MOD(ROUND(SUM(IMPORTE)),1)*100),'0'),2,'0')  ||                    -- IMPORTE
                        
                    LPAD(IFNULL(SUBSTR(POS_PRIN,1,4),'0'),4,'0') ||                                    -- OFICINA CONTABLE
                    LPAD('0000',4) ||                                                               -- OFICINA GESTORA
                    LPAD('0000',4) ||                                                               -- OFICINA COBRADORA
                    
                    --LPAD(IFNULL(SUBSTR(COD_AGENTE,1,4),'0'),4,'0') || 
                    --LPAD(IFNULL(SUBSTR(COD_AGENTE,7,4),'0'),4,'0') ||                                  -- CODIGO AGENTE
                    (CASE WHEN EARNINGGROUPID LIKE '%S4%'
                        THEN LPAD(IFNULL(SUBSTR(POS_PRIN,1,4),'0'),4,'0') || 
                             --ALM 20220630: Si el codigo de agente es 999999 ponemos 000000.
                             --LPAD(IFNULL(SUBSTR(POS_PRIN,7,4),'0'),4,'0')
                             LPAD(IFNULL(CASE WHEN SUBSTR(POS_PRIN,5,6) = '999999' THEN '0000' ELSE SUBSTR(POS_PRIN,7,4) END,'0'),4,'0')
                        ELSE LPAD('00000000',8)
                    END) ||                                                                         -- CODIGO AGENTE
                    
                    --LPAD(IFNULL(SUBSTR(MANAGER_POS_PRIN,1,4),'0'),4,'0') || 
                    --LPAD(IFNULL(SUBSTR(MANAGER_POS_PRIN,7,4),'0'),4,'0') ||                            -- INSPECTOR
                    (CASE WHEN EARNINGGROUPID LIKE '%S5%'
                        THEN LPAD(IFNULL(SUBSTR(POS_PRIN,1,4),'0'),4,'0') || 
                             --ALM 20220630: Si el codigo de agente es 999999 ponemos 000000.
                             --LPAD(IFNULL(SUBSTR(POS_PRIN,7,4),'0'),4,'0')
                             LPAD(IFNULL(CASE WHEN SUBSTR(POS_PRIN,5,6) = '999999' THEN '0000' ELSE SUBSTR(POS_PRIN,7,4) END,'0'),4,'0')
                        ELSE LPAD('00000000',8)
                    END) ||                                                                         -- INSPECTOR
                    
                    RPAD(' ',4) ||                                                                  -- SUBCUENTA
                    CASE WHEN CC.CONCEPTO_PAGO IS NOT NULL AND CC.TIPO_AGENTE IS NOT NULL
                        --ALM 20220318: Para los agentes de asistencia hay que usar ademas de la tipologia el programa de pago. 
                        --THEN LPAD(IFNULL(SUBSTR(CC.CONCEPTO_CONTABLE,1,4),'0'),4,'0')
                        THEN (CASE WHEN CC.CONCEPTO_CONTABLE = '151'
                                THEN (CASE WHEN PROGRAMA = 'MACB101P' THEN '0151' ELSE '0152'END)
                                ELSE LPAD(IFNULL(SUBSTR(CC.CONCEPTO_CONTABLE,1,4),'0'),4,'0')
                            END)
                        ELSE LPAD(IFNULL(SUBSTR(EARNINGCODEID,1,3),'0'),4,'0') 
                    END ||                                                                          -- CONCEPTO ORIGEN   (N4)
                    
                    RPAD(' ',1) ||                                                                  -- DESTINO CONTABLE 
                    RPAD(' ',4) ||                                                                  -- DEPARTAMENTO 
                    RPAD(' ',5) ||                                                                  -- REFERENCIA
                    
                    --ALM 20220425: Por peticion de Mariano ponemos siempre estado C. 
                    --(CASE WHEN CODIGO_POLIZA LIKE '%S%' THEN 'C' ELSE (
                    --IFNULL(RPAD(ESTADO,1), ' ')) END)                                                  -- SITUACION
                    'C'                                                                             --SITUACION
                FROM EXT.FINAL_REPEXT_FILE RP
                --ALM 20220513: Como los datos de esta tabla se guardan a mano por el momento usamos un TRIM para evitar espacios que puedan dar lugar a diferencias no debidas.
                --LEFT JOIN INYCEXT.INYC_CONCEPTOS_CONTABLES CC ON CC.CONCEPTO_PAGO = SUBSTR(RP.EARNINGCODEID,1,3) AND CC.TIPO_AGENTE = TO_CHAR(SUBSTR(RP.TIPO_AGENTE,1,3))
                --ALM 20220525: Por peticion de Mariano, cambiamos el concepto 410 por el 404 para todos los casos y antes de cruzar con la tabla de cambios de concepto.
                --LEFT JOIN EXT.CONF_REPEXT_CONCEPTOS_CONTABLES_FILE = SUBSTR(RP.EARNINGCODEID,1,3) AND TRIM(CC.TIPO_AGENTE) = TO_CHAR(SUBSTR(RP.TIPO_AGENTE,1,3))
                LEFT JOIN EXT.CONF_REPEXT_CONCEPTOS_CONTABLES_FILE CC ON TRIM(CC.CONCEPTO_PAGO) =  (CASE WHEN SUBSTR(RP.EARNINGCODEID,1,3) = '410' THEN '404' ELSE SUBSTR(RP.EARNINGCODEID,1,3) END)
                   --SMM 20251120 AND TRIM(CC.TIPO_AGENTE) = TO_CHAR(SUBSTR(RP.TIPO_AGENTE,1,3))
				--    AND TRIM(CC.TIPO_AGENTE) = TO_CHAR(FLOOR(RP.TIPO_AGENTE))
				   AND TRIM(CC.TIPO_AGENTE) = FLOOR(TO_VARCHAR(RP.TIPO_AGENTE))
                WHERE RP.PERIODSEQ = v_periodSeq
                --GROUP BY PRODUCTID,CODIGO_POLIZA,POS_PRIN,COD_AGENTE,MANAGER_POS_PRIN,CC.CONCEPTO_PAGO,CC.TIPO_AGENTE,CC.CONCEPTO_CONTABLE,EARNINGCODEID,ESTADO
                
                ;
            
            v_num_rows = ::ROWCOUNT;   
            -- COMMIT;
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Carga de la tabla FINAL_REPEXT_INF_PYG_FILE. Recibos Cobrados: '|| to_char(v_num_rows) || ' filas.', v_log_count, v_idproceso, 'info');
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Carga de la tabla FINAL_REPEXT_INF_PYG_FILE. Recibos Pendientes.', v_log_count, v_idproceso, 'info');
            
            INSERT INTO EXT.FINAL_REPEXT_INF_PYG_FILE
                SELECT * FROM EXT.OUT_REPEXT_INF_PYG_P_FILE WHERE PERIODSEQ = v_periodSeq;
            
            v_num_rows = ::ROWCOUNT;   
            -- COMMIT;
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Carga de la tabla FINAL_REPEXT_INF_PYG_FILE. Recibos Pendientes: '|| to_char(v_num_rows) || ' filas.', v_log_count, v_idproceso, 'info');
            
            -- INSERT INTO EXT.FINAL_REPEXT_INF_PyG_FILE(LINE,PERIODSEQ)
            -- VALUES('01',v_periodSeq);
            -- INSERT INTO EXT.FINAL_REPEXT_INF_PyG_FILE(LINE,PERIODSEQ)
            -- VALUES('03',v_periodSeq);
            ----------------------------EXT.FINAL_REPEXT_INF_PYG_FILE----------------------------
            
            ----------------------------EXT.FINAL_REPEXT_CDA_FILE----------------------------
            v_DesError := 'CARGA CDA';
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Borrado de la tabla FINAL_REPEXT_CDA_FILE.', v_log_count, v_idproceso, 'info');
            
            DELETE FROM EXT.FINAL_REPEXT_CDA_FILE WHERE PERIODSEQ = v_periodSeq;
            
            v_num_rows = ::ROWCOUNT;              
            -- COMMIT;
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Borrado de la tabla FINAL_REPEXT_CDA_FILE: ' || to_char(v_num_rows) || ' filas borradas.', v_log_count, v_idproceso, 'info');
            
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Carga de la tabla FINAL_REPEXT_CDA_FILE. DATOS CONTABLES.', v_log_count, v_idproceso, 'info');
            
            INSERT INTO EXT.FINAL_REPEXT_CDA_FILE(PERIODSEQ,LINE)
                SELECT
                    --ALM 20220527: Nuevo campo para las particiones.
                    v_periodSeq AS PERIODSEQ,
                    LPAD(IFNULL(SUBSTR(RP.PRODUCTID,1,2),'0'),2,'0') ||                                                -- COMPANIA          (A2)
                    --ALM 20220309: Por peticion de Pedro, ponemos la fecha del mes de ejecucion.
                    --LPAD(IFNULL(TO_CHAR(COMPENSATIONDATE,'YYYYMM'), '0'),6,'0') ||                                   -- FECHA_CARGO       (N6)
                    LPAD(IFNULL(REPLACE(TO_CHAR(v_PeriodStartDate,'YYYYMM'),' ',''), '0'),6,'0') ||                -- FECHA_CARGO       (N6)
                    RPAD('COMER',6,' ') ||                                                                          -- SISTEMA           (A6)
                    RPAD(' ',10) ||                                                                                 -- CONCEPTO          (A10)
                    CASE WHEN CC.CONCEPTO_PAGO IS NOT NULL AND CC.TIPO_AGENTE IS NOT NULL
                        --ALM 20220318: Para los agentes de asistencia hay que usar ademas de la tipologia el programa de pago. 
                        --THEN LPAD(IFNULL(SUBSTR(CC.CONCEPTO_CONTABLE,1,4),'0'),4,'0')
                        THEN (CASE WHEN CC.CONCEPTO_CONTABLE = '151'
                                THEN (CASE WHEN RP.PROGRAMA = 'MACB101P' THEN '0151' ELSE '0152'END)
                                ELSE LPAD(IFNULL(REPLACE(SUBSTR(CC.CONCEPTO_CONTABLE,1,4),' ',''),'0'),4,'0')
                            END)
                        ELSE LPAD(IFNULL(REPLACE(SUBSTR(RP.EARNINGCODEID,1,3),' ',''),'0'),4,'0') 
                    END ||                                                                          -- CONCEPTO ORIGEN   (N4)
                    
                    --ALM 20220309: Agrupamos para que por cada poliza salga unicamente una fila con todo el importe sumado.
                    --              DE MOMENTO SE QUEDA SIN AGRUPAR HASTA QUE PEDRO NOS CONFIRME.
                    RPAD(IFNULL(CASE WHEN RP.IMPORTE < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||           -- SIGNO             (A1)
                    -- LPAD(IFNULL(REPLACE((TRUNC(ABS(ROUND(RP.IMPORTE,2)))),' ',''),'0'),12,'0') ||
                    LPAD(IFNULL(REPLACE((CAST(ABS(ROUND(RP.IMPORTE,2))AS INTEGER)),' ',''),'0'),12,'0') || 
                    LPAD(IFNULL(REPLACE(ABS(MOD(ROUND(RP.IMPORTE,2),1)*100),' ',''),'0'),2,'0')  ||      -- IMPORTE           (N14)
                    --RPAD(IFNULL(CASE WHEN SUM(IMPORTE) < 0
                    --        THEN '-' ELSE '+' END,' '),1,' ' ) ||                                   -- SIGNO             (A1)
                    --LPAD(IFNULL((TRUNC(ABS(SUM(IMPORTE)))),'0'),12,'0') || 
                    --LPAD(IFNULL(ABS(MOD(ROUND(SUM(IMPORTE)),1)*100),'0'),2,'0')  ||                    -- IMPORTE           (N14)
                    
                    --ALM 20220608: Javier nos indica que el manda la oficina del agente que viene en la transaccion, pero por el momento lo dejamos como esta.
                    --LPAD(IFNULL(SUBSTR(COD_AGENTE,1,4),'0'),4,'0') ||                                  -- OFICINA CONTABLE  (N4)
                    --ALM 20220628: Solo usamos el agente de la poliza para los conceptos de agente.
                    --LPAD(IFNULL(SUBSTR(POS_PRIN,1,4),'0'),4,'0') ||                                    -- OFICINA CONTABLE  (N4)
                    --ALM 20220713: Para los pagos de los agentes con grupo de junio hay que usar el POS_PRIN porque el reparto no es correcto.
                    --              Pero al estar corregido el reparto de cada a julio solo aplicamos el nuevo filtro para junio.
                    --(CASE WHEN RP.EARNINGGROUPID LIKE '%S4%'
                    (CASE WHEN RP.EARNINGGROUPID LIKE '%S4%' AND (NOT(RP.TIPO_AGENTE BETWEEN 50 AND 65) OR TO_CHAR(v_PeriodStartDate,'YYYYMM') <> '202206') 
                    --JGE 20240130 condicion para controlar polizas CDA con oficina contable a ceros por correcciones manuales erroneas
                    AND RP.COD_AGENTE <> '0000000000'
                        THEN LPAD(IFNULL(REPLACE(SUBSTR(RP.COD_AGENTE,1,4),' ',''),'0'),4,'0')
                        ELSE LPAD(IFNULL(REPLACE(SUBSTR(RP.POS_PRIN,1,4),' ',''),'0'),4,'0')
                    END) ||                                                                         -- OFICINA CONTABLE  (N4)
                    LPAD('0000',4) ||                                                               -- OFICINA GESTORA   (N4)
                    LPAD('0000',4) ||                                                               -- OFICINA COBRADORA (N4)
                    
                    --ALM 20220425: Por peticion de Mariano devolvemos el agente al que le ha llegado la poliza no el que la ha cobrado.
                    --LPAD(IFNULL(SUBSTR(POS_PRIN,1,4),'0'),4,'0') || 
                    --LPAD(IFNULL(SUBSTR(POS_PRIN,5,6),'0'),6,'0') ||                                    -- CODIGO AGENTE     (N10)
                    --ALM 20220628: Solo usamos el agente de la poliza para los conceptos de agente.
                    --LPAD(IFNULL(SUBSTR(COD_AGENTE,1,4),'0'),4,'0') || 
                    --LPAD(IFNULL(SUBSTR(COD_AGENTE,5,6),'0'),6,'0') ||                                  -- CODIGO AGENTE     (N10)
                    --ALM 20220713: Para los pagos de los agentes con grupo de junio hay que usar el POS_PRIN porque el reparto no es correcto.
                    --              Pero al estar corregido el reparto de cada a julio solo aplicamos el nuevo filtro para junio.
                    --(CASE WHEN RP.EARNINGGROUPID LIKE '%S4%'
                    (CASE WHEN RP.EARNINGGROUPID LIKE '%S4%' AND (NOT(RP.TIPO_AGENTE BETWEEN 50 AND 65) OR TO_CHAR(v_PeriodStartDate,'YYYYMM') <> '202206')
                        THEN LPAD(IFNULL(REPLACE(SUBSTR(RP.COD_AGENTE,1,4),' ',''),'0'),4,'0') || 
                             --ALM 20220630: Si el codigo de agente es 999999 ponemos 000000.
                             --LPAD(IFNULL(SUBSTR(COD_AGENTE,5,6),'0'),6,'0')
                             LPAD(IFNULL(REPLACE(CASE WHEN SUBSTR(RP.COD_AGENTE,5,6) = '999999' THEN '000000' ELSE SUBSTR(RP.COD_AGENTE,5,6) END,' ',''),'0'),6,'0')
                        ELSE LPAD(IFNULL(REPLACE(SUBSTR(RP.POS_PRIN,1,4),' ',''),'0'),4,'0') || 
                             --ALM 20220630: Si el codigo de agente es 999999 ponemos 000000.
                             --LPAD(IFNULL(SUBSTR(POS_PRIN,5,6),'0'),6,'0')
                             LPAD(IFNULL(REPLACE(CASE WHEN SUBSTR(RP.POS_PRIN,5,6) = '999999' THEN '000000' ELSE SUBSTR(RP.POS_PRIN,5,6) END,' ',''),'0'),6,'0')
                    END) ||                                                                         -- CODIGO AGENTE
                    
                    --ALM 20220712: Por peticion de Mariano, devolvemos la tipologia del agente de la poliza en lugar del de la POS_PRIN si el concepto es de agente.
                    --RPAD(IFNULL(SUBSTR(RP.TIPO_AGENTE,1,3),' '), 3,' ') ||                             -- TIPO COMERCIAL    (A3)
                    --ALM 20220712: Usamos un JOIN en lugar de una subconsulta porque sino el rendimiento baja mucho.
                    --RPAD(CASE WHEN RP.EARNINGGROUPID LIKE '%S4%'
                    --    THEN (SELECT IFNULL(SUBSTR(POS.GENERICNUMBER2,1,3),' ') FROM TCMP.CS_POSITION POS
                    --        WHERE POS.GENERICATTRIBUTE3 = RP.COD_AGENTE
                    --        AND POS.TENANTID = v_idtenant AND POS.PROCESSINGUNITSEQ = 38280596832649217
                    --        AND POS.CREATEDATE < v_fecha_reparto
                    --        AND POS.REMOVEDATE > v_fecha_reparto
                    --        AND POS.EFFECTIVESTARTDATE <= ADD_DAYS(v_periodEndDate,-1)
                    --        AND POS.EFFECTIVEENDDATE > ADD_DAYS(v_periodEndDate,-1))
                    --    ELSE IFNULL(SUBSTR(RP.TIPO_AGENTE,1,3),' ')
                    --END, 3,' ') ||                                                                  -- TIPO COMERCIAL    (A3)
                    --ALM 20220713: Para los pagos de los agentes con grupo de junio hay que usar el POS_PRIN porque el reparto no es correcto.
                    --              Pero al estar corregido el reparto de cada a julio solo aplicamos el nuevo filtro para junio.
                    --RPAD(CASE WHEN RP.EARNINGGROUPID LIKE '%S4%'
                    RPAD(CASE WHEN RP.EARNINGGROUPID LIKE '%S4%' AND (NOT(RP.TIPO_AGENTE BETWEEN 50 AND 65) OR TO_CHAR(v_PeriodStartDate,'YYYYMM') <> '202206')
                        --Si es nulo porque no encuentra el codigo del agente (no deberia ocurrir) ponemos el principal.
                    --LFC 20251121:    THEN TO_NVARCHAR(FLOOR(IFNULL(SUBSTR(POS.GENERICNUMBER2,1,3),IFNULL(SUBSTR(RP.TIPO_AGENTE,1,3),' '))))
                    --    ELSE TO_NVARCHAR(FLOOR(IFNULL(SUBSTR(RP.TIPO_AGENTE,1,3),' ')))
					    --SMM 20251121 THEN TO_NVARCHAR(FLOOR(IFNULL(SUBSTR(POS.GENERICNUMBER2,1,3),IFNULL(FLOOR(RP.TIPO_AGENTE),' '))))	
						-- ELSE TO_NVARCHAR(FLOOR(IFNULL(FLOOR(RP.TIPO_AGENTE),' ')))				
						THEN TO_NVARCHAR(FLOOR(IFNULL(SUBSTR(POS.GENERICNUMBER2,1,3),IFNULL(TO_VARCHAR(FLOOR(RP.TIPO_AGENTE)),' '))))	
						ELSE TO_NVARCHAR(FLOOR(IFNULL(TO_VARCHAR(FLOOR(RP.TIPO_AGENTE)),' ')))
                    END, 3,' ') ||                                                                  -- TIPO COMERCIAL    (A3)
                    RPAD(IFNULL(SUBSTR(RP.NIF,1,10),' '),10,' ') ||                                    -- NIF AGENTE        (A10)

                    LPAD(IFNULL(REPLACE(SUBSTR(RP.PRODUCTID,3,6),' ',''),'0'),6,'0') ||                -- PRODUCTO          (N6)
                    LPAD(IFNULL(REPLACE(CASE WHEN RP.CODIGO_POLIZA LIKE '%S%' THEN '99999999999' ELSE (
                        CASE WHEN SUBSTR(RP.PRODUCTID,3,1) = '2'
                                THEN SUBSTR(RP.CODIGO_POLIZA,1,11)
                                ELSE SUBSTR(RP.CODIGO_POLIZA,1,7)
                                END) 
                    END,' ',''),'0'),11, '0') ||                                                    -- POLIZA           (N11)         
                    (CASE WHEN RP.CODIGO_POLIZA LIKE '%S%' THEN '00000' ELSE (
                        LPAD(IFNULL(REPLACE(CASE WHEN SUBSTR(RP.PRODUCTID,3,1) = '2'
                            THEN SUBSTR(RP.CODIGO_POLIZA,12,5)
                            ELSE SUBSTR(RP.CODIGO_POLIZA,8,5)
                            END,' ',''),'0'),5,'0'))
                    END) ||                                                                         -- SUBPOLIZA        (N5)
                    -- RAP 20220616 Pagos comerciales tienen el earningcodeid en la poliza
                    LPAD(IFNULL(REPLACE(CASE WHEN RP.CODIGO_POLIZA LIKE '%S%' THEN '00000' ELSE (
                        CASE WHEN SUBSTR(RP.PRODUCTID,3,1) = '2'
                            THEN '0'
                            --ELSE TO_CHAR(SUBSTR(CODIGO_POLIZA,13,3))
                            ELSE TO_CHAR(RIGHT(RP.CODIGO_POLIZA,3))
                        END)
                    END,' ',''),'0'),5,'0') ||                                                              -- ORDEN
                    --TGV 20221128 SE AÑADE EL CODIGO DE RECIBO PARA LOS PRODUCTOS 011 Y CONCEPTOS DE PAGO 150 QUE NO SEAN PAGOS COMERCIALES, RECUPERACIONES, GESTIONES, BAJAS O AGRUPADOS.
                    (CASE WHEN RP.PRODUCTID LIKE '011%' AND SUBSTR(RP.EARNINGCODEID,1,3) = '150' AND RP.CODIGO_POLIZA <> '99999999999' 
                        AND RP.EVENTTYPEID NOT IN ('Pago Comercial', '11','15') AND RP.SUBLINENUMBER <> 1
                        THEN LPAD(IFNULL(REPLACE(SUBSTR(RP.SUBLINENUMBER,1,8),' ',''),'0'),11,'0') ELSE                  
                    RPAD(' ',7) ||                                                                  -- CUENTA           (A7)
                    RPAD(' ',4)                                                                   -- SUBCUENTA        (A4)
                    END )       ||
                    --ALM 20220425: Por peticion de Mariano quitamos este campo del fichero.
                    --RPAD(IFNULL(SUBSTR(TIPO_REPARTO,1,2),' '), 2, ' ') ||                              -- TIPO REPARTO     (A2)
                    
                    RPAD(' ',1) ||                                                                  -- DESTINO CONTABLE (A1)
                    RPAD(IFNULL(SUBSTR(RP.TIPO_PAGO,1,44),' '),4,' ') ||                               -- TIPO PAGO        (A4)
                    RPAD(' ',5) ||                                                                  -- REFERENCIA       (A5)
                    
                    --ALM 20220425: Por peticion de Mariano ponemos siempre estado C.
                    --(CASE WHEN CODIGO_POLIZA LIKE '%S%' THEN 'C' ELSE (
                    --    RPAD(IFNULL(SUBSTR(ESTADO,1,1),' '),1,' ') )
                    --END)                                                                            -- SITUACION        (A1)
                    'C'                                                                             --SITUACION         (A1)
                FROM EXT.FINAL_REPEXT_FILE RP
                --ALM 20220513: Como los datos de esta tabla se guardan a mano por el momento usamos un TRIM para evitar espacios que puedan dar lugar a diferencias no debidas.
                --LEFT JOIN INYCEXT.INYC_CONCEPTOS_CONTABLES CC ON CC.CONCEPTO_PAGO = SUBSTR(RP.EARNINGCODEID,1,3) AND CC.TIPO_AGENTE = TO_CHAR(SUBSTR(RP.TIPO_AGENTE,1,3))
                --ALM 20220525: Por peticion de Mariano, cambiamos el concepto 410 por el 404 para todos los casos y antes de cruzar con la tabla de cambios de concepto.
                --LEFT JOIN EXT.CONF_REPEXT_CONCEPTOS_CONTABLES_FILE = SUBSTR(RP.EARNINGCODEID,1,3) AND TRIM(CC.TIPO_AGENTE) = TO_CHAR(SUBSTR(RP.TIPO_AGENTE,1,3))
                LEFT JOIN EXT.CONF_REPEXT_CONCEPTOS_CONTABLES_FILE CC ON TRIM(CC.CONCEPTO_PAGO) = (CASE WHEN SUBSTR(RP.EARNINGCODEID,1,3) = '410' THEN '404' ELSE SUBSTR(RP.EARNINGCODEID,1,3) END)
                    --SMM 20251120 AND TRIM(CC.TIPO_AGENTE) = TO_CHAR(SUBSTR(RP.TIPO_AGENTE,1,3))
					AND TRIM(CC.TIPO_AGENTE) = FLOOR(TO_VARCHAR(RP.TIPO_AGENTE))
                --ALM 20220712: Unimos por la tabla de CS_POSITION en lugar de usar una subconsulta por rendimiento.
                --ALM 20220713: Puede ocurrir que el COD_AGENTE no este activo y haya que buscar su tipologia en la ultima version en la que estuvo activo.
                --LEFT JOIN TCMP.CS_POSITION POS ON POS.GENERICATTRIBUTE3 = RP.COD_AGENTE
                --    AND POS.TENANTID = v_idtenant AND POS.PROCESSINGUNITSEQ = 38280596832649217
                --    AND POS.CREATEDATE < v_fecha_reparto
                --    AND POS.REMOVEDATE > v_fecha_reparto
                --    AND POS.EFFECTIVESTARTDATE <= ADD_DAYS(v_periodEndDate,-1)
                --    AND POS.EFFECTIVEENDDATE > ADD_DAYS(v_periodEndDate,-1)
                LEFT JOIN (SELECT X.GENERICATTRIBUTE3,X.GENERICNUMBER2,X.NAME FROM (
                    SELECT Y.GENERICATTRIBUTE3,Y.GENERICNUMBER2,Y.NAME,ROW_NUMBER() OVER (PARTITION BY Y.GENERICATTRIBUTE3 ORDER BY Y.EFFECTIVEENDDATE DESC) AS ULT_VER_POS
                    FROM TCMP.CS_POSITION Y 
                    WHERE Y.TENANTID = v_idtenant AND Y.PROCESSINGUNITSEQ = 38280596832649217
                        --ALM 20220719: Hay que coger versiones que no sean posteriores a la fecha del reparto.
                        --AND Y.REMOVEDATE = TO_DATE('22000101','yyyymmdd')
                        AND Y.REMOVEDATE > v_fecha_reparto
                        AND Y.CREATEDATE < v_fecha_reparto
                        AND Y.EFFECTIVESTARTDATE <= ADD_DAYS(v_periodEndDate,-1)
                    ) X
                    WHERE X.ULT_VER_POS = 1
                ) POS ON POS.GENERICATTRIBUTE3 = RP.COD_AGENTE
				--20251124 
				AND  POS.NAME = RP.POSITIONNAME
                WHERE RP.PERIODSEQ = v_periodSeq
                --GROUP BY PRODUCTID,CC.CONCEPTO_PAGO,CC.TIPO_AGENTE,CC.CONCEPTO_CONTABLE,EARNINGCODEID,POS_PRIN,COD_AGENTE,RP.TIPO_AGENTE,NIF,CODIGO_POLIZA,TIPO_REPARTO,TIPO_PAGO,ESTADO
                ;
            
            v_num_rows = ::ROWCOUNT;    
            -- COMMIT;
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Carga de la tabla FINAL_REPEXT_CDA_FILE. DATOS CONTABLES: '|| to_char(v_num_rows) || ' filas.', v_log_count, v_idproceso, 'info');
            
            --ALM 20220801: Separamos la carga de DATOS NO CONTABLES en dos insert, uno para agentes y otro para el resto.
            --              Asi podemos usar INNER en lugar de LEFT para que agilizar la consulta.
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Carga de la tabla FINAL_REPEXT_CDA_FILE. DATOS NO CONTABLES. Commissions TIPO 1.', v_log_count, v_idproceso, 'info');
            
            INSERT INTO EXT.FINAL_REPEXT_CDA_FILE(PERIODSEQ,LINE)
                SELECT
                    v_periodSeq AS PERIODSEQ,
                    LPAD(IFNULL(SUBSTR(BR.PRODUCTID,1,2),'0'),2,'0') ||                                                        -- COMPANIA          (A2)
                    LPAD(IFNULL(TO_CHAR(v_PeriodStartDate,'YYYYMM'), '0'),6,'0') ||                                        -- FECHA_CARGO       (N6)
                    RPAD('COMER',6,' ') ||                                                                                  -- SISTEMA           (A6)
                    RPAD(' ',10) ||                                                                                         -- CONCEPTO          (A10)

                    LPAD(IFNULL(CON.CONCEPTO,'0'),4,'0') ||                                                                    -- CONCEPTO ORIGEN   (N4)
                                
                    (CASE WHEN CON.CONCEPTO = '901' THEN
                            (CASE WHEN SUBSTR(BR.PRODUCTID,3,1) = '2' THEN
                                    RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_NETA_ANUAL) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||   -- SIGNO             (A1)
                                    -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_NETA_ANUAL),2)))),'0'),12,'0') ||
                                    LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_NETA_ANUAL),2))AS INTEGER)),'0'),12,'0') || 
                                    LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_NETA_ANUAL),2),1)*100),'0'),2,'0')                  -- IMPORTE           (N14)
                                ELSE
                                    RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_NETA) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||         -- SIGNO             (A1)
                                    -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_NETA),2)))),'0'),12,'0') ||
                                    LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_NETA),2))AS INTEGER)),'0'),12,'0') || 
                                    LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_NETA),2),1)*100),'0'),2,'0')                        -- IMPORTE           (N14)
                            END)
                        WHEN CON.CONCEPTO = '902' THEN
                            (CASE WHEN SUBSTR(BR.PRODUCTID,3,1) = '2' THEN
                                    RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_NETA_ANUAL) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||   -- SIGNO             (A1)
                                    -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_NETA_ANUAL),2)))),'0'),12,'0') ||
                                    LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_NETA_ANUAL),2))AS INTEGER)),'0'),12,'0') || 
                                    LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_NETA_ANUAL),2),1)*100),'0'),2,'0')                  -- IMPORTE           (N14)
                                ELSE
                                    RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_NETA) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||         -- SIGNO             (A1)
                                    -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_NETA),2)))),'0'),12,'0') ||
                                    LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_NETA),2))AS INTEGER)),'0'),12,'0') || 
                                    LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_NETA),2),1)*100),'0'),2,'0')                        -- IMPORTE           (N14)
                            END)
                        WHEN CON.CONCEPTO = '906' THEN
                            RPAD(IFNULL(CASE WHEN SUM(BR.POLIZA_FISICA) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||              -- SIGNO             (A1)
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.POLIZA_FISICA),2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.POLIZA_FISICA),2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.POLIZA_FISICA),2),1)*100),'0'),2,'0')                             -- IMPORTE           (N14)
                        WHEN CON.CONCEPTO = '907' THEN
                            RPAD(IFNULL(CASE WHEN SUM(BR.POLIZA_FISICA) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||              -- SIGNO             (A1)
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.POLIZA_FISICA),2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.POLIZA_FISICA),2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.POLIZA_FISICA),2),1)*100),'0'),2,'0')                             -- IMPORTE           (N14)
                        WHEN CON.CONCEPTO = '909' THEN
                            RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_COMIS_S4) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||             -- SIGNO             (A1)
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_COMIS_S4),2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_COMIS_S4),2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_COMIS_S4),2),1)*100),'0'),2,'0')                            -- IMPORTE           (N14)
                        WHEN CON.CONCEPTO = '913' THEN
                            RPAD(IFNULL(CASE WHEN SUM(BR.SERVICIO_ASISTENCIAS) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||       -- SIGNO             (A1)
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.SERVICIO_ASISTENCIAS),2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.SERVICIO_ASISTENCIAS),2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.SERVICIO_ASISTENCIAS),2),1)*100),'0'),2,'0')                      -- IMPORTE           (N14)
                        WHEN CON.CONCEPTO = '914' THEN
                            RPAD(IFNULL(CASE WHEN SUM(BR.POLIZA_CORREGIDA) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||           -- SIGNO             (A1)
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.POLIZA_CORREGIDA),2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.POLIZA_CORREGIDA),2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.POLIZA_CORREGIDA),2),1)*100),'0'),2,'0')                          -- IMPORTE           (N14)
                        WHEN CON.CONCEPTO = '915' THEN
                            (CASE WHEN SUM(BR.IMPORTE_COMISION) < 0 THEN '-00000000000100'
                                  WHEN SUM(BR.IMPORTE_COMISION) = 0 THEN '+00000000000000'
                                ELSE '+00000000000100' 
                            END)                                                                                            -- SIGNO + IMPORTE   (A1) + (N14)
                        WHEN CON.CONCEPTO = '917' THEN
                            RPAD(IFNULL(CASE WHEN SUM(BR.NUM_ASEG) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||                   -- SIGNO             (A1)
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.NUM_ASEG),2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.NUM_ASEG),2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.NUM_ASEG),2),1)*100),'0'),2,'0')                                  -- IMPORTE           (N14)
                        WHEN CON.CONCEPTO = '920' THEN
                            RPAD(IFNULL(CASE WHEN SUM(BR.POLIZA_CORREGIDA) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||           -- SIGNO             (A1)
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.POLIZA_CORREGIDA),2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.POLIZA_CORREGIDA),2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.POLIZA_CORREGIDA),2),1)*100),'0'),2,'0')                          -- IMPORTE           (N14)
                        --JGE 20230713 nuevo concepto para agentes zona
                        WHEN CON.CONCEPTO = '921' THEN
                            --JGE 20230731 por peticion de Javier no se hace distincion entre rrtt y el resto
                            --(CASE WHEN SUBSTR(BR.PRODUCTID,3,1) = '2' THEN
                            --        RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_NETA_ANUAL) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||   -- SIGNO             (A1)
                            --        LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_NETA_ANUAL),2)))),'0'),12,'0') || 
                            --        LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_NETA_ANUAL),2),1)*100),'0'),2,'0')                  -- IMPORTE           (N14)
                            --    ELSE
                            RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_NETA) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||         -- SIGNO             (A1)
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_NETA),2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_NETA),2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_NETA),2),1)*100),'0'),2,'0')                        -- IMPORTE           (N14)
                            --END)
                        ELSE '+00000000000000'
                    END) ||
                    
                    LPAD(IFNULL(SUBSTR(BR.COD_AGENTE,1,4),'0'),4,'0') ||                                                       -- OFICINA CONTABLE  (N4)
                    LPAD('0000',4) ||                                                                                       -- OFICINA GESTORA   (N4)
                    LPAD('0000',4) ||                                                                                       -- OFICINA COBRADORA (N4)
                    
                    LPAD(IFNULL(SUBSTR(BR.COD_AGENTE,1,4),'0'),4,'0') ||
                    LPAD(IFNULL(CASE WHEN SUBSTR(BR.COD_AGENTE,5,6) = '999999'
                        THEN CAST('000000' AS NVARCHAR(6))
                        ELSE SUBSTR(BR.COD_AGENTE,5,6)
                    END,'0'),6,'0') ||                                                                                      -- CODIGO AGENTE     (N10)
        
                    RPAD(TO_NVARCHAR(FLOOR(IFNULL(SUBSTR(POS_POLIZA.GENERICNUMBER2,1,3),' '))),3,' ') ||                                           -- TIPO COMERCIAL    (A3)
                    
                    RPAD(IFNULL(SUBSTR(POS_POLIZA.NAME,1,9),' '),10,' ') ||                                                    -- NIF AGENTE        (A10)
                    
                    LPAD(IFNULL(SUBSTR(BR.PRODUCTID,3,6),'0'),6,'0') ||                                                        -- PRODUCTO          (N6)
                    LPAD(IFNULL(CASE WHEN BR.CODIGO_POLIZA LIKE '%S%' THEN CAST('99999999999' AS NVARCHAR(11)) ELSE (
                        CASE WHEN SUBSTR(BR.PRODUCTID,3,1) = '2'
                                THEN SUBSTR(BR.CODIGO_POLIZA,1,11)
                                ELSE SUBSTR(BR.CODIGO_POLIZA,1,7)
                                END)
                    END,'0'),11, '0') ||                                                                                    -- POLIZA            (N11)
                    LPAD(IFNULL(CASE WHEN BR.CODIGO_POLIZA LIKE '%S%' THEN CAST('00000' AS NVARCHAR(5)) ELSE (
                        CASE WHEN SUBSTR(BR.PRODUCTID,3,1) = '2'
                            THEN SUBSTR(BR.CODIGO_POLIZA,12,5)
                            ELSE SUBSTR(BR.CODIGO_POLIZA,8,5)
                            END)
                    END,'0'),5,'0') ||                                                                                      -- SUBPOLIZA         (N5)
                    LPAD(IFNULL(CASE WHEN BR.CODIGO_POLIZA LIKE '%S%' THEN CAST('00000' AS NVARCHAR(5)) ELSE (
                        CASE WHEN SUBSTR(BR.PRODUCTID,3,1) = '2'
                            THEN CAST('00000' AS NVARCHAR(5))
                            ELSE RIGHT(BR.CODIGO_POLIZA,3)
                        END)
                    END,'0'),5,'0') ||    
                                                                                                      -- ORDEN             (N5)
                    --TGV 20221128 SE AÑADE EL CODIGO DE RECIBO PARA LOS PRODUCTOS 011 Y CONCEPTOS DE PAGO : POLCOBNP, PRINCPROS4 Y QUE NO SEAN PAGOS COMERCIALES, RECUPERACIONES, GESTIONES, BAJAS O AGRUPADOS.
                    (CASE WHEN BR.PRODUCTID LIKE '011%' AND CON.CONCEPTO IN ('906', '901') AND BR.CODIGO_POLIZA <> '99999999999' 
                        AND BR.EVENTTYPEID NOT IN ('Pago Comercial', '11','15') AND BR.SUBLINENUMBER <> 1
                        THEN LPAD(IFNULL(SUBSTR(BR.SUBLINENUMBER,1,8),'0'),11,'0') ELSE                  
                    RPAD(' ',7) ||                                                                  -- CUENTA           (A7)
                    RPAD(' ',4)                                                                   -- SUBCUENTA        (A4)
                    END)        ||           
                    
                    RPAD(' ',1) ||                                                                                          -- DESTINO CONTABLE  (A1)
                    
                    RPAD(' ',4) ||                                                                                          -- TIPO PAGO         (A4)
                    
                    RPAD(' ',5) ||                                                                                          -- REFERENCIA        (A5)
                    
                    'C'                                                                                                     -- SITUACION         (A1)
                    AS LINE
                FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE BR
                INNER JOIN EXT.CONF_REPEXT_CONCEPTOS_CDA_FILE CON ON CON.EVENTTYPEID = BR.EVENTTYPEID
                INNER JOIN (SELECT X.NAME,X.GENERICATTRIBUTE3,X.GENERICNUMBER2 FROM (
                    SELECT Y.NAME,Y.GENERICATTRIBUTE3,Y.GENERICNUMBER2,ROW_NUMBER() OVER (PARTITION BY Y.GENERICATTRIBUTE3 ORDER BY Y.EFFECTIVEENDDATE DESC) AS ULT_VER_POS
                    FROM TCMP.CS_POSITION Y 
                    WHERE Y.TENANTID = v_idtenant AND Y.PROCESSINGUNITSEQ = 38280596832649217
                        AND Y.REMOVEDATE > v_fecha_reparto
                        AND Y.CREATEDATE < v_fecha_reparto
                        AND Y.EFFECTIVESTARTDATE <= ADD_DAYS(v_periodEndDate,-1)
                        --ALM 20220808: Filtramos los registros con cod agente igual a 0 para que no se genren duplicados.
                        AND Y.GENERICATTRIBUTE3 <> '0000000000'
                    ) X
                    WHERE X.ULT_VER_POS = 1
                ) POS_POLIZA ON POS_POLIZA.GENERICATTRIBUTE3 = BR.COD_AGENTE
				--SMM 20251124
				--AND  POS_POLIZA.NAME = RP.POSITIONNAME
                    --AGENTES
                    AND (CON.TIPO = 1
                        AND (POS_POLIZA.GENERICNUMBER2 < 66 OR POS_POLIZA.GENERICNUMBER2 = 79 OR POS_POLIZA.GENERICNUMBER2 BETWEEN 100 AND 165 OR POS_POLIZA.GENERICNUMBER2 >= 300))
                WHERE BR.PERIODSEQ = v_periodSeq
                GROUP BY BR.PRODUCTID,BR.CODIGO_POLIZA,BR.EVENTTYPEID,BR.COD_AGENTE,BR.SUBLINENUMBER,
                    --POS_POLIZA.GENERICATTRIBUTE3,
                    POS_POLIZA.GENERICNUMBER2,SUBSTR(POS_POLIZA.NAME,1,9),
                    CON.CONCEPTO,CON.TIPO
                HAVING 
                    (SUM(BR.PRIMA_NETA_ANUAL) <> 0 AND SUBSTR(BR.PRODUCTID,3,1) = '2' AND CON.CONCEPTO IN ('901','902')) OR
                    (SUM(BR.PRIMA_NETA) <> 0 AND SUBSTR(BR.PRODUCTID,3,1) <> '2' AND CON.CONCEPTO IN ('901','902')) OR
                    (SUM(BR.POLIZA_FISICA) <> 0 AND CON.CONCEPTO IN ('906','907')) OR
                    (SUM(BR.PRIMA_COMIS_S4) <> 0 AND CON.CONCEPTO IN ('909')) OR
                    (SUM(BR.SERVICIO_ASISTENCIAS) <> 0 AND CON.CONCEPTO IN ('913')) OR
                    (SUM(BR.POLIZA_CORREGIDA) <> 0 AND CON.CONCEPTO IN ('914','920')) OR
                    (SUM(BR.IMPORTE_COMISION) <> 0 AND CON.CONCEPTO IN ('915')) OR
                    (SUM(BR.NUM_ASEG) <> 0 AND CON.CONCEPTO IN ('917'))
            ;
            
            v_num_rows = ::ROWCOUNT;   
            -- COMMIT;
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Carga de la tabla FINAL_REPEXT_CDA_FILE. DATOS NO CONTABLES. Commissions TIPO 1: '|| to_char(v_num_rows) || ' filas.', v_log_count, v_idproceso, 'info');
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Carga de la tabla FINAL_REPEXT_CDA_FILE. DATOS NO CONTABLES. Commissions TIPO 2 y 3.', v_log_count, v_idproceso, 'info');
            
            INSERT INTO EXT.FINAL_REPEXT_CDA_FILE(PERIODSEQ,LINE)
                SELECT
                    v_periodSeq AS PERIODSEQ,
                    LPAD(IFNULL(SUBSTR(BR.PRODUCTID,1,2),'0'),2,'0') ||                                                        -- COMPANIA          (A2)
                    LPAD(IFNULL(TO_CHAR(v_PeriodStartDate,'YYYYMM'), '0'),6,'0') ||                                        -- FECHA_CARGO       (N6)
                    RPAD('COMER',6,' ') ||                                                                                  -- SISTEMA           (A6)
                    RPAD(' ',10) ||                                                                                         -- CONCEPTO          (A10)

                    LPAD(IFNULL(CON.CONCEPTO,'0'),4,'0') ||                                                                    -- CONCEPTO ORIGEN   (N4)
                                
                    (CASE WHEN CON.CONCEPTO = '903' THEN
                            (CASE WHEN SUBSTR(BR.PRODUCTID,3,1) = '2' THEN
                                    RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_NETA_ANUAL) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||   -- SIGNO             (A1)
                                    -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_NETA_ANUAL),2)))),'0'),12,'0') ||
                                    LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_NETA_ANUAL),2))AS INTEGER)),'0'),12,'0') || 
                                    LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_NETA_ANUAL),2),1)*100),'0'),2,'0')                  -- IMPORTE           (N14)
                                ELSE
                                    RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_NETA) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||         -- SIGNO             (A1)
                                    -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_NETA),2)))),'0'),12,'0') ||
                                    LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_NETA),2))AS INTEGER)),'0'),12,'0') || 
                                    LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_NETA),2),1)*100),'0'),2,'0')                        -- IMPORTE           (N14)
                            END)
                        WHEN CON.CONCEPTO = '904' THEN
                            (CASE WHEN POS_PAGO.GENERICNUMBER2 NOT IN ('82','61') AND BR.EVENTTYPEID = '11' THEN '+00000000000000' ELSE
                                RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_CORREGIDA) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||        -- SIGNO             (A1)
                                -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_CORREGIDA),2)))),'0'),12,'0') ||
                                LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_CORREGIDA),2))AS INTEGER)),'0'),12,'0') || 
                                LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_CORREGIDA),2),1)*100),'0'),2,'0')                       -- IMPORTE           (N14)
                            END)
                        WHEN CON.CONCEPTO = '908' THEN
                            RPAD(IFNULL(CASE WHEN SUM(BR.POLIZA_CORR_MANAGER) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||        -- SIGNO             (A1)
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.POLIZA_CORR_MANAGER),2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.POLIZA_CORR_MANAGER),2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.POLIZA_CORR_MANAGER),2),1)*100),'0'),2,'0')                       -- IMPORTE           (N14)
                        WHEN CON.CONCEPTO = '910' THEN
                            (CASE WHEN POS_PAGO.GENERICNUMBER2 NOT IN ('82','61') AND BR.EVENTTYPEID = '11' THEN '+00000000000000' ELSE
                                RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_COMIS_S5) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||         -- SIGNO             (A1)
                                -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_COMIS_S5),2)))),'0'),12,'0') ||
                                LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_COMIS_S5),2))AS INTEGER)),'0'),12,'0') || 
                                LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_COMIS_S5),2),1)*100),'0'),2,'0')                        -- IMPORTE           (N14)
                            END)
                        WHEN CON.CONCEPTO = '911' THEN
                            RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_COMIS_S5) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||             -- SIGNO             (A1)
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_COMIS_S5),2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_COMIS_S5),2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_COMIS_S5),2),1)*100),'0'),2,'0')                            -- IMPORTE           (N14)
                        WHEN CON.CONCEPTO = '912' THEN
                            RPAD(IFNULL(CASE WHEN SUM(BR.PRIMA_CORREGIDA) < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||            -- SIGNO             (A1)
                            -- LPAD(IFNULL((TRUNC(ABS(ROUND(SUM(BR.PRIMA_CORREGIDA),2)))),'0'),12,'0') ||
                            LPAD(IFNULL((CAST(ABS(ROUND(SUM(BR.PRIMA_CORREGIDA),2))AS INTEGER)),'0'),12,'0') || 
                            LPAD(IFNULL(ABS(MOD(ROUND(SUM(BR.PRIMA_CORREGIDA),2),1)*100),'0'),2,'0')                           -- IMPORTE           (N14)
                        ELSE '+00000000000000'
                    END) ||
                    
                    LPAD(IFNULL(SUBSTR(POS_PAGO.GENERICATTRIBUTE3,1,4),'0'),4,'0') ||                                          -- OFICINA CONTABLE  (N4)
                    LPAD('0000',4) ||                                                                                       -- OFICINA GESTORA   (N4)
                    LPAD('0000',4) ||                                                                                       -- OFICINA COBRADORA (N4)
                    
                    LPAD(IFNULL(SUBSTR(POS_PAGO.GENERICATTRIBUTE3,1,4),'0'),4,'0') ||
                    LPAD(IFNULL(CASE WHEN SUBSTR(POS_PAGO.GENERICATTRIBUTE3,5,6) = '999999'
                        THEN CAST('000000' AS NVARCHAR(6))
                        ELSE SUBSTR(POS_PAGO.GENERICATTRIBUTE3,5,6)
                    END,'0'),6,'0') ||                                                                                      -- CODIGO AGENTE     (N10)
        
                    RPAD(TO_NVARCHAR(FLOOR(IFNULL(SUBSTR(POS_PAGO.GENERICNUMBER2,1,3),' '))),3,' ') ||                                             -- TIPO COMERCIAL    (A3)
                    
                    RPAD(IFNULL(SUBSTR(POS_PAGO.NAME,1,9),' '),10,' ') ||                                                      -- NIF AGENTE        (A10)
                    
                    LPAD(IFNULL(SUBSTR(BR.PRODUCTID,3,6),'0'),6,'0') ||                                                        -- PRODUCTO          (N6)
                    LPAD(IFNULL(CASE WHEN BR.CODIGO_POLIZA LIKE '%S%' THEN CAST('99999999999' AS NVARCHAR(11)) ELSE (
                        CASE WHEN SUBSTR(BR.PRODUCTID,3,1) = '2'
                                THEN SUBSTR(BR.CODIGO_POLIZA,1,11)
                                ELSE SUBSTR(BR.CODIGO_POLIZA,1,7)
                                END)
                    END,'0'),11, '0') ||                                                                                    -- POLIZA            (N11)
                    LPAD(IFNULL(CASE WHEN BR.CODIGO_POLIZA LIKE '%S%' THEN CAST('00000' AS NVARCHAR(5)) ELSE (
                        CASE WHEN SUBSTR(BR.PRODUCTID,3,1) = '2'
                            THEN SUBSTR(BR.CODIGO_POLIZA,12,5)
                            ELSE SUBSTR(BR.CODIGO_POLIZA,8,5)
                            END)
                    END,'0'),5,'0') ||                                                                                      -- SUBPOLIZA         (N5)
                    LPAD(IFNULL(CASE WHEN BR.CODIGO_POLIZA LIKE '%S%' THEN CAST('00000' AS NVARCHAR(5)) ELSE (
                        CASE WHEN SUBSTR(BR.PRODUCTID,3,1) = '2'
                            THEN CAST('00000' AS NVARCHAR(5))
                            ELSE RIGHT(BR.CODIGO_POLIZA,3)
                        END)
                    END,'0'),5,'0') ||                                                                                      -- ORDEN             (N5)

                    RPAD(' ',7) ||                                                                                          -- CUENTA            (A7)
                    RPAD(' ',4) ||                                                                                          -- SUBCUENTA         (A4)
                    
                    RPAD(' ',1) ||                                                                                          -- DESTINO CONTABLE  (A1)
                    
                    RPAD(' ',4) ||                                                                                          -- TIPO PAGO         (A4)
                    
                    RPAD(' ',5) ||                                                                                          -- REFERENCIA        (A5)
                    
                    'C'                                                                                                     -- SITUACION         (A1)
                    AS LINE
                FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE BR
                INNER JOIN EXT.CONF_REPEXT_CONCEPTOS_CDA_FILE CON ON CON.EVENTTYPEID = BR.EVENTTYPEID
                --ALM 20220801: Sigue ralentizando demasiado el proceso por lo que usamos una subconsulta.
                --INNER JOIN TCMP.CS_POSITION POS_PAGO ON POS_PAGO.TENANTID = v_idtenant AND POS_PAGO.PROCESSINGUNITSEQ = 38280596832649217
                --    AND POS_PAGO.CREATEDATE < v_fecha_reparto
                --    AND POS_PAGO.REMOVEDATE > v_fecha_reparto
                --    AND POS_PAGO.EFFECTIVESTARTDATE <= ADD_DAYS(v_periodEndDate,-1)
                --    AND POS_PAGO.EFFECTIVEENDDATE > ADD_DAYS(v_periodEndDate,-1)
                --    --AGENTE CON GRUPO / INSPECTOR
                --    AND ((CON.TIPO = 2
                --        AND ((POS_PAGO.GENERICNUMBER2 >= 50 AND POS_PAGO.GENERICNUMBER2 < 100 AND POS_PAGO.GENERICNUMBER2 <> 82)
                --            OR (POS_PAGO.GENERICNUMBER2 >= 150 AND POS_PAGO.GENERICNUMBER2 < 300)
                --            OR POS_PAGO.GENERICNUMBER2 >= 350)
                --        AND (BR.POS_PRIN = POS_PAGO.GENERICATTRIBUTE3 OR BR.MANAGER_POS_PRIN = POS_PAGO.GENERICATTRIBUTE3))
                --    --RESPONSABLE
                --    OR (CON.TIPO = 3
                --        AND POS_PAGO.GENERICNUMBER2 = 82
                --        AND (BR.POS_PRIN = POS_PAGO.GENERICATTRIBUTE3 OR BR.MANAGER_POS_PRIN = POS_PAGO.GENERICATTRIBUTE3 OR BR.MAN_ACT_POS_PRIN = POS_PAGO.GENERICATTRIBUTE3)
                --    ))
                --ALM 20220809: Usamos un HINT para mejorar el rendimiento y que primero ejecute la subconsulta y luego los filtros.
                INNER JOIN (SELECT   X.NAME,X.GENERICATTRIBUTE3,X.GENERICNUMBER2 FROM TCMP.CS_POSITION X
                    WHERE X.TENANTID = v_idtenant AND X.PROCESSINGUNITSEQ = 38280596832649217
                        AND X.REMOVEDATE > v_fecha_reparto
                        AND X.CREATEDATE < v_fecha_reparto
                        AND X.EFFECTIVESTARTDATE <= ADD_DAYS(v_periodEndDate,-1)
                        AND X.EFFECTIVEENDDATE > ADD_DAYS(v_periodEndDate,-1)
                        --ALM 20220808: Filtramos los registros con cod agente igual a 0 para que no se genren duplicados.
                        AND X.GENERICATTRIBUTE3 <> '0000000000'
                ) POS_PAGO ON (
                    --AGENTE CON GRUPO / INSPECTOR
                    (CON.TIPO = 2
                        AND ((POS_PAGO.GENERICNUMBER2 >= 50 AND POS_PAGO.GENERICNUMBER2 < 100 AND POS_PAGO.GENERICNUMBER2 <> 82)
                            OR (POS_PAGO.GENERICNUMBER2 >= 150 AND POS_PAGO.GENERICNUMBER2 < 300)
                            OR POS_PAGO.GENERICNUMBER2 >= 350)
                        AND ((BR.POS_PRIN = POS_PAGO.GENERICATTRIBUTE3) OR
                            (BR.MANAGER_POS_PRIN = POS_PAGO.GENERICATTRIBUTE3)))
                    OR 
                    --RESPONSABLE
                    (CON.TIPO = 3
                        AND POS_PAGO.GENERICNUMBER2 = 82
                        AND ((BR.POS_PRIN = POS_PAGO.GENERICATTRIBUTE3) OR
                            (BR.MANAGER_POS_PRIN = POS_PAGO.GENERICATTRIBUTE3) OR
                            (BR.MAN_ACT_POS_PRIN = POS_PAGO.GENERICATTRIBUTE3)))
                    )
                WHERE BR.PERIODSEQ = v_periodSeq
                GROUP BY BR.PRODUCTID,BR.CODIGO_POLIZA,BR.EVENTTYPEID,--BR.COD_AGENTE,
                    POS_PAGO.GENERICATTRIBUTE3,
                    POS_PAGO.GENERICNUMBER2,
                    SUBSTR(POS_PAGO.NAME,1,9),
                    CON.CONCEPTO,CON.TIPO
                HAVING 
                    (SUM(BR.PRIMA_NETA_ANUAL) <> 0 AND SUBSTR(BR.PRODUCTID,3,1) = '2' AND CON.CONCEPTO IN ('903')) OR
                    (SUM(BR.PRIMA_NETA) <> 0 AND SUBSTR(BR.PRODUCTID,3,1) <> '2' AND CON.CONCEPTO IN ('903')) OR
                    (SUM(BR.PRIMA_CORREGIDA) <> 0 AND CON.CONCEPTO IN ('904','912')) OR
                    (SUM(BR.POLIZA_CORR_MANAGER) <> 0 AND CON.CONCEPTO IN ('908')) OR
                    (SUM(BR.PRIMA_COMIS_S5) <> 0 AND CON.CONCEPTO IN ('910','911'))
            ;
            
            v_num_rows = ::ROWCOUNT;   
            -- COMMIT;
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Carga de la tabla FINAL_REPEXT_CDA_FILE. DATOS NO CONTABLES. Commissions TIPO 2 y 3: '|| to_char(v_num_rows) || ' filas.', v_log_count, v_idproceso, 'info');

            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Carga de la tabla FINAL_REPEXT_CDA_FILE. DATOS NO CONTABLES. Cartera DDEE LP.', v_log_count, v_idproceso, 'info');
            
            INSERT INTO EXT.FINAL_REPEXT_CDA_FILE(PERIODSEQ,LINE)
                SELECT
                    v_periodSeq AS PERIODSEQ,
                    LPAD(IFNULL(SUBSTR(CAR_LP.PRODUCTID,1,2),'0'),2,'0') ||                                                    -- COMPANIA          (A2)
                    LPAD(IFNULL(REPLACE(TO_CHAR(v_PeriodStartDate,'YYYYMM'),' ',''), '0'),6,'0') ||                        -- FECHA_CARGO       (N6)
                    RPAD('COMER',6,' ') ||                                                                                  -- SISTEMA           (A6)
                    RPAD(' ',10) ||                                                                                         -- CONCEPTO          (A10)

                    LPAD(IFNULL(REPLACE(CON.CONCEPTO,' ',''),'0'),4,'0') ||                                                    -- CONCEPTO ORIGEN   (N4)
                                
                    (CASE WHEN CON.CONCEPTO = '902' THEN
                            RPAD(IFNULL(CASE WHEN CAR_LP.PRIMA_NETA < 0 THEN '-' ELSE '+' END,' '),1,' ' ) ||
                            -- LPAD(IFNULL(REPLACE((TRUNC(ABS(ROUND(CAR_LP.PRIMA_NETA,2)))),' ',''),'0'),12,'0') ||
                            LPAD(IFNULL(REPLACE((CAST(ABS(ROUND(CAR_LP.PRIMA_NETA,2))AS INTEGER)),' ',''),'0'),12,'0') || 
                            LPAD(IFNULL(REPLACE(ABS(MOD(ROUND(CAR_LP.PRIMA_NETA,2),1)*100),' ',''),'0'),2,'0')
                         WHEN CON.CONCEPTO = '907' THEN
                            (CASE WHEN SUBSTR(CAR_LP.ORDERID, 3,1) = '2' AND SUBSTR(CAR_LP.ORDERID, 5,1) <> '0'
                                THEN LPAD('+00000000000000',15)           
                                ELSE (CASE WHEN CAR_LP.PRIMA_NETA < 0 THEN LPAD('-00000000000001',15) ELSE LPAD('+00000000000001',15) END)
                            END)
                          ELSE '+00000000000000'
                    END) ||                                                                                                 -- SIGNO + IMPORTE   (A1) + (N14)
                    
                    LPAD(IFNULL(REPLACE(SUBSTR(CAR_LP.COD_AGENTE,1,4),' ',''),'0'),4,'0') ||                                   -- OFICINA CONTABLE  (N4)
                    LPAD('0000',4) ||                                                                                       -- OFICINA GESTORA   (N4)
                    LPAD('0000',4) ||                                                                                       -- OFICINA COBRADORA (N4)
                    
                    LPAD(IFNULL(REPLACE(SUBSTR(CAR_LP.COD_AGENTE,1,4),' ',''),'0'),4,'0') || 
                    LPAD(IFNULL(REPLACE(SUBSTR(CAR_LP.COD_AGENTE,5,6),' ',''),'0'),6,'0') ||                                   -- CODIGO AGENTE     (N10)
                    
                    LPAD(TO_NVARCHAR(FLOOR(IFNULL(CAST(POS.GENERICNUMBER2 AS NVARCHAR(3)),'0'))), 3,'0') ||                                       -- TIPO COMERCIAL    (A3)
                    RPAD(IFNULL(SUBSTR(PART.GENERICATTRIBUTE1,1,10),' '),10,' ') ||                                            -- NIF AGENTE        (A10)
                    
                    LPAD(IFNULL(REPLACE(SUBSTR(CAR_LP.PRODUCTID,3,6),' ',''),'0'),6,'0') ||                                    -- PRODUCTO          (N6)
                    LPAD(IFNULL(REPLACE((CASE WHEN CAR_LP.POLIZA LIKE '%S%' THEN '99999999999' ELSE 
                        (CASE WHEN SUBSTR(CAR_LP.PRODUCTID,3,1) = '2'
                                THEN SUBSTR(CAR_LP.POLIZA,1,11)
                                ELSE SUBSTR(CAR_LP.POLIZA,1,7)
                                END)
                    END),' ',''),'0'),11,'0') ||                                                                            -- POLIZA            (N11)
                    LPAD(IFNULL(REPLACE(CASE WHEN CAR_LP.POLIZA LIKE '%S%' THEN '00000' ELSE (
                        CASE WHEN SUBSTR(CAR_LP.PRODUCTID,3,1) = '2'
                            THEN SUBSTR(CAR_LP.POLIZA,12,5)
                            ELSE SUBSTR(CAR_LP.POLIZA,8,5)
                            END)
                    END,' ',''),'0'),5,'0') ||                                                                              -- SUBPOLIZA         (N5)
                    LPAD(IFNULL(REPLACE(CASE WHEN CAR_LP.POLIZA LIKE '%S%' THEN '00000' ELSE (
                        CASE WHEN SUBSTR(PRODUCTID,3,1) = '2' THEN '00000' 
                            ELSE RIGHT(POLIZA,3)
                        END)
                    END,' ',''),'0'),5,'0') ||                                                                              -- ORDEN             (N5)
                    RPAD(' ',7) ||                                                                                          -- CUENTA            (A7)
                    RPAD(' ',4) ||                                                                                          -- SUBCUENTA         (A4)
                    
                    RPAD(' ',1) ||                                                                                          -- DESTINO CONTABLE  (A1)
                    RPAD(' ',4) ||                                                                                          -- TIPO PAGO         (A4)
                    RPAD(' ',5) ||                                                                                          -- REFERENCIA        (A5)
                    'C'                                                                                                     -- SITUACION         (A1)
                    AS LINE
                FROM EXT.CARTERA_DDEE CAR_LP
                INNER JOIN TCMP.CS_POSITION POS ON CAR_LP.POSITIONNAME = POS.NAME
                    AND POS.TENANTID = v_idtenant AND POS.PROCESSINGUNITSEQ = 38280596832649217
                    AND POS.CREATEDATE < v_fecha_reparto
                    AND POS.REMOVEDATE > v_fecha_reparto
                    AND POS.EFFECTIVESTARTDATE <= ADD_DAYS(v_periodEndDate,-1)
                    AND POS.EFFECTIVEENDDATE > ADD_DAYS(v_periodEndDate,-1)
                INNER JOIN TCMP.CS_PARTICIPANT PART ON POS.PAYEESEQ = PART.PAYEESEQ
                    AND PART.TENANTID = v_idtenant
                    AND (PART.TERMINATIONDATE IS NULL OR PART.TERMINATIONDATE > v_fecha_reparto)
                    AND PART.CREATEDATE < v_fecha_reparto
                    AND PART.REMOVEDATE > v_fecha_reparto
                    AND PART.EFFECTIVESTARTDATE <= ADD_DAYS(v_periodEndDate,-1)
                    AND PART.EFFECTIVEENDDATE > ADD_DAYS(v_periodEndDate,-1)
                INNER JOIN EXT.CONF_REPEXT_CONCEPTOS_CDA_FILE CON ON CON.EVENTTYPEID = '81' AND CON.TIPO = '1'
                    --ALM 20220706: Al anadir la permanencia 81 al concepto 914 se incluiria una fila mas por agente que no tiene sentido para los DDEE.
                    AND CON.CONCEPTO <> '914'
                WHERE CAR_LP.COMPENSATIONDATE = v_PeriodStartDate
                    AND CAR_LP.ESTADO = 'C'
                    --JGE 20241218 meter condicion para evitar facturas vacias
                    AND CAR_LP.IMPORTE <> 0
            ;
            
            v_num_rows = ::ROWCOUNT;   
            -- COMMIT;
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Carga de la tabla FINAL_REPEXT_CDA_FILE. DATOS NO CONTABLES. Cartera DDEE LP: '|| to_char(v_num_rows) || ' filas.', v_log_count, v_idproceso, 'info');
            
            --ALM 20220705: Ya no es necesario borrar los regitros de inspector para las agencias.
            --              No se cargan en la consulta anterior al quitar la tipologia 100 de los conceptos de inspector. 
            --RAP 20220622 Por peticion de Mariano en la reunion del 20220621, y por correo de hoy, 20220622, se filtran los registros de las agencias que tengan 
            --                conceptos de primas y polizas de inspectores/managers (conceptos S5) (codigos de conceptos 903, 904, 908, 910, 911). 
            
            --
            --CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Borrado de registros de agencias con concepto 903,904,908,910,911 en la tabla FINAL_REPEXT_CDA_FILE. '|| to_char(filas) || ' filas.', v_log_count, v_idproceso, 'info');
            ----------------------------EXT.FINAL_REPEXT_CDA_FILE----------------------------
            
            ----------------------------EXT.FINAL_REPEXT_INF_SAP_FILE----------------------------
            v_DesError := 'CARGA SAP';
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Borrado de la tabla FINAL_REPEXT_INF_SAP_FILE.', v_log_count, v_idproceso, 'info');
            
            DELETE FROM EXT.FINAL_REPEXT_INF_SAP_FILE WHERE PERIODSEQ = v_periodSeq;
            
            v_num_rows = ::ROWCOUNT;             
            -- COMMIT;
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Borrado de la tabla FINAL_REPEXT_INF_SAP_FILE: ' || to_char(v_num_rows) || ' filas borradas.', v_log_count, v_idproceso, 'info');
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Carga de la tabla FINAL_REPEXT_INF_SAP_FILE.', v_log_count, v_idproceso, 'info');
            
            INSERT INTO EXT.FINAL_REPEXT_INF_SAP_FILE(PERIODSEQ,LINE)
                SELECT
                    --ALM 20220527: Nuevo campo para las particiones.
                    v_periodSeq AS PERIODSEQ,
                    PAGOS.TIPO_REGISTRO ||';'||
                    PAGOS.CIA_CODIGO ||';'||
                    PAGOS.PER_CIF_NIF ||';'||
                    PAGOS.PAG_REFERENCIA_ORIGEN ||';'||
                    PAGOS.TIPO_PAGO ||';'||
                    PAGOS.CARGO_LIQUIDACION ||';'||
                    PAGOS.PAG_OFICINA ||';'||
                    PAGOS.PAG_AGENTE ||';'||
                    PAGOS.PAG_COD_UNICO ||';'||
                    RPAD(PAGOS.PAG_CLASIF_AGENTE,2,' ') ||';'||
                    PAGOS.PAG_FECHA_FACTURA ||';'||
                    PAGOS.IRPF ||';'||
                    PAGOS.MONEDA ||';'||
                    --LIQEXT
                    PAGOS.COD_CONCEPTO ||';'||
                    PAGOS.OFICINA_GASTO ||';'||
                    PAGOS.PRODUCTO ||';'||
                    PAGOS.IMPORTE_COMISION ||';'||
                    PAGOS.CARGO_ABONO ||';'||
                    PAGOS.AUTORIZA_FACTURA ||';'||
                    PAGOS.ENVIAR_SII_AEAT ||';'||
                    PAGOS.ENVIAR_SII_ATC ||';'||
                    --PAGOS
                    PAGOS.PAG_IMPORTE ||';'||
                    PAGOS.SIGNO_PAG_IMPORTE ||';'||
                    PAGOS.AUT_IMPORTE ||';'||
                    PAGOS.SIGNO_AUT_IMPORTE ||';'||
                    PAGOS.VIA_PAGO ||';'||
                    PAGOS.ESTADO ||';'||
                    PAGOS.FECHA_ESTADO ||';'||
                    PAGOS.IBAN AS LINE
                FROM (
                    SELECT 'PA' AS TIPO_REGISTRO,
                        PAG.CIA_CODIGO,
                        IFNULL(RPAD(PAG.PER_CIF_NIF,10,' '), '          ') AS PER_CIF_NIF,
                        CAST(CASE WHEN EXTRACT(YEAR FROM v_PeriodStartDate) > '2021' AND SUBSTR(PAG.PAG_REFERENCIA_ORIGEN, 3, 4) > '2021'
                            THEN RPAD(( SUBSTR(PAG.PAG_REFERENCIA_ORIGEN, 1, 2) || SUBSTR(PAG.PAG_REFERENCIA_ORIGEN, 5, 11) || '/' || RIGHT( '0' || PAG.SECUENCIAL, 2)) ,23,' ')
                            ELSE RPAD(PAG.PAG_REFERENCIA_ORIGEN,23,' ')
                        END AS VARCHAR(23)) AS PAG_REFERENCIA_ORIGEN,
                        SUBSTR(PAG.PAG_REFERENCIA_ORIGEN,2,1) AS TIPO_PAGO,
                        SUBSTR(PAG.PAG_FECHA_LIQUIDACION,1,6) AS CARGO_LIQUIDACION,
                        PAG.PAG_OFICINA,
                        PAG.PAG_AGENTE,
                        RPAD(PAG.PAG_COD_UNICO,14,' ') AS PAG_COD_UNICO,
                        PAG.PAG_CLASIF_AGENTE,
                        SUBSTR(PAG.PAG_FECHA_FACTURA,7,2) || SUBSTR(PAG.PAG_FECHA_FACTURA,5,2) || SUBSTR(PAG.PAG_FECHA_FACTURA,1,4) AS PAG_FECHA_FACTURA,
                        LPAD(FLOOR(ABS(PAG.DC_IMPORTE30)),2,'0')||','||LPAD((ABS(MOD(ROUND(PAG.DC_IMPORTE30,2),1)*100)),2,'0') AS IRPF,
                        'EUR' AS MONEDA,
                                
                        --LIQEXT
                        RPAD(' ',3) AS COD_CONCEPTO,
                        RPAD(' ',4) AS OFICINA_GASTO,
                        RPAD(' ',5) AS PRODUCTO,
                        RPAD(' ',16) AS IMPORTE_COMISION,
                        RPAD(' ',1) AS CARGO_ABONO,
                        RPAD(' ',1) AS AUTORIZA_FACTURA,
                        RPAD(' ',1) AS ENVIAR_SII_AEAT,
                        RPAD(' ',1) AS ENVIAR_SII_ATC,
                                
                        --PAGEXT
                        -- RPAD(TRUNC(ABS(PAG.PAG_IMPORTE)) || LPAD((ABS(MOD(ROUND(PAG.PAG_IMPORTE,2),1)*100)),2,'0'),16,' ') AS PAG_IMPORTE,
                        RPAD(CAST(ABS(PAG.PAG_IMPORTE)AS INTEGER) || LPAD((ABS(MOD(ROUND(PAG.PAG_IMPORTE,2),1)*100)),2,'0'),16,' ') AS PAG_IMPORTE,
                        CASE WHEN PAG.PAG_IMPORTE < 0 THEN '-' ELSE ' ' END AS SIGNO_PAG_IMPORTE,
                        -- RPAD(IFNULL(TRUNC(ABS((SELECT SUM(AUT.IMPCOMIS) - ROUND((SUM(AUT.IMPCOMIS)*MAX(AUT.IRPF)),2)
                        RPAD(IFNULL(CAST(ABS((SELECT SUM(AUT.IMPCOMIS) - ROUND((SUM(AUT.IMPCOMIS)*MAX(AUT.IRPF)),2) 
                                    FROM EXT.FINAL_EXTRACTPAGOS_AUT_FILE AUT 
                                    --JGE 20230113: Actualizamos para usar PAG_REFERENCIA_ORIGEN
                                    --WHERE AUT.COFICINA = PAG.PAG_OFICINA AND AUT.CAGENTE = SUBSTR(PAG.PAG_AGENTE,-5) AND AUT.CCOMPANI = SUBSTR(PAG.CIA_CODIGO,-1))
                                     WHERE AUT.PERIODSEQ = PAG.PERIODSEQ AND AUT.PAG_REFERENCIA_ORIGEN = PAG.PAG_REFERENCIA_ORIGEN)
                                - (CASE WHEN PAG.PAG_IMPORTE = 0 THEN 0 ELSE ROUND((PAG.DC_IMPORTE1 * (100 - PAG.DC_IMPORTE30)/100),2) END))AS INTEGER) 
                            || LPAD((ABS(MOD(ROUND((SELECT SUM(AUT.IMPCOMIS) - ROUND((SUM(AUT.IMPCOMIS)*MAX(AUT.IRPF)),2) 
                                    FROM EXT.FINAL_EXTRACTPAGOS_AUT_FILE AUT
                                    --JGE 20230113: Actualizamos para usar PAG_REFERENCIA_ORIGEN
                                    --WHERE AUT.COFICINA = PAG.PAG_OFICINA AND AUT.CAGENTE = SUBSTR(PAG.PAG_AGENTE,-5) AND AUT.CCOMPANI = SUBSTR(PAG.CIA_CODIGO,-1))
                                     WHERE AUT.PERIODSEQ = PAG.PERIODSEQ AND AUT.PAG_REFERENCIA_ORIGEN = PAG.PAG_REFERENCIA_ORIGEN)
                                - (CASE WHEN PAG.PAG_IMPORTE = 0 THEN 0 ELSE ROUND((PAG.DC_IMPORTE1 * (100 - PAG.DC_IMPORTE30)/100),2) END),2),1)*100)),2,'0')
                        ,0),16,' ') AS AUT_IMPORTE,
                        --ALM 20220708: Hay que usar la misma resta que para el importe porque sino puede dar problemas.
                        --              Ej: Cargo = 202206, pag_referencia_origen = 142022067690612.
                        --                  Cargo = 202207, pag_referencia_origen = 142022077820142.
                        --CASE WHEN ((SELECT SUM(AUT.IMPCOMIS) FROM EXT.FINAL_EXTRACTPAGOS_AUT_FILE AUT 
                        --            WHERE AUT.COFICINA = PAG.PAG_OFICINA AND AUT.CAGENTE = SUBSTR(PAG.PAG_AGENTE,-5)) - PAG.DC_IMPORTE1) < 0
                        CASE WHEN ((SELECT SUM(AUT.IMPCOMIS) - ROUND((SUM(AUT.IMPCOMIS)*MAX(AUT.IRPF)),2) 
                                    FROM EXT.FINAL_EXTRACTPAGOS_AUT_FILE AUT 
                                    --JGE 20230113: Actualizamos para usar PAG_REFERENCIA_ORIGEN
                                    --WHERE AUT.COFICINA = PAG.PAG_OFICINA AND AUT.CAGENTE = SUBSTR(PAG.PAG_AGENTE,-5) AND AUT.CCOMPANI = SUBSTR(PAG.CIA_CODIGO,-1))
                                     WHERE AUT.PERIODSEQ = PAG.PERIODSEQ AND AUT.PAG_REFERENCIA_ORIGEN = PAG.PAG_REFERENCIA_ORIGEN)
                                - (CASE WHEN PAG.PAG_IMPORTE = 0 THEN 0 ELSE ROUND((PAG.DC_IMPORTE1 * (100 - PAG.DC_IMPORTE30)/100),2) END)) < 0
                            THEN '-' ELSE ' '
                        END AS SIGNO_AUT_IMPORTE,
                        (CASE WHEN PAG.PAG_CLASIF_AGENTE = 'EM' THEN 'T' ELSE
                            (CASE WHEN PAG.FPG_CODIGO = '2' THEN 'E'
                                  WHEN PAG.FPG_CODIGO = '3' THEN 'T'
                                  ELSE ' '
                            END)
                        END) AS VIA_PAGO,
                        --ALM 20220421: Como aqui no filtramos por estado, los pagos que no esten confirmados los devolvemos como retenidos.
                        (CASE WHEN PAG.ESTADO IN (0,1,2,3,4,5,6) THEN 'R'  --Incluimos en estado incial como Retenido, para la primera ejecucion
                              --WHEN PAG.ESTADO IN (2,4,6) THEN 'X'    --Nunca van a ir en el PAGEXT
                              WHEN PAG.ESTADO IN (7) THEN 'L'        --Solo el estado 7 (CONFIRMADO) se devuelve como pago liberado
                              WHEN PAG.ESTADO IN (8) THEN 'A'        --Pagos Anulados
                              WHEN PAG.ESTADO IN (9) THEN 'C'        --Pagos Compensados (Pago sin Pago)
                        END) AS ESTADO,
                        TO_CHAR(PAG.FECHA_ESTADO,'DDMMYYYY') AS FECHA_ESTADO,
                        RPAD(PAG.IBAN,24,' ') AS IBAN
                    FROM EXT.FINAL_EXTRACTPAGOS_FILE PAG
                    WHERE PAG.PERIODSEQ = v_periodSeq

                    UNION ALL

                    SELECT 'GA' AS TIPO_REGISTRO,
                        PAGEXT.CIA_CODIGO,
                        RPAD(PAGEXT.PER_CIF_NIF,10,' ') AS PER_CIF_NIF,
                        CAST(CASE WHEN EXTRACT(YEAR FROM v_PeriodStartDate) > '2021' AND SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 3, 4) > '2021'
                            THEN RPAD(( SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 1, 2) || SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 5, 11) || '/' || RIGHT( '0' || PAGEXT.SECUENCIAL, 2)) ,23,' ')
                            ELSE RPAD(PAGEXT.PAG_REFERENCIA_ORIGEN,23,' ')
                        END AS VARCHAR(23)) AS PAG_REFERENCIA_ORIGEN,
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1) AS TIPO_PAGO,
                        SUBSTR(PAGEXT.PAG_FECHA_LIQUIDACION,1,6) AS CARGO_LIQUIDACION,
                        PAGEXT.PAG_OFICINA,
                        PAGEXT.PAG_AGENTE,
                        RPAD(PAGEXT.PAG_COD_UNICO,14,' ') AS PAG_COD_UNICO,
                        PAGEXT.PAG_CLASIF_AGENTE,
                        SUBSTR(PAGEXT.PAG_FECHA_FACTURA,7,2) || SUBSTR(PAGEXT.PAG_FECHA_FACTURA,5,2) || SUBSTR(PAGEXT.PAG_FECHA_FACTURA,1,4) AS PAG_FECHA_FACTURA,
                        LPAD(FLOOR(ABS(PAGEXT.DC_IMPORTE30)),2,'0')||','||LPAD((ABS(MOD(ROUND(PAGEXT.DC_IMPORTE30,2),1)*100)),2,'0') AS IRPF,
                        'EUR' AS MONEDA,
                                
                        --LIQEXT
                        RPAD(LIQ.COD_CONCEPTO,3,' ') AS COD_CONCEPTO,
                        CAST(SUBSTR(LIQ.POSICION_COMERCIAL,1,4) AS VARCHAR(4)) AS OFICINA_GASTO,
                        (CASE WHEN LIQ.PRODUCTO IS NULL OR LIQ.PRODUCTO = '00000' THEN RPAD(' ',5) ELSE LIQ.PRODUCTO END) AS PRODUCTO,
                        --ALM 20220413: Por peticion de Juan Encinas, agrupamos los conceptos de IRPF
                        --RPAD(TRUNC(ABS(ROUND(LIQ.IMPORTE,2))) || LPAD((ABS(MOD(ROUND(LIQ.IMPORTE,2),1)*100)),2,'0'),16,' ') AS IMPORTE_COMISION,
                        --(CASE WHEN LIQ.IMPORTE >= 0 THEN 'D' ELSE 'H' END) AS CARGO_ABONO,
                        -- RPAD(TRUNC(ABS(ROUND(SUM(LIQ.IMPORTE),2))) || LPAD((ABS(MOD(ROUND(SUM(LIQ.IMPORTE),2),1)*100)),2,'0'),16,' ') AS IMPORTE_COMISION,
                        RPAD(CAST(ABS(ROUND(SUM(LIQ.IMPORTE),2))AS INTEGER) || LPAD((ABS(MOD(ROUND(SUM(LIQ.IMPORTE),2),1)*100)),2,'0'),16,' ') AS IMPORTE_COMISION,
                        (CASE WHEN SUM(LIQ.IMPORTE) >= 0 THEN 'D' ELSE 'H' END) AS CARGO_ABONO,
                        
                        RPAD(PAGEXT.ENVIO_SII,1,' ') AS AUTORIZA_FACTURA,
                        (CASE WHEN PAGEXT.ENVIO_SII = 'S' AND PAGEXT.SERCO_CANARIAS IS NULL THEN 'S' ELSE ' ' END) AS ENVIAR_SII_AEAT,
                        (CASE WHEN PAGEXT.ENVIO_SII = 'S' AND PAGEXT.SERCO_CANARIAS = 'C' THEN 'S' ELSE ' ' END) AS ENVIAR_SII_ATC,
                                
                        --PAGEXT
                        RPAD(' ',16) AS PAG_IMPORTE,
                        RPAD(' ',1) AS SIGNO_PAG_IMPORTE,
                        RPAD(' ',16) AS AUT_IMPORTE,
                        RPAD(' ',1) AS SIGNO_AUT_IMPORTE,
                        RPAD(' ',1) AS VIA_PAGO,
                        RPAD(' ',1) AS ESTADO,
                        RPAD(' ',8) AS FECHA_ESTADO,
                        RPAD(' ',24) AS IBAN
                        
                    --ALM 20220224: Para enero 2022 la tabla de EXT.FINAL_LIQEXT_CABECERA_FILE no esta correcta y usamos una creada a mano.
                    --FROM INYCEXT.INYC_LIQEXT_CAB_FINAL_202201 LIQ
                    FROM EXT.FINAL_LIQEXT_CABECERA_FILE LIQ
                    INNER JOIN EXT.FINAL_EXTRACTPAGOS_FILE PAGEXT ON RPAD(PAGEXT.PER_CIF_NIF,10, ' ') = (
                            CASE WHEN LENGTH(LIQ.DOC_NIF) = 9 THEN RPAD(SUBSTR(LIQ.DOC_NIF,1,9),10,' ') ELSE RPAD(SUBSTR(LIQ.DOC_NIF,2,9),10,' ') END)
                        AND PAGEXT.CIA_CODIGO = LIQ.COMPANIA
                        AND substr(PAGEXT.CONCEP_CODIGO,3,1) = LIQ.TIPODOCUMENTO
                        AND PAGEXT.PAG_OFICINA = SUBSTR(LIQ.POSICION_COMERCIAL,1,4) 
                        AND PAGEXT.PAG_AGENTE = SUBSTR(LIQ.POSICION_COMERCIAL,5,6)
                        AND PAGEXT.PERIODSEQ = LIQ.PERIODSEQ
                        AND TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN) = TRIM(LIQ.PAG_REFERENCIA_ORIGEN)
                    WHERE LIQ.DOC_NIF IS NOT NULL
                        AND SUBSTR(LIQ.COD_CONCEPTO,1,1) IN ('6','8') 
                        AND PAGEXT.PERIODSEQ = v_periodSeq
                    GROUP BY
                        PAGEXT.CIA_CODIGO,
                        RPAD(PAGEXT.PER_CIF_NIF,10,' '),
                        CAST(CASE WHEN EXTRACT(YEAR FROM v_PeriodStartDate) > '2021' AND SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 3, 4) > '2021'
                            THEN RPAD(( SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 1, 2) || SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 5, 11) || '/' || RIGHT( '0' || PAGEXT.SECUENCIAL, 2)) ,23,' ')
                            ELSE RPAD(PAGEXT.PAG_REFERENCIA_ORIGEN,23,' ')
                        END AS VARCHAR(23)),
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1),
                        SUBSTR(PAGEXT.PAG_FECHA_LIQUIDACION,1,6),
                        PAGEXT.PAG_OFICINA,
                        PAGEXT.PAG_AGENTE,
                        RPAD(PAGEXT.PAG_COD_UNICO,14,' '),
                        PAGEXT.PAG_CLASIF_AGENTE,
                        SUBSTR(PAGEXT.PAG_FECHA_FACTURA,7,2) || SUBSTR(PAGEXT.PAG_FECHA_FACTURA,5,2) || SUBSTR(PAGEXT.PAG_FECHA_FACTURA,1,4),
                        LPAD(FLOOR(ABS(PAGEXT.DC_IMPORTE30)),2,'0')||','||LPAD((ABS(MOD(ROUND(PAGEXT.DC_IMPORTE30,2),1)*100)),2,'0'),
                        RPAD(LIQ.COD_CONCEPTO,3,' '),
                        CAST(SUBSTR(LIQ.POSICION_COMERCIAL,1,4) AS VARCHAR(4)),
                        (CASE WHEN LIQ.PRODUCTO IS NULL OR LIQ.PRODUCTO = '00000' THEN RPAD(' ',5) ELSE LIQ.PRODUCTO END),
                        RPAD(PAGEXT.ENVIO_SII,1,' '),
                        (CASE WHEN PAGEXT.ENVIO_SII = 'S' AND PAGEXT.SERCO_CANARIAS IS NULL THEN 'S' ELSE ' ' END),
                        (CASE WHEN PAGEXT.ENVIO_SII = 'S' AND PAGEXT.SERCO_CANARIAS = 'C' THEN 'S' ELSE ' ' END)
                    
                    UNION ALL

                    SELECT 'GA' AS TIPO_REGISTRO,
                        PAGEXT.CIA_CODIGO,
                        RPAD(PAGEXT.PER_CIF_NIF,10,' ') AS PER_CIF_NIF,
                        CAST(CASE WHEN EXTRACT(YEAR FROM v_PeriodStartDate) > '2021' AND SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 3, 4) > '2021'
                            THEN RPAD(( SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 1, 2) || SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 5, 11) || '/' || RIGHT( '0' || PAGEXT.SECUENCIAL, 2)) ,23,' ')
                            ELSE RPAD(PAGEXT.PAG_REFERENCIA_ORIGEN,23,' ')
                        END AS VARCHAR(23)) AS PAG_REFERENCIA_ORIGEN,
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1) AS TIPO_PAGO,
                        SUBSTR(PAGEXT.PAG_FECHA_LIQUIDACION,1,6) AS CARGO_LIQUIDACION,
                        PAGEXT.PAG_OFICINA,
                        PAGEXT.PAG_AGENTE,
                        RPAD(PAGEXT.PAG_COD_UNICO,14,' ') AS PAG_COD_UNICO,
                        PAGEXT.PAG_CLASIF_AGENTE,
                        SUBSTR(PAGEXT.PAG_FECHA_FACTURA,7,2) || SUBSTR(PAGEXT.PAG_FECHA_FACTURA,5,2) || SUBSTR(PAGEXT.PAG_FECHA_FACTURA,1,4) AS PAG_FECHA_FACTURA,
                        LPAD(FLOOR(ABS(PAGEXT.DC_IMPORTE30)),2,'0')||','||LPAD((ABS(MOD(ROUND(PAGEXT.DC_IMPORTE30,2),1)*100)),2,'0') AS IRPF,
                        'EUR' AS MONEDA,
                                    
                        --LIQEXT
                        --ALM 20220525: Por peticion de Mariano, se incluye la modificacion de conceptos de pago tambien para el ficihero de SAP.
                        --SUBSTR(REP.EARNINGCODEID,1,3) AS COD_CONCEPTO,
                        (CASE WHEN CC.CONCEPTO_PAGO IS NOT NULL AND CC.TIPO_AGENTE IS NOT NULL
                            --ALM 20220318: Para los agentes de asistencia hay que usar ademas de la tipologia el programa de pago. 
                            THEN (CASE WHEN CC.CONCEPTO_CONTABLE = '151'
                                    THEN (CASE WHEN REP.PROGRAMA = 'MACB101P' THEN '151' ELSE '152'END)
                                    ELSE SUBSTR(CC.CONCEPTO_CONTABLE,1,3)
                                END)
                            ELSE SUBSTR(REP.EARNINGCODEID,1,3) 
                        END) AS COD_CONCEPTO,
                        CAST(SUBSTR(REP.POS_PRIN,1,4) AS VARCHAR(4)) AS OFICINA_GASTO,
                        --(CASE WHEN REP.PRODUCTID IS NULL OR REP.PRODUCTID = '00000' THEN RPAD(' ',5) ELSE REP.PRODUCTID END) AS PRODUCTO,
                        SUBSTR(REP.PRODUCTID, 3, 5) AS PRODUCTO,
                        -- RPAD(TRUNC(ABS(ROUND(SUM(REP.IMPORTE),2))) || LPAD((ABS(MOD(ROUND(SUM(REP.IMPORTE),2),1)*100)),2,'0'),16,' ') AS IMPORTE_COMISION,
                        RPAD(CAST(ABS(ROUND(SUM(REP.IMPORTE),2))AS INTEGER) || LPAD((ABS(MOD(ROUND(SUM(REP.IMPORTE),2),1)*100)),2,'0'),16,' ') AS IMPORTE_COMISION,
                        (CASE WHEN SUM(REP.IMPORTE) >= 0 THEN 'D' ELSE 'H' END) AS CARGO_ABONO,
                        
                        RPAD(PAGEXT.ENVIO_SII,1,' ') AS AUTORIZA_FACTURA,
                        (CASE WHEN PAGEXT.ENVIO_SII = 'S' AND PAGEXT.SERCO_CANARIAS IS NULL THEN 'S' ELSE ' ' END) AS ENVIAR_SII_AEAT,
                        (CASE WHEN PAGEXT.ENVIO_SII = 'S' AND PAGEXT.SERCO_CANARIAS = 'C' THEN 'S' ELSE ' ' END) AS ENVIAR_SII_ATC,
                                    
                        --PAGEXT
                        RPAD(' ',16) AS PAG_IMPORTE,
                        RPAD(' ',1) AS SIGNO_PAG_IMPORTE,
                        RPAD(' ',16) AS AUT_IMPORTE,
                        RPAD(' ',1) AS SIGNO_AUT_IMPORTE,
                        RPAD(' ',1) AS VIA_PAGO,
                        RPAD(' ',1) AS ESTADO,
                        RPAD(' ',8) AS FECHA_ESTADO,
                        RPAD(' ',24) AS IBAN
                    FROM EXT.FINAL_REPEXT_FILE REP
                    INNER JOIN EXT.FINAL_EXTRACTPAGOS_FILE PAGEXT ON TRIM(PAGEXT.PER_CIF_NIF) = REP.NIF
                        AND PAGEXT.CIA_CODIGO = SUBSTR(REP.EARNINGGROUPID,7,2)
                        --ALM 20220323: Usamos el nuevo campo TIPO_DOCUMENTO para poder diferenciar pagos del cierre y de la LC.
                        --ALM 20230208: El campo CONCEP_CODIGO no tiene en cuenta el cambio de la LC.
                        AND SUBSTR(PAGEXT.CONCEP_CODIGO,3,1) = SUBSTR(REP.EARNINGGROUPID,5,1)
                        --AND SUBSTR(PAGEXT.CONCEP_CODIGO,3,1) = REP.TIPO_DOCUMENTO
                        AND PAGEXT.PAG_OFICINA = SUBSTR(REP.POS_PRIN,1,4) 
                        AND PAGEXT.PAG_AGENTE = SUBSTR(REP.POS_PRIN,5,6)
                        AND PAGEXT.PERIODSEQ = REP.PERIODSEQ
                        --ALM 20220323: Usamos el nuevo campo TIPO_DOCUMENTO para poder diferenciar pagos del cierre y de la LC.
                        --AND TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN) = SUBSTR(REP.EARNINGGROUPID,8,1) || SUBSTR(REP.EARNINGGROUPID,5,1) || 
                        AND TRIM(PAGEXT.PAG_REFERENCIA_ORIGEN) = SUBSTR(REP.EARNINGGROUPID,8,1) || REP.TIPO_DOCUMENTO || 
                                                                 --EXTRACT(YEAR FROM REP.COMPENSATIONDATE) || SUBSTR('0' || EXTRACT(MONTH FROM REP.COMPENSATIONDATE),-2) ||
                                                                 EXTRACT(YEAR FROM v_PeriodStartDate) || RIGHT('0' || EXTRACT(MONTH FROM v_PeriodStartDate),2) ||
                                                                 SUBSTR(REP.POS_PRIN,2,3) || SUBSTR(REP.POS_PRIN,7,4)
                    --ALM 20220525: Por peticion de Mariano, se incluye la modificacion de conceptos de pago tambien para el ficihero de SAP.
                    LEFT JOIN EXT.CONF_REPEXT_CONCEPTOS_CONTABLES_FILE CC ON TRIM(CC.CONCEPTO_PAGO) = (CASE WHEN SUBSTR(REP.EARNINGCODEID,1,3) = '410' THEN '404' ELSE SUBSTR(REP.EARNINGCODEID,1,3) END)
                    -- LFC 20251121;	AND TRIM(CC.TIPO_AGENTE) = TO_CHAR(SUBSTR(REP.TIPO_AGENTE,1,3))
                    --AND TRIM(CC.TIPO_AGENTE) = TO_CHAR(FLOOR(REP.TIPO_AGENTE))
					AND TRIM(CC.TIPO_AGENTE) = FLOOR(TO_VARCHAR(REP.TIPO_AGENTE))
					WHERE PAGEXT.PERIODSEQ = v_periodSeq 
                    GROUP BY
                        PAGEXT.CIA_CODIGO,
                        RPAD(PAGEXT.PER_CIF_NIF,10,' '),
                        CAST(CASE WHEN EXTRACT(YEAR FROM v_PeriodStartDate) > '2021' AND SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 3, 4) > '2021'
                            THEN RPAD(( SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 1, 2) || SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN, 5, 11) || '/' || RIGHT( '0' || PAGEXT.SECUENCIAL, 2)) ,23,' ')
                            ELSE RPAD(PAGEXT.PAG_REFERENCIA_ORIGEN,23,' ')
                        END AS VARCHAR(23)),
                        SUBSTR(PAGEXT.PAG_REFERENCIA_ORIGEN,2,1),
                        SUBSTR(PAGEXT.PAG_FECHA_LIQUIDACION,1,6),
                        PAGEXT.PAG_OFICINA,
                        PAGEXT.PAG_AGENTE,
                        RPAD(PAGEXT.PAG_COD_UNICO,14,' '),
                        PAGEXT.PAG_CLASIF_AGENTE,
                        SUBSTR(PAGEXT.PAG_FECHA_FACTURA,7,2) || SUBSTR(PAGEXT.PAG_FECHA_FACTURA,5,2) || SUBSTR(PAGEXT.PAG_FECHA_FACTURA,1,4),
                        LPAD(FLOOR(ABS(PAGEXT.DC_IMPORTE30)),2,'0')||','||LPAD((ABS(MOD(ROUND(PAGEXT.DC_IMPORTE30,2),1)*100)),2,'0'),
                        --ALM 20220525: Por peticion de Mariano, se incluye la modificacion de conceptos de pago tambien para el ficihero de SAP.
                        --SUBSTR(REP.EARNINGCODEID,1,3),
                        (CASE WHEN CC.CONCEPTO_PAGO IS NOT NULL AND CC.TIPO_AGENTE IS NOT NULL
                            --ALM 20220318: Para los agentes de asistencia hay que usar ademas de la tipologia el programa de pago. 
                            THEN (CASE WHEN CC.CONCEPTO_CONTABLE = '151'
                                    THEN (CASE WHEN REP.PROGRAMA = 'MACB101P' THEN '151' ELSE '152'END)
                                    ELSE SUBSTR(CC.CONCEPTO_CONTABLE,1,3)
                                END)
                            ELSE SUBSTR(REP.EARNINGCODEID,1,3) 
                        END),
                        CAST(SUBSTR(REP.POS_PRIN,1,4) AS VARCHAR(4)),
                        REP.PRODUCTID,
                        RPAD(PAGEXT.ENVIO_SII,1,' '),
                        (CASE WHEN PAGEXT.ENVIO_SII = 'S' AND PAGEXT.SERCO_CANARIAS IS NULL THEN 'S' ELSE ' ' END),
                        (CASE WHEN PAGEXT.ENVIO_SII = 'S' AND PAGEXT.SERCO_CANARIAS = 'C' THEN 'S' ELSE ' ' END)
                    ORDER BY 3,4,1,14

                ) PAGOS;
            
            v_num_rows = ::ROWCOUNT;   
            -- COMMIT;
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Carga de la tabla FINAL_REPEXT_INF_SAP_FILE: '|| to_char(v_num_rows) || ' filas.', v_log_count, v_idproceso, 'info');
        
        

            --JGE 20230802: Genera fichero inspectores reglados   
            ----------------------------EXT.FINAL_REPEXT_INR_SAP_FILE----------------------------
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Borrado de la tabla FINAL_REPEXT_INR_SAP_FILE.', v_log_count, v_idproceso, 'info');
            
            DELETE FROM EXT.FINAL_REPEXT_INR_SAP_FILE WHERE PERIODSEQ = v_periodSeq;
            
            v_num_rows = ::ROWCOUNT;              
            COMMIT;
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Borrado de la tabla FINAL_REPEXT_INR_SAP_FILE: ' || to_char(::ROWCOUNT) || ' filas borradas.', v_log_count, v_idproceso, 'info');
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Inicio Carga de la tabla FINAL_REPEXT_INR_SAP_FILE.', v_log_count, v_idproceso, 'info');
            
            INSERT INTO EXT.FINAL_REPEXT_INR_SAP_FILE(PERIODSEQ,LINE)
                SELECT  v_periodSeq AS PERIODSEQ,
                        CIA ||
                        TIPO_DOCUMENTO ||
                        FECHA_CARGO ||  
                        CODIGO_AGENTE  || 
                        COD_CONCEPTO ||      
                        PRODUCTO ||            
                        CASE WHEN IMPORTE >= 0 THEN '+' ELSE '-' END || LPAD(floor(abs(ROUND(IMPORTE,2))),9,'0') ||','|| LPAD(( abs(mod(ROUND(IMPORTE,2),1)*100) ),2,'0') ||           
                        PROGRAMA || 
                        NIF AS LINE
                FROM(
                        --ALM 20230213: Usamos un HINT para mejorar el rendimiento y que primero ejecute esta subconsulta
                        SELECT 
                            LPAD(SUBSTR(PRODUCTID, 1, 2),2,'0') AS CIA,
                            TIPO_DOCUMENTO,
                            --ALM 20230213: Por peticion de Pedro Fernandez devolvemos siempre la fecha del cargo.
                            --              Por lo que no podemos usar la COMPENSATIONDATE ya que puede haber polizas anteriores dependiendo del reparto utilizado.
                            --TO_CHAR(COMPENSATIONDATE,'YYYYMM') AS FECHA_CARGO,
                            TO_CHAR(v_PeriodStartDate,'YYYYMM') AS FECHA_CARGO,
                            LPAD(IFNULL(POS_PRIN,'0'),10,'0')  AS CODIGO_AGENTE, 
                            --SUBSTR(earningcodeid,1,3) AS COD_CONCEPTO,   
                            (CASE WHEN CC.CONCEPTO_PAGO IS NOT NULL AND CC.TIPO_AGENTE IS NOT NULL
                                THEN (CASE WHEN CC.CONCEPTO_CONTABLE = '151'
                                        THEN (CASE WHEN R.PROGRAMA = 'MACB101P' THEN '151' ELSE '152'END)
                                        ELSE SUBSTR(CC.CONCEPTO_CONTABLE,1,3)
                                END)
                                ELSE SUBSTR(R.EARNINGCODEID,1,3) 
                            END) AS COD_CONCEPTO,
                            CASE WHEN SUBSTR(PRODUCTID, 3, 5)   is null THEN '00000' else LPAD(SUBSTR(PRODUCTID, 3, 5) ,5,'0')    end AS PRODUCTO,         
                            SUM(IMPORTE) AS IMPORTE,   
                            CASE WHEN PROGRAMA is NULL THEN '        ' ELSE RPAD(PROGRAMA,8,' ') END AS PROGRAMA,
                            RPAD(NIF,11,' ') AS NIF
                        FROM EXT.FINAL_REPEXT_FILE R
                                INNER JOIN TCMP.CS_PARTICIPANT P
                                ON R.PARTICIPANTSEQ = P.PAYEESEQ 
                                AND P.TENANTID = v_idtenant
                                AND (P.TERMINATIONDATE IS NULL OR P.TERMINATIONDATE > v_fecha_reparto)
                                AND P.CREATEDATE < v_fecha_reparto
                                AND P.REMOVEDATE > v_fecha_reparto
                                AND P.EFFECTIVESTARTDATE <=  ADD_DAYS(v_periodEndDate,-1)
                                AND P.EFFECTIVEENDDATE >  ADD_DAYS(v_periodEndDate,-1)
                        LEFT JOIN EXT.CONF_REPEXT_CONCEPTOS_CONTABLES_FILE CC ON TRIM(CC.CONCEPTO_PAGO) = (CASE WHEN SUBSTR(R.EARNINGCODEID,1,3) = '410' THEN '404' ELSE SUBSTR(R.EARNINGCODEID,1,3) END)
                            --SMM 20251120    AND TRIM(CC.TIPO_AGENTE) = TO_CHAR(SUBSTR(R.TIPO_AGENTE,1,3))
							--AND TRIM(CC.TIPO_AGENTE) = TO_CHAR(FLOOR(R.TIPO_AGENTE))
							AND TRIM(CC.TIPO_AGENTE) = FLOOR(TO_VARCHAR(R.TIPO_AGENTE))
                        WHERE R.PERIODSEQ = v_periodSeq
                                AND SUBSTR(R.EARNINGGROUPID,5,1) = '5'
                                AND P.GENERICNUMBER4 <> 0
                                --AND SUBSTR(PRODUCTID, 1, 2) IN ('01', '03')
                        GROUP BY LPAD(SUBSTR(PRODUCTID, 1, 2),2,'0'),
                            TIPO_DOCUMENTO,
                            --TO_CHAR(COMPENSATIONDATE,'YYYYMM'),
                            LPAD(IFNULL(POS_PRIN,'0'),10,'0'), 
                            --SUBSTR(earningcodeid,1,3),   
                            (CASE WHEN CC.CONCEPTO_PAGO IS NOT NULL AND CC.TIPO_AGENTE IS NOT NULL
                                THEN (CASE WHEN CC.CONCEPTO_CONTABLE = '151'
                                        THEN (CASE WHEN R.PROGRAMA = 'MACB101P' THEN '151' ELSE '152'END)
                                        ELSE SUBSTR(CC.CONCEPTO_CONTABLE,1,3)
                                    END)
                                ELSE SUBSTR(R.EARNINGCODEID,1,3) 
                            END),
                            CASE WHEN SUBSTR(PRODUCTID, 3, 5)   is null THEN '00000' else LPAD(SUBSTR(PRODUCTID, 3, 5) ,5,'0')    end,            
                            CASE WHEN PROGRAMA is NULL THEN '        ' ELSE RPAD(PROGRAMA,8,' ') END ,
                            RPAD(NIF,11,' ')
                ) X
                
                --JGE 20230208: comentamos order by para mejorar rendimiento
                --ORDER BY CIA, CODIGO_AGENTE, TIPO_DOCUMENTO, COD_CONCEPTO, PRODUCTO     
                ;

            v_num_rows = ::ROWCOUNT;     
            -- COMMIT;
            
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin Carga de la tabla FINAL_REPEXT_INR_SAP_FILE: '|| to_char(v_num_rows) || ' filas.', v_log_count, v_idproceso, 'info');

        END IF;
        
        --Volvemos a cambiar el estado de la tabla de control para permitir modificaciones en el Workflow.
       
        
        --Volvemos a poner el estado a 1 del control del REPEXT del periodo para que se puedan volver a realizar modificaciones o dar el visto bueno.
        UPDATE EXT.CONF_REPEXT_CONTROL_FILE
        SET ESTADO = 1
        WHERE PERIODSEQ = v_periodSeq;
            
        COMMIT;
            
        CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Actualizacion del estado en la tabla de control: 1', v_log_count, v_idproceso, 'info');
        

		--Llamada al procedimiento CDA. Si es la primera ejecución --> CDAPRO
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Llamada al procedimiento CDAINF', v_log_count, v_idproceso, 'info');
        CALL EXT.SP_CDAINF_OC(FILENAME,:i_fechaliquidacion||';'||:i_par_tipo_ejecucion);

        IF v_flag_error = c_correccion_error THEN
        	CALL EXT.LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name , 'Error en CORRECCION. No se encontró un registro. Registros con error: ' || v_c_correccion_cont_error 
        	||' v_c_correccion_periodseq = ' || v_c_correccion_periodseq_error || ' - v_c_correccion_ofi: ' || v_c_correccion_ofi_error
					       || ' v_c_correccion_age: ' || v_c_correccion_age_error || ' v_c_correccion_nif: ' || v_c_correccion_nif_error || ' v_c_correccion_tipo_doc: ' || v_c_correccion_tipo_doc_error || ' v_c_correccion_cia: ' || v_c_correccion_cia_error 
					       , v_log_count, v_idproceso, 'error');
					       
        	CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin del proceso con ERRORES.', v_log_count, v_idproceso, 'info');
        	
        	UPDATE
            	EXT.OUT_BATCH_CONTROL
        	SET
            	STATUS = v_const_out_batch_control_error,
            	FILE_NAME = FILENAME,
            	TARGET_ROWS = v_num_rows,
            	END_DATE = CURRENT_TIMESTAMP
        	WHERE
            	ID_PROCESO = v_idproceso;
            	
        ELSE
        	
        	
        	CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Fin del proceso.', v_log_count, v_idproceso, 'info');
        	
        	UPDATE EXT.OUT_BATCH_CONTROL
			SET STATUS = v_const_out_batch_control_ok,
				FILE_NAME = FILENAME,
				TARGET_ROWS = v_num_rows,
				END_DATE = CURRENT_TIMESTAMP
			WHERE  ID_PROCESO = v_idproceso;
            	
        END IF;
        
        
        
    -- EXCEPTION
    --     WHEN HAY_ERROR THEN
    --         --Volvemos a poner el estado a 1 del control del REPEXT del periodo para que se puedan volver a realizar modificaciones o dar el visto bueno.
    --         UPDATE EXT.CONF_REPEXT_CONTROL_FILE
