    --         CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Actualizacion del estado en la tabla de control: 1', v_log_count, v_idproceso, 'info');
    --         CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'Error: ' || v_DesError || ' -- : SQLCOD(' || SQLCODE || ') ' ||SQLERRM, v_log_count, v_idproceso, 'info');
    --         RETURN;        
        
        

END